    // Auto-record all event bus messages to the audit log
    for topic in &["agent.task", "agent.result", "agent.health", "agent.scale"] {
        let log = audit_log.clone();
        let topic_owned = topic.to_string();
        let _ = event_bus.subscribe(topic, move |_topic, payload| {
            if let Ok(text) = std::str::from_utf8(payload) {
                if let Ok(json) = serde_json::from_str::<serde_json::Value>(text) {
                    audit_record(&log, &topic_owned, json);
                }
            }
        });
    }
