/// Multi-round consensus protocol among agents.
#[derive(Clone, Debug)]
struct CpVote {
    agent: String,
    approve: bool,
    reason: String,
}

#[derive(Clone, Debug)]
enum CpOutcome {
    Pending,
    Committed,
    Aborted,
}

#[derive(Clone, Debug)]
struct CpRound {
    id: String,
    proposal: String,
    quorum: usize,
    votes: Vec<CpVote>,
    outcome: CpOutcome,
}

struct CpProtocol {
    rounds: Vec<CpRound>,
}

impl CpProtocol {
    fn new() -> Self {
        Self { rounds: Vec::new() }
    }

    fn propose(&mut self, id: &str, proposal: &str, quorum: usize) {
        self.rounds.push(CpRound {
            id: id.to_string(),
            proposal: proposal.to_string(),
            quorum,
            votes: Vec::new(),
            outcome: CpOutcome::Pending,
        });
    }

    fn vote(&mut self, round_id: &str, agent: &str, approve: bool, reason: &str) -> bool {
        if let Some(r) = self.rounds.iter_mut().find(|r| r.id == round_id) {
            if matches!(r.outcome, CpOutcome::Pending) {
                if !r.votes.iter().any(|v| v.agent == agent) {
                    r.votes.push(CpVote {
                        agent: agent.to_string(),
                        approve,
                        reason: reason.to_string(),
                    });
                    return true;
                }
            }
        }
        false
    }

    fn resolve(&mut self, round_id: &str) -> Option<CpOutcome> {
        if let Some(r) = self.rounds.iter_mut().find(|r| r.id == round_id) {
            if matches!(r.outcome, CpOutcome::Pending) {
                let approvals = r.votes.iter().filter(|v| v.approve).count();
                if approvals >= r.quorum {
                    r.outcome = CpOutcome::Committed;
                } else if r.votes.len() >= r.quorum {
                    r.outcome = CpOutcome::Aborted;
                }
            }
            Some(r.outcome.clone())
        } else {
            None
        }
    }

    fn status(&self, round_id: &str) -> Option<&CpRound> {
        self.rounds.iter().find(|r| r.id == round_id)
    }

    fn list(&self) -> Vec<String> {
        self.rounds.iter().map(|r| r.id.clone()).collect()
    }
}

type SharedCpProtocol = Arc<std::sync::Mutex<CpProtocol>>;

/// DAG-based task dependency graph with topological sort.
#[derive(Clone, Debug)]
struct DepNode {
    id: String,
    label: String,
    done: bool,
}

#[derive(Clone, Debug)]
struct DepEdge {
    from: String,
    to: String,
}

struct TaskDepGraph {
    nodes: Vec<DepNode>,
    edges: Vec<DepEdge>,
}

impl TaskDepGraph {
    fn new() -> Self {
        Self { nodes: Vec::new(), edges: Vec::new() }
    }

    fn add_node(&mut self, id: &str, label: &str) {
        if !self.nodes.iter().any(|n| n.id == id) {
            self.nodes.push(DepNode {
                id: id.to_string(),
                label: label.to_string(),
                done: false,
            });
        }
    }

    fn add_edge(&mut self, from: &str, to: &str) -> bool {
        if self.nodes.iter().any(|n| n.id == from) && self.nodes.iter().any(|n| n.id == to) {
            self.edges.push(DepEdge { from: from.to_string(), to: to.to_string() });
            // Check for cycle
            if self.has_cycle() {
                self.edges.pop();
                return false;
            }
            true
        } else {
            false
        }
    }

    fn has_cycle(&self) -> bool {
        // Kahn's algorithm — if topo sort doesn't include all nodes, there's a cycle
        let mut in_deg: std::collections::HashMap<&str, usize> = std::collections::HashMap::new();
        for n in &self.nodes { in_deg.insert(&n.id, 0); }
        for e in &self.edges { *in_deg.entry(&e.to).or_insert(0) += 1; }
        let mut queue: Vec<&str> = in_deg.iter().filter(|(_, &d)| d == 0).map(|(&k, _)| k).collect();
        let mut count = 0;
        while let Some(n) = queue.pop() {
            count += 1;
            for e in &self.edges {
                if e.from == n {
                    let d = in_deg.get_mut(e.to.as_str()).unwrap();
                    *d -= 1;
                    if *d == 0 { queue.push(&e.to); }
                }
            }
        }
        count != self.nodes.len()
    }

    fn topo_sort(&self) -> Vec<String> {
        let mut in_deg: std::collections::HashMap<&str, usize> = std::collections::HashMap::new();
        for n in &self.nodes { in_deg.insert(&n.id, 0); }
        for e in &self.edges { *in_deg.entry(&e.to).or_insert(0) += 1; }
        let mut queue: std::collections::VecDeque<&str> = in_deg.iter().filter(|(_, &d)| d == 0).map(|(&k, _)| k).collect();
        let mut result = Vec::new();
        while let Some(n) = queue.pop_front() {
            result.push(n.to_string());
            for e in &self.edges {
                if e.from == n {
                    let d = in_deg.get_mut(e.to.as_str()).unwrap();
                    *d -= 1;
                    if *d == 0 { queue.push_back(&e.to); }
                }
            }
        }
        result
    }

    fn ready_set(&self) -> Vec<String> {
        // Nodes whose dependencies are all done
        let mut result = Vec::new();
        for n in &self.nodes {
            if n.done { continue; }
            let deps: Vec<&str> = self.edges.iter().filter(|e| e.to == n.id).map(|e| e.from.as_str()).collect();
            if deps.iter().all(|d| self.nodes.iter().any(|nd| nd.id == *d && nd.done)) {
                result.push(n.id.clone());
            }
        }
        result
    }

    fn mark_done(&mut self, id: &str) -> bool {
        if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
            n.done = true;
            true
        } else {
            false
        }
    }

    fn list(&self) -> Vec<String> {
        self.nodes.iter().map(|n| format!("{} [{}] {}", n.id, if n.done { "done" } else { "pending" }, n.label)).collect()
    }
}

type SharedTaskDepGraph = Arc<std::sync::Mutex<TaskDepGraph>>;

/// Isolated sandbox environments for agent execution.
#[derive(Clone, Debug)]
struct AgentSandboxPolicy {
    max_memory_mb: u64,
    max_cpu_ms: u64,
    allowed_ops: Vec<String>,
}

#[derive(Clone, Debug)]
struct AgentSandbox {
    id: String,
    agent: String,
    policy: AgentSandboxPolicy,
    violations: Vec<String>,
    active: bool,
}

struct AgentSandboxRegistry {
    sandboxes: Vec<AgentSandbox>,
}

impl AgentSandboxRegistry {
    fn new() -> Self {
        Self { sandboxes: Vec::new() }
    }

    fn create(&mut self, id: &str, agent: &str, policy: AgentSandboxPolicy) {
        self.sandboxes.push(AgentSandbox {
            id: id.to_string(),
            agent: agent.to_string(),
            policy,
            violations: Vec::new(),
            active: true,
        });
    }

    fn check_op(&mut self, sandbox_id: &str, op: &str) -> bool {
        if let Some(sb) = self.sandboxes.iter_mut().find(|s| s.id == sandbox_id && s.active) {
            if sb.policy.allowed_ops.contains(&op.to_string()) {
                true
            } else {
                sb.violations.push(format!("denied: {}", op));
                false
            }
        } else {
            false
        }
    }

    fn violations(&self, sandbox_id: &str) -> Vec<String> {
        self.sandboxes.iter().find(|s| s.id == sandbox_id).map(|s| s.violations.clone()).unwrap_or_default()
    }

    fn deactivate(&mut self, sandbox_id: &str) -> bool {
        if let Some(sb) = self.sandboxes.iter_mut().find(|s| s.id == sandbox_id) {
            sb.active = false;
            true
        } else {
            false
        }
    }

    fn list(&self) -> Vec<String> {
        self.sandboxes.iter().map(|s| format!("{} agent={} active={} violations={}", s.id, s.agent, s.active, s.violations.len())).collect()
    }
}

type SharedAgentSandboxRegistry = Arc<std::sync::Mutex<AgentSandboxRegistry>>;

/// Configurable retry strategy engine with backoff.
#[derive(Clone, Debug)]
struct RetryStrategyPolicy {
    max_attempts: u32,
    base_delay_ms: u64,
    backoff_multiplier: f64,
    jitter: bool,
}

#[derive(Clone, Debug)]
struct RetryStrategyAttempt {
    attempt: u32,
    delay_ms: u64,
    error: String,
}

struct RetryStrategyEngine {
    policies: std::collections::HashMap<String, RetryStrategyPolicy>,
    history: std::collections::HashMap<String, Vec<RetryStrategyAttempt>>,
}

impl RetryStrategyEngine {
    fn new() -> Self {
        Self {
            policies: std::collections::HashMap::new(),
            history: std::collections::HashMap::new(),
        }
    }

    fn register(&mut self, op: &str, policy: RetryStrategyPolicy) {
        self.policies.insert(op.to_string(), policy);
    }

    fn record_attempt(&mut self, op: &str, attempt: u32, error: &str) -> Option<u64> {
        let policy = self.policies.get(op)?;
        if attempt >= policy.max_attempts {
            return None; // exhausted
        }
        let mut delay = (policy.base_delay_ms as f64 * policy.backoff_multiplier.powi(attempt as i32)) as u64;
        if policy.jitter {
            delay = delay.wrapping_add(delay / 10); // simple deterministic jitter
        }
        let att = RetryStrategyAttempt { attempt, delay_ms: delay, error: error.to_string() };
        self.history.entry(op.to_string()).or_default().push(att);
        Some(delay)
    }

    fn attempts(&self, op: &str) -> Vec<&RetryStrategyAttempt> {
        self.history.get(op).map(|v| v.iter().collect()).unwrap_or_default()
    }

    fn exhausted(&self, op: &str) -> bool {
        if let (Some(policy), Some(hist)) = (self.policies.get(op), self.history.get(op)) {
            hist.len() as u32 >= policy.max_attempts
        } else {
            false
        }
    }

    fn list(&self) -> Vec<String> {
        self.policies.keys().cloned().collect()
    }
}

type SharedRetryStrategyEngine = Arc<std::sync::Mutex<RetryStrategyEngine>>;

/// Structured changelog tracker for agent actions.
#[derive(Clone, Debug)]
enum ChangeKind {
    Create,
    Update,
    Delete,
    Config,
}

impl std::fmt::Display for ChangeKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ChangeKind::Create => write!(f, "create"),
            ChangeKind::Update => write!(f, "update"),
            ChangeKind::Delete => write!(f, "delete"),
            ChangeKind::Config => write!(f, "config"),
        }
    }
}

#[derive(Clone, Debug)]
struct ChangeEntry {
    seq: u64,
    agent: String,
    kind: ChangeKind,
    target: String,
    summary: String,
    rollback: bool,
}

struct ChangelogTracker {
    entries: Vec<ChangeEntry>,
    next_seq: u64,
}

impl ChangelogTracker {
    fn new() -> Self {
        Self { entries: Vec::new(), next_seq: 1 }
    }

    fn record(&mut self, agent: &str, kind: ChangeKind, target: &str, summary: &str) -> u64 {
        let seq = self.next_seq;
        self.next_seq += 1;
        self.entries.push(ChangeEntry {
            seq,
            agent: agent.to_string(),
            kind,
            target: target.to_string(),
            summary: summary.to_string(),
            rollback: false,
        });
        seq
    }

    fn mark_rollback(&mut self, seq: u64) -> bool {
        if let Some(e) = self.entries.iter_mut().find(|e| e.seq == seq) {
            e.rollback = true;
            true
        } else {
            false
        }
    }

    fn by_agent(&self, agent: &str) -> Vec<&ChangeEntry> {
        self.entries.iter().filter(|e| e.agent == agent).collect()
    }

    fn by_target(&self, target: &str) -> Vec<&ChangeEntry> {
        self.entries.iter().filter(|e| e.target == target).collect()
    }

    fn rollbacks(&self) -> Vec<&ChangeEntry> {
        self.entries.iter().filter(|e| e.rollback).collect()
    }

    fn list(&self, limit: usize) -> Vec<String> {
        self.entries.iter().rev().take(limit).map(|e| {
            format!("#{} [{}] {} {} → {} {}", e.seq, e.kind, e.agent, e.target, e.summary, if e.rollback { "(rolled back)" } else { "" })
        }).collect()
    }
}

type SharedChangelogTracker = Arc<std::sync::Mutex<ChangelogTracker>>;

