/// Sliding-window rate counter per agent/resource.
#[derive(Clone, Debug)]
struct RateWindow {
    agent: String,
    resource: String,
    window_secs: u64,
    timestamps: Vec<u64>,
    limit: usize,
    cooldown_until: u64,
}

struct RateWindowTracker {
    windows: Vec<RateWindow>,
    clock: u64, // virtual clock for testing
}

impl RateWindowTracker {
    fn new() -> Self {
        Self { windows: Vec::new(), clock: 0 }
    }

    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn register(&mut self, agent: &str, resource: &str, window_secs: u64, limit: usize) {
        self.windows.push(RateWindow {
            agent: agent.to_string(),
            resource: resource.to_string(),
            window_secs,
            timestamps: Vec::new(),
            limit,
            cooldown_until: 0,
        });
    }

    fn record(&mut self, agent: &str, resource: &str) -> bool {
        let clock = self.clock;
        if let Some(w) = self.windows.iter_mut().find(|w| w.agent == agent && w.resource == resource) {
            if clock < w.cooldown_until {
                return false; // in cooldown
            }
            w.timestamps.retain(|&t| clock.saturating_sub(t) < w.window_secs);
            if w.timestamps.len() >= w.limit {
                w.cooldown_until = clock + w.window_secs; // burst → cooldown
                return false;
            }
            w.timestamps.push(clock);
            true
        } else {
            false
        }
    }

    fn count(&self, agent: &str, resource: &str) -> usize {
        if let Some(w) = self.windows.iter().find(|w| w.agent == agent && w.resource == resource) {
            let clock = self.clock;
            w.timestamps.iter().filter(|&&t| clock.saturating_sub(t) < w.window_secs).count()
        } else {
            0
        }
    }

    fn in_cooldown(&self, agent: &str, resource: &str) -> bool {
        self.windows.iter().find(|w| w.agent == agent && w.resource == resource)
            .map(|w| self.clock < w.cooldown_until).unwrap_or(false)
    }

    fn list(&self) -> Vec<String> {
        self.windows.iter().map(|w| format!("{}/{} limit={} window={}s", w.agent, w.resource, w.limit, w.window_secs)).collect()
    }
}

type SharedRateWindowTracker = Arc<std::sync::Mutex<RateWindowTracker>>;

/// Layered configuration overlay.
#[derive(Clone, Debug)]
enum OverlayValue {
    Str(String),
    Num(f64),
    Bool(bool),
}

impl std::fmt::Display for OverlayValue {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            OverlayValue::Str(s) => write!(f, "{}", s),
            OverlayValue::Num(n) => write!(f, "{}", n),
            OverlayValue::Bool(b) => write!(f, "{}", b),
        }
    }
}

#[derive(Clone, Debug)]
struct OverlayLayer {
    name: String,
    priority: u32,
    entries: std::collections::HashMap<String, OverlayValue>,
}

struct ConfigOverlay {
    layers: Vec<OverlayLayer>,
}

impl ConfigOverlay {
    fn new() -> Self {
        Self { layers: Vec::new() }
    }

    fn add_layer(&mut self, name: &str, priority: u32) {
        self.layers.push(OverlayLayer {
            name: name.to_string(),
            priority,
            entries: std::collections::HashMap::new(),
        });
        self.layers.sort_by_key(|l| l.priority);
    }

    fn set(&mut self, layer: &str, key: &str, value: OverlayValue) -> bool {
        if let Some(l) = self.layers.iter_mut().find(|l| l.name == layer) {
            l.entries.insert(key.to_string(), value);
            true
        } else {
            false
        }
    }

    fn get(&self, key: &str) -> Option<&OverlayValue> {
        // highest priority layer wins
        for layer in self.layers.iter().rev() {
            if let Some(v) = layer.entries.get(key) {
                return Some(v);
            }
        }
        None
    }

    fn diff(&self, layer_a: &str, layer_b: &str) -> Vec<(String, Option<String>, Option<String>)> {
        let la = self.layers.iter().find(|l| l.name == layer_a);
        let lb = self.layers.iter().find(|l| l.name == layer_b);
        let mut all_keys: std::collections::HashSet<String> = std::collections::HashSet::new();
        if let Some(a) = la { all_keys.extend(a.entries.keys().cloned()); }
        if let Some(b) = lb { all_keys.extend(b.entries.keys().cloned()); }
        let mut result = Vec::new();
        for k in all_keys {
            let va = la.and_then(|l| l.entries.get(&k)).map(|v| format!("{}", v));
            let vb = lb.and_then(|l| l.entries.get(&k)).map(|v| format!("{}", v));
            if va != vb {
                result.push((k, va, vb));
            }
        }
        result
    }

    fn list(&self) -> Vec<String> {
        self.layers.iter().map(|l| format!("{} (priority={}, keys={})", l.name, l.priority, l.entries.len())).collect()
    }
}

type SharedConfigOverlay = Arc<std::sync::Mutex<ConfigOverlay>>;

/// Parameterized workflow template engine.
#[derive(Clone, Debug)]
struct WfTplStep {
    name: String,
    action: String,
    done: bool,
}

#[derive(Clone, Debug)]
struct WfTplTemplate {
    id: String,
    description: String,
    params: Vec<String>,
    steps: Vec<WfTplStep>,
}

struct WfTplEngine {
    templates: Vec<WfTplTemplate>,
    instances: Vec<(String, WfTplTemplate)>, // (instance_id, instantiated template)
    next_id: u64,
}

impl WfTplEngine {
    fn new() -> Self {
        Self { templates: Vec::new(), instances: Vec::new(), next_id: 1 }
    }

    fn register(&mut self, id: &str, description: &str, params: Vec<String>, steps: Vec<(String, String)>) {
        self.templates.push(WfTplTemplate {
            id: id.to_string(),
            description: description.to_string(),
            params,
            steps: steps.into_iter().map(|(name, action)| WfTplStep { name, action, done: false }).collect(),
        });
    }

    fn instantiate(&mut self, template_id: &str, vars: &std::collections::HashMap<String, String>) -> Option<String> {
        let tpl = self.templates.iter().find(|t| t.id == template_id)?;
        let mut instance = tpl.clone();
        let inst_id = format!("wf-{}", self.next_id);
        self.next_id += 1;
        // Substitute variables in step actions
        for step in &mut instance.steps {
            for (k, v) in vars {
                step.action = step.action.replace(&format!("{{{{{}}}}}", k), v);
            }
        }
        self.instances.push((inst_id.clone(), instance));
        Some(inst_id)
    }

    fn advance(&mut self, instance_id: &str) -> Option<String> {
        if let Some((_, inst)) = self.instances.iter_mut().find(|(id, _)| id == instance_id) {
            if let Some(step) = inst.steps.iter_mut().find(|s| !s.done) {
                step.done = true;
                return Some(step.name.clone());
            }
        }
        None
    }

    fn progress(&self, instance_id: &str) -> Option<(usize, usize)> {
        self.instances.iter().find(|(id, _)| id == instance_id).map(|(_, inst)| {
            let done = inst.steps.iter().filter(|s| s.done).count();
            (done, inst.steps.len())
        })
    }

    fn list_templates(&self) -> Vec<String> {
        self.templates.iter().map(|t| format!("{}: {}", t.id, t.description)).collect()
    }

    fn list_instances(&self) -> Vec<String> {
        self.instances.iter().map(|(id, inst)| {
            let done = inst.steps.iter().filter(|s| s.done).count();
            format!("{} ({}/{} steps)", id, done, inst.steps.len())
        }).collect()
    }
}

type SharedWfTplEngine = Arc<std::sync::Mutex<WfTplEngine>>;

/// Agent lineage (parent-child spawn) tracker.
#[derive(Clone, Debug)]
struct AgentLineageNode {
    id: String,
    parent: Option<String>,
    depth: usize,
}

#[derive(Clone, Debug)]
struct AgentLineageEdge {
    parent: String,
    child: String,
}

struct AgentLineageTracker {
    nodes: Vec<AgentLineageNode>,
    edges: Vec<AgentLineageEdge>,
    max_depth: usize,
}

impl AgentLineageTracker {
    fn new(max_depth: usize) -> Self {
        Self { nodes: Vec::new(), edges: Vec::new(), max_depth }
    }

    fn register_root(&mut self, id: &str) {
        if !self.nodes.iter().any(|n| n.id == id) {
            self.nodes.push(AgentLineageNode { id: id.to_string(), parent: None, depth: 0 });
        }
    }

    fn spawn(&mut self, parent: &str, child: &str) -> Result<(), String> {
        let parent_depth = self.nodes.iter().find(|n| n.id == parent)
            .map(|n| n.depth).ok_or_else(|| "parent not found".to_string())?;
        if parent_depth + 1 > self.max_depth {
            return Err("max depth exceeded".to_string());
        }
        if self.nodes.iter().any(|n| n.id == child) {
            return Err("child already exists".to_string());
        }
        self.nodes.push(AgentLineageNode {
            id: child.to_string(),
            parent: Some(parent.to_string()),
            depth: parent_depth + 1,
        });
        self.edges.push(AgentLineageEdge { parent: parent.to_string(), child: child.to_string() });
        Ok(())
    }

    fn children(&self, id: &str) -> Vec<String> {
        self.edges.iter().filter(|e| e.parent == id).map(|e| e.child.clone()).collect()
    }

    fn orphans(&self) -> Vec<String> {
        self.nodes.iter().filter(|n| {
            if let Some(ref p) = n.parent {
                !self.nodes.iter().any(|nd| nd.id == *p)
            } else {
                false
            }
        }).map(|n| n.id.clone()).collect()
    }

    fn depth(&self, id: &str) -> Option<usize> {
        self.nodes.iter().find(|n| n.id == id).map(|n| n.depth)
    }

    fn list(&self) -> Vec<String> {
        self.nodes.iter().map(|n| format!("{} depth={} parent={}", n.id, n.depth, n.parent.as_deref().unwrap_or("none"))).collect()
    }
}

type SharedAgentLineageTracker = Arc<std::sync::Mutex<AgentLineageTracker>>;

/// Time-bucketed metric aggregation.
#[derive(Clone, Debug)]
enum AggType {
    Sum,
    Avg,
    Min,
    Max,
    Count,
}

#[derive(Clone, Debug)]
struct MetricBucket {
    name: String,
    agg: AggType,
    values: Vec<f64>,
    window_start: u64,
    window_secs: u64,
}

struct MetricAggregator {
    buckets: Vec<MetricBucket>,
    clock: u64,
}

impl MetricAggregator {
    fn new() -> Self {
        Self { buckets: Vec::new(), clock: 0 }
    }

    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn create_bucket(&mut self, name: &str, agg: AggType, window_secs: u64) {
        self.buckets.push(MetricBucket {
            name: name.to_string(),
            agg,
            values: Vec::new(),
            window_start: self.clock,
            window_secs,
        });
    }

    fn record(&mut self, name: &str, value: f64) {
        if let Some(b) = self.buckets.iter_mut().find(|b| b.name == name) {
            // Rollup if window expired
            if self.clock.saturating_sub(b.window_start) >= b.window_secs {
                b.values.clear();
                b.window_start = self.clock;
            }
            b.values.push(value);
        }
    }

    fn aggregate(&self, name: &str) -> Option<f64> {
        let b = self.buckets.iter().find(|b| b.name == name)?;
        if b.values.is_empty() { return None; }
        Some(match b.agg {
            AggType::Sum => b.values.iter().sum(),
            AggType::Avg => b.values.iter().sum::<f64>() / b.values.len() as f64,
            AggType::Min => b.values.iter().cloned().fold(f64::INFINITY, f64::min),
            AggType::Max => b.values.iter().cloned().fold(f64::NEG_INFINITY, f64::max),
            AggType::Count => b.values.len() as f64,
        })
    }

    fn list(&self) -> Vec<String> {
        self.buckets.iter().map(|b| format!("{} agg={:?} values={} window={}s", b.name, b.agg, b.values.len(), b.window_secs)).collect()
    }
}

type SharedMetricAggregator = Arc<std::sync::Mutex<MetricAggregator>>;

