/// Content-hash deduplication engine.
#[derive(Clone, Debug)]
struct DedupRecord {
    hash: u64,
    first_seen: u64,
    count: u64,
}

struct DedupEngine {
    entries: std::collections::HashMap<u64, DedupRecord>,
    clock: u64,
}

impl DedupEngine {
    fn new() -> Self {
        Self { entries: std::collections::HashMap::new(), clock: 0 }
    }

    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn hash_content(content: &[u8]) -> u64 {
        let mut h: u64 = 14695981039346656037;
        for &b in content {
            h = h.wrapping_mul(1099511628211);
            h ^= b as u64;
        }
        h
    }

    fn check(&mut self, content: &[u8]) -> bool {
        let h = Self::hash_content(content);
        if let Some(entry) = self.entries.get_mut(&h) {
            entry.count += 1;
            true // duplicate
        } else {
            self.entries.insert(h, DedupRecord { hash: h, first_seen: self.clock, count: 1 });
            false // new
        }
    }

    fn stats(&self) -> (usize, u64) {
        let total_dupes: u64 = self.entries.values().map(|e| e.count.saturating_sub(1)).sum();
        (self.entries.len(), total_dupes)
    }

    fn list(&self) -> Vec<String> {
        self.entries.values().map(|e| format!("hash={:#x} seen={} first_at={}", e.hash, e.count, e.first_seen)).collect()
    }
}

type SharedDedupEngine = Arc<std::sync::Mutex<DedupEngine>>;

/// Agent capability negotiation.
#[derive(Clone, Debug)]
struct CapOfferEntry {
    agent: String,
    capability: String,
    level: u32,
}

#[derive(Clone, Debug)]
struct CapDemandEntry {
    agent: String,
    capability: String,
    min_level: u32,
}

struct CapNegEngine {
    offers: Vec<CapOfferEntry>,
    demands: Vec<CapDemandEntry>,
}

impl CapNegEngine {
    fn new() -> Self {
        Self { offers: Vec::new(), demands: Vec::new() }
    }

    fn offer(&mut self, agent: &str, capability: &str, level: u32) {
        self.offers.push(CapOfferEntry { agent: agent.to_string(), capability: capability.to_string(), level });
    }

    fn demand(&mut self, agent: &str, capability: &str, min_level: u32) {
        self.demands.push(CapDemandEntry { agent: agent.to_string(), capability: capability.to_string(), min_level });
    }

    fn match_pairs(&self) -> Vec<(String, String, String)> {
        let mut result = Vec::new();
        for d in &self.demands {
            for o in &self.offers {
                if o.capability == d.capability && o.level >= d.min_level && o.agent != d.agent {
                    result.push((d.agent.clone(), o.agent.clone(), d.capability.clone()));
                }
            }
        }
        result
    }

    fn unmet_demands(&self) -> Vec<String> {
        self.demands.iter().filter(|d| {
            !self.offers.iter().any(|o| o.capability == d.capability && o.level >= d.min_level && o.agent != d.agent)
        }).map(|d| format!("{} needs {} (min_level={})", d.agent, d.capability, d.min_level)).collect()
    }

    fn list(&self) -> Vec<String> {
        let mut r: Vec<String> = self.offers.iter().map(|o| format!("OFFER: {} → {} (lvl={})", o.agent, o.capability, o.level)).collect();
        r.extend(self.demands.iter().map(|d| format!("DEMAND: {} ← {} (min={})", d.agent, d.capability, d.min_level)));
        r
    }
}

type SharedCapNegEngine = Arc<std::sync::Mutex<CapNegEngine>>;

/// Cron-style job scheduler.
#[derive(Clone, Debug)]
struct CronTrigger {
    interval_secs: u64,
}

#[derive(Clone, Debug)]
struct CronJob {
    id: String,
    description: String,
    trigger: CronTrigger,
    enabled: bool,
    last_run: u64,
    run_count: u64,
}

struct CronScheduler {
    jobs: Vec<CronJob>,
    clock: u64,
}

impl CronScheduler {
    fn new() -> Self {
        Self { jobs: Vec::new(), clock: 0 }
    }

    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn add(&mut self, id: &str, description: &str, interval_secs: u64) {
        self.jobs.push(CronJob {
            id: id.to_string(),
            description: description.to_string(),
            trigger: CronTrigger { interval_secs },
            enabled: true,
            last_run: 0,
            run_count: 0,
        });
    }

    fn toggle(&mut self, id: &str) -> Option<bool> {
        if let Some(j) = self.jobs.iter_mut().find(|j| j.id == id) {
            j.enabled = !j.enabled;
            Some(j.enabled)
        } else {
            None
        }
    }

    fn due_jobs(&self) -> Vec<String> {
        self.jobs.iter().filter(|j| {
            j.enabled && (self.clock.saturating_sub(j.last_run) >= j.trigger.interval_secs)
        }).map(|j| j.id.clone()).collect()
    }

    fn run(&mut self, id: &str) -> bool {
        if let Some(j) = self.jobs.iter_mut().find(|j| j.id == id) {
            j.last_run = self.clock;
            j.run_count += 1;
            true
        } else {
            false
        }
    }

    fn list(&self) -> Vec<String> {
        self.jobs.iter().map(|j| format!("{} [{}] interval={}s runs={}", j.id, if j.enabled { "on" } else { "off" }, j.trigger.interval_secs, j.run_count)).collect()
    }
}

type SharedCronScheduler = Arc<std::sync::Mutex<CronScheduler>>;

/// Access control matrix.
#[derive(Clone, Debug, PartialEq)]
enum AclPermission {
    Allow,
    Deny,
}

#[derive(Clone, Debug)]
struct AclEntry {
    subject: String,
    resource: String,
    permission: AclPermission,
    granted_at: u64,
}

struct AclMatrix {
    entries: Vec<AclEntry>,
    audit: Vec<String>,
    clock: u64,
}

impl AclMatrix {
    fn new() -> Self {
        Self { entries: Vec::new(), audit: Vec::new(), clock: 0 }
    }

    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn grant(&mut self, subject: &str, resource: &str) {
        self.entries.retain(|e| !(e.subject == subject && e.resource == resource));
        self.entries.push(AclEntry {
            subject: subject.to_string(),
            resource: resource.to_string(),
            permission: AclPermission::Allow,
            granted_at: self.clock,
        });
        self.audit.push(format!("t={} GRANT {} → {}", self.clock, subject, resource));
    }

    fn revoke(&mut self, subject: &str, resource: &str) {
        self.entries.retain(|e| !(e.subject == subject && e.resource == resource));
        self.audit.push(format!("t={} REVOKE {} → {}", self.clock, subject, resource));
    }

    fn check(&self, subject: &str, resource: &str) -> bool {
        self.entries.iter().any(|e| e.subject == subject && e.resource == resource && e.permission == AclPermission::Allow)
    }

    fn audit_log(&self, limit: usize) -> Vec<String> {
        self.audit.iter().rev().take(limit).cloned().collect()
    }

    fn list(&self) -> Vec<String> {
        self.entries.iter().map(|e| format!("{} → {} {:?}", e.subject, e.resource, e.permission)).collect()
    }
}

type SharedAclMatrix = Arc<std::sync::Mutex<AclMatrix>>;

/// Multi-stage processing pipeline.
#[derive(Clone, Debug)]
struct PipeStage {
    name: String,
    status: String, // "pending", "running", "done", "skipped", "failed"
}

#[derive(Clone, Debug)]
struct PipeRun {
    id: String,
    stages: Vec<PipeStage>,
}

struct PipelineBuilder {
    templates: std::collections::HashMap<String, Vec<String>>,
    runs: Vec<PipeRun>,
    next_id: u64,
}

impl PipelineBuilder {
    fn new() -> Self {
        Self { templates: std::collections::HashMap::new(), runs: Vec::new(), next_id: 1 }
    }

    fn define(&mut self, name: &str, stages: Vec<String>) {
        self.templates.insert(name.to_string(), stages);
    }

    fn start(&mut self, template: &str) -> Option<String> {
        let stages = self.templates.get(template)?;
        let id = format!("pipe-{}", self.next_id);
        self.next_id += 1;
        self.runs.push(PipeRun {
            id: id.clone(),
            stages: stages.iter().map(|s| PipeStage { name: s.clone(), status: "pending".to_string() }).collect(),
        });
        Some(id)
    }

    fn advance(&mut self, run_id: &str) -> Option<String> {
        if let Some(run) = self.runs.iter_mut().find(|r| r.id == run_id) {
            if let Some(stage) = run.stages.iter_mut().find(|s| s.status == "pending") {
                stage.status = "done".to_string();
                return Some(stage.name.clone());
            }
        }
        None
    }

    fn skip(&mut self, run_id: &str, stage_name: &str) -> bool {
        if let Some(run) = self.runs.iter_mut().find(|r| r.id == run_id) {
            if let Some(stage) = run.stages.iter_mut().find(|s| s.name == stage_name && s.status == "pending") {
                stage.status = "skipped".to_string();
                return true;
            }
        }
        false
    }

    fn progress(&self, run_id: &str) -> Option<(usize, usize)> {
        self.runs.iter().find(|r| r.id == run_id).map(|r| {
            let done = r.stages.iter().filter(|s| s.status == "done" || s.status == "skipped").count();
            (done, r.stages.len())
        })
    }

    fn list(&self) -> Vec<String> {
        self.runs.iter().map(|r| {
            let done = r.stages.iter().filter(|s| s.status == "done" || s.status == "skipped").count();
            format!("{} ({}/{})", r.id, done, r.stages.len())
        }).collect()
    }
}

type SharedPipelineBuilder = Arc<std::sync::Mutex<PipelineBuilder>>;

