/// Per-agent token budget tracking.
#[derive(Clone, Debug)]
struct TokenBudget {
    agent: String,
    total: u64,
    spent: u64,
}

struct TokenBudgetTracker {
    budgets: Vec<TokenBudget>,
}

impl TokenBudgetTracker {
    fn new() -> Self { Self { budgets: Vec::new() } }

    fn allocate(&mut self, agent: &str, total: u64) {
        self.budgets.push(TokenBudget { agent: agent.to_string(), total, spent: 0 });
    }

    fn spend(&mut self, agent: &str, amount: u64) -> Result<u64, String> {
        if let Some(b) = self.budgets.iter_mut().find(|b| b.agent == agent) {
            if b.spent + amount > b.total {
                return Err(format!("overage: {} + {} > {}", b.spent, amount, b.total));
            }
            b.spent += amount;
            Ok(b.total - b.spent)
        } else {
            Err("agent not found".to_string())
        }
    }

    fn refund(&mut self, agent: &str, amount: u64) -> bool {
        if let Some(b) = self.budgets.iter_mut().find(|b| b.agent == agent) {
            b.spent = b.spent.saturating_sub(amount);
            true
        } else {
            false
        }
    }

    fn remaining(&self, agent: &str) -> Option<u64> {
        self.budgets.iter().find(|b| b.agent == agent).map(|b| b.total.saturating_sub(b.spent))
    }

    fn list(&self) -> Vec<String> {
        self.budgets.iter().map(|b| format!("{}: {}/{} spent", b.agent, b.spent, b.total)).collect()
    }
}

type SharedTokenBudgetTracker = Arc<std::sync::Mutex<TokenBudgetTracker>>;

/// Versioned schema registry.
#[derive(Clone, Debug)]
struct SchemaVer {
    version: u32,
    fields: Vec<String>,
}

#[derive(Clone, Debug)]
struct SchemaRegEntry {
    name: String,
    versions: Vec<SchemaVer>,
}

struct SchemaReg {
    schemas: Vec<SchemaRegEntry>,
}

impl SchemaReg {
    fn new() -> Self { Self { schemas: Vec::new() } }

    fn register(&mut self, name: &str, fields: Vec<String>) -> u32 {
        if let Some(entry) = self.schemas.iter_mut().find(|s| s.name == name) {
            let ver = entry.versions.len() as u32 + 1;
            entry.versions.push(SchemaVer { version: ver, fields });
            ver
        } else {
            self.schemas.push(SchemaRegEntry {
                name: name.to_string(),
                versions: vec![SchemaVer { version: 1, fields }],
            });
            1
        }
    }

    fn latest(&self, name: &str) -> Option<&SchemaVer> {
        self.schemas.iter().find(|s| s.name == name).and_then(|s| s.versions.last())
    }

    fn compatible(&self, name: &str, v1: u32, v2: u32) -> Option<bool> {
        let entry = self.schemas.iter().find(|s| s.name == name)?;
        let s1 = entry.versions.iter().find(|v| v.version == v1)?;
        let s2 = entry.versions.iter().find(|v| v.version == v2)?;
        Some(s1.fields.iter().all(|f| s2.fields.contains(f)))
    }

    fn list(&self) -> Vec<String> {
        self.schemas.iter().map(|s| format!("{} (versions={})", s.name, s.versions.len())).collect()
    }
}

type SharedSchemaReg = Arc<std::sync::Mutex<SchemaReg>>;

/// Shared/exclusive lock manager.
#[derive(Clone, Debug, PartialEq)]
enum LockMode {
    Shared,
    Exclusive,
}

#[derive(Clone, Debug)]
struct LockEntry {
    resource: String,
    holder: String,
    mode: LockMode,
}

struct LockMgr {
    locks: Vec<LockEntry>,
}

impl LockMgr {
    fn new() -> Self { Self { locks: Vec::new() } }

    fn acquire(&mut self, resource: &str, holder: &str, mode: LockMode) -> bool {
        let existing: Vec<&LockEntry> = self.locks.iter().filter(|l| l.resource == resource).collect();
        match &mode {
            LockMode::Exclusive => {
                if !existing.is_empty() { return false; }
            }
            LockMode::Shared => {
                if existing.iter().any(|l| l.mode == LockMode::Exclusive) { return false; }
            }
        }
        self.locks.push(LockEntry { resource: resource.to_string(), holder: holder.to_string(), mode });
        true
    }

    fn release(&mut self, resource: &str, holder: &str) -> bool {
        let before = self.locks.len();
        self.locks.retain(|l| !(l.resource == resource && l.holder == holder));
        self.locks.len() < before
    }

    fn held_by(&self, holder: &str) -> Vec<String> {
        self.locks.iter().filter(|l| l.holder == holder).map(|l| format!("{} ({:?})", l.resource, l.mode)).collect()
    }

    fn list(&self) -> Vec<String> {
        self.locks.iter().map(|l| format!("{} → {} ({:?})", l.resource, l.holder, l.mode)).collect()
    }
}

type SharedLockMgr = Arc<std::sync::Mutex<LockMgr>>;

/// Multi-channel notification hub.
#[derive(Clone, Debug)]
enum NotifSeverity {
    Info,
    Warning,
    Critical,
}

impl std::fmt::Display for NotifSeverity {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            NotifSeverity::Info => write!(f, "info"),
            NotifSeverity::Warning => write!(f, "warn"),
            NotifSeverity::Critical => write!(f, "crit"),
        }
    }
}

#[derive(Clone, Debug)]
struct NotifMessage {
    channel: String,
    severity: NotifSeverity,
    text: String,
    seq: u64,
}

struct NotifHub {
    channels: Vec<String>,
    messages: Vec<NotifMessage>,
    next_seq: u64,
}

impl NotifHub {
    fn new() -> Self {
        Self { channels: Vec::new(), messages: Vec::new(), next_seq: 1 }
    }

    fn add_channel(&mut self, name: &str) {
        if !self.channels.contains(&name.to_string()) {
            self.channels.push(name.to_string());
        }
    }

    fn send(&mut self, channel: &str, severity: NotifSeverity, text: &str) -> Option<u64> {
        if !self.channels.contains(&channel.to_string()) { return None; }
        let seq = self.next_seq;
        self.next_seq += 1;
        self.messages.push(NotifMessage {
            channel: channel.to_string(), severity, text: text.to_string(), seq,
        });
        Some(seq)
    }

    fn by_channel(&self, channel: &str) -> Vec<&NotifMessage> {
        self.messages.iter().filter(|m| m.channel == channel).collect()
    }

    fn critical_count(&self) -> usize {
        self.messages.iter().filter(|m| matches!(m.severity, NotifSeverity::Critical)).count()
    }

    fn list(&self, limit: usize) -> Vec<String> {
        self.messages.iter().rev().take(limit).map(|m| {
            format!("#{} [{}] {} — {}", m.seq, m.severity, m.channel, m.text)
        }).collect()
    }
}

type SharedNotifHub = Arc<std::sync::Mutex<NotifHub>>;

/// Shared resource pool with leasing.
#[derive(Clone, Debug)]
struct PoolSlot {
    id: String,
    leased_to: Option<String>,
}

struct QuotaPool {
    name: String,
    slots: Vec<PoolSlot>,
}

impl QuotaPool {
    fn new(name: &str, capacity: usize) -> Self {
        let slots = (0..capacity).map(|i| PoolSlot { id: format!("{}-{}", name, i), leased_to: None }).collect();
        Self { name: name.to_string(), slots }
    }

    fn lease(&mut self, agent: &str) -> Option<String> {
        if let Some(slot) = self.slots.iter_mut().find(|s| s.leased_to.is_none()) {
            slot.leased_to = Some(agent.to_string());
            Some(slot.id.clone())
        } else {
            None
        }
    }

    fn release(&mut self, slot_id: &str) -> bool {
        if let Some(slot) = self.slots.iter_mut().find(|s| s.id == slot_id) {
            slot.leased_to = None;
            true
        } else {
            false
        }
    }

    fn available(&self) -> usize {
        self.slots.iter().filter(|s| s.leased_to.is_none()).count()
    }

    fn utilization(&self) -> f64 {
        let used = self.slots.iter().filter(|s| s.leased_to.is_some()).count();
        used as f64 / self.slots.len() as f64
    }

    fn list(&self) -> Vec<String> {
        self.slots.iter().map(|s| {
            format!("{}: {}", s.id, s.leased_to.as_deref().unwrap_or("free"))
        }).collect()
    }
}

struct QuotaPoolRegistry {
    pools: Vec<QuotaPool>,
}

impl QuotaPoolRegistry {
    fn new() -> Self { Self { pools: Vec::new() } }

    fn create(&mut self, name: &str, capacity: usize) {
        self.pools.push(QuotaPool::new(name, capacity));
    }

    fn lease(&mut self, pool: &str, agent: &str) -> Option<String> {
        self.pools.iter_mut().find(|p| p.name == pool).and_then(|p| p.lease(agent))
    }

    fn release(&mut self, pool: &str, slot_id: &str) -> bool {
        self.pools.iter_mut().find(|p| p.name == pool).map(|p| p.release(slot_id)).unwrap_or(false)
    }

    fn stats(&self, pool: &str) -> Option<(usize, f64)> {
        self.pools.iter().find(|p| p.name == pool).map(|p| (p.available(), p.utilization()))
    }

    fn list(&self) -> Vec<String> {
        self.pools.iter().map(|p| format!("{}: {}/{} available", p.name, p.available(), p.slots.len())).collect()
    }
}

type SharedQuotaPoolRegistry = Arc<std::sync::Mutex<QuotaPoolRegistry>>;

