/// Canary deployment with staged rollout.
#[derive(Clone, Debug, PartialEq)]
enum CanaryState { Pending, Canary, Full, RolledBack }

#[derive(Clone, Debug)]
struct CanaryDeploy {
    id: String,
    version: String,
    traffic_pct: u32,
    state: CanaryState,
    errors: u32,
    rollback_threshold: u32,
}

struct CanaryDeployer {
    deploys: Vec<CanaryDeploy>,
}

impl CanaryDeployer {
    fn new() -> Self { Self { deploys: Vec::new() } }

    fn create(&mut self, id: &str, version: &str, rollback_threshold: u32) {
        self.deploys.push(CanaryDeploy {
            id: id.to_string(), version: version.to_string(),
            traffic_pct: 0, state: CanaryState::Pending, errors: 0, rollback_threshold,
        });
    }

    fn promote(&mut self, id: &str, pct: u32) -> Option<CanaryState> {
        let d = self.deploys.iter_mut().find(|d| d.id == id)?;
        if d.state == CanaryState::RolledBack { return Some(d.state.clone()); }
        d.traffic_pct = pct;
        d.state = if pct >= 100 { CanaryState::Full } else { CanaryState::Canary };
        Some(d.state.clone())
    }

    fn report_error(&mut self, id: &str) -> Option<bool> {
        let d = self.deploys.iter_mut().find(|d| d.id == id)?;
        d.errors += 1;
        if d.errors >= d.rollback_threshold {
            d.state = CanaryState::RolledBack;
            d.traffic_pct = 0;
            Some(true) // rolled back
        } else {
            Some(false)
        }
    }

    fn status(&self, id: &str) -> Option<&CanaryDeploy> {
        self.deploys.iter().find(|d| d.id == id)
    }

    fn list(&self) -> Vec<String> {
        self.deploys.iter().map(|d| format!("{} v={} traffic={}% {:?} errors={}", d.id, d.version, d.traffic_pct, d.state, d.errors)).collect()
    }
}

type SharedCanaryDeployer = Arc<std::sync::Mutex<CanaryDeployer>>;

/// Data partitioner with consistent hashing.
#[derive(Clone, Debug)]
struct DpShard {
    id: String,
    range_start: u64,
    range_end: u64,
    items: Vec<String>,
}

struct DataPartitioner {
    shards: Vec<DpShard>,
}

impl DataPartitioner {
    fn new() -> Self { Self { shards: Vec::new() } }

    fn create_shards(&mut self, prefix: &str, count: usize) {
        let range_size = u64::MAX / count as u64;
        for i in 0..count {
            self.shards.push(DpShard {
                id: format!("{}-{}", prefix, i),
                range_start: i as u64 * range_size,
                range_end: if i == count - 1 { u64::MAX } else { (i as u64 + 1) * range_size - 1 },
                items: Vec::new(),
            });
        }
    }

    fn hash_key(key: &str) -> u64 {
        let mut h: u64 = 0xcbf29ce484222325;
        for b in key.bytes() { h = h.wrapping_mul(0x100000001b3); h ^= b as u64; }
        h
    }

    fn insert(&mut self, key: &str) -> Option<String> {
        let h = Self::hash_key(key);
        if let Some(shard) = self.shards.iter_mut().find(|s| h >= s.range_start && h <= s.range_end) {
            shard.items.push(key.to_string());
            Some(shard.id.clone())
        } else {
            None
        }
    }

    fn locate(&self, key: &str) -> Option<String> {
        let h = Self::hash_key(key);
        self.shards.iter().find(|s| h >= s.range_start && h <= s.range_end).map(|s| s.id.clone())
    }

    fn list(&self) -> Vec<String> {
        self.shards.iter().map(|s| format!("{}: {} items", s.id, s.items.len())).collect()
    }
}

type SharedDataPartitioner = Arc<std::sync::Mutex<DataPartitioner>>;

/// Incident lifecycle tracker.
#[derive(Clone, Debug, PartialEq)]
enum IncidentSeverity { Low, Medium, High, Critical }

impl std::fmt::Display for IncidentSeverity {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            IncidentSeverity::Low => write!(f, "low"),
            IncidentSeverity::Medium => write!(f, "med"),
            IncidentSeverity::High => write!(f, "high"),
            IncidentSeverity::Critical => write!(f, "crit"),
        }
    }
}

#[derive(Clone, Debug)]
struct Incident {
    id: String,
    title: String,
    severity: IncidentSeverity,
    status: String, // "open", "mitigating", "resolved"
    timeline: Vec<String>,
}

struct IncidentTracker {
    incidents: Vec<Incident>,
}

impl IncidentTracker {
    fn new() -> Self { Self { incidents: Vec::new() } }

    fn open(&mut self, id: &str, title: &str, severity: IncidentSeverity) {
        self.incidents.push(Incident {
            id: id.to_string(), title: title.to_string(), severity,
            status: "open".to_string(), timeline: vec!["opened".to_string()],
        });
    }

    fn update_status(&mut self, id: &str, status: &str) -> bool {
        if let Some(inc) = self.incidents.iter_mut().find(|i| i.id == id) {
            inc.status = status.to_string();
            inc.timeline.push(format!("status → {}", status));
            true
        } else { false }
    }

    fn add_note(&mut self, id: &str, note: &str) -> bool {
        if let Some(inc) = self.incidents.iter_mut().find(|i| i.id == id) {
            inc.timeline.push(note.to_string());
            true
        } else { false }
    }

    fn active(&self) -> Vec<&Incident> {
        self.incidents.iter().filter(|i| i.status != "resolved").collect()
    }

    fn list(&self) -> Vec<String> {
        self.incidents.iter().map(|i| format!("{} [{}] {} — {}", i.id, i.severity, i.status, i.title)).collect()
    }
}

type SharedIncidentTracker = Arc<std::sync::Mutex<IncidentTracker>>;

/// Content-based message router.
#[derive(Clone, Debug)]
struct RouteFilter {
    contains: Option<String>,
    prefix: Option<String>,
}

#[derive(Clone, Debug)]
struct MsgRoute {
    id: String,
    target: String,
    filter: RouteFilter,
    routed_count: u64,
}

struct MsgRouter {
    routes: Vec<MsgRoute>,
    dead_letters: Vec<String>,
}

impl MsgRouter {
    fn new() -> Self { Self { routes: Vec::new(), dead_letters: Vec::new() } }

    fn add_route(&mut self, id: &str, target: &str, filter: RouteFilter) {
        self.routes.push(MsgRoute { id: id.to_string(), target: target.to_string(), filter, routed_count: 0 });
    }

    fn route(&mut self, message: &str) -> Option<String> {
        for r in &mut self.routes {
            let matches = match (&r.filter.contains, &r.filter.prefix) {
                (Some(c), _) => message.contains(c.as_str()),
                (_, Some(p)) => message.starts_with(p.as_str()),
                _ => true,
            };
            if matches {
                r.routed_count += 1;
                return Some(r.target.clone());
            }
        }
        self.dead_letters.push(message.to_string());
        None
    }

    fn dead_letter_count(&self) -> usize { self.dead_letters.len() }

    fn stats(&self) -> Vec<String> {
        self.routes.iter().map(|r| format!("{} → {} (routed={})", r.id, r.target, r.routed_count)).collect()
    }

    fn list(&self) -> Vec<String> {
        self.routes.iter().map(|r| format!("{} → {}", r.id, r.target)).collect()
    }
}

type SharedMsgRouter = Arc<std::sync::Mutex<MsgRouter>>;

/// Agent performance profiler.
#[derive(Clone, Debug)]
struct ProfileSample {
    agent: String,
    latency_ms: f64,
    memory_kb: u64,
    timestamp: u64,
}

struct AgentProfiler {
    samples: Vec<ProfileSample>,
}

impl AgentProfiler {
    fn new() -> Self { Self { samples: Vec::new() } }

    fn sample(&mut self, agent: &str, latency_ms: f64, memory_kb: u64, timestamp: u64) {
        self.samples.push(ProfileSample { agent: agent.to_string(), latency_ms, memory_kb, timestamp });
    }

    fn avg_latency(&self, agent: &str) -> Option<f64> {
        let samples: Vec<f64> = self.samples.iter().filter(|s| s.agent == agent).map(|s| s.latency_ms).collect();
        if samples.is_empty() { return None; }
        Some(samples.iter().sum::<f64>() / samples.len() as f64)
    }

    fn peak_memory(&self, agent: &str) -> Option<u64> {
        self.samples.iter().filter(|s| s.agent == agent).map(|s| s.memory_kb).max()
    }

    fn hotspots(&self, threshold_ms: f64) -> Vec<String> {
        let mut agents: std::collections::HashMap<&str, Vec<f64>> = std::collections::HashMap::new();
        for s in &self.samples { agents.entry(&s.agent).or_default().push(s.latency_ms); }
        agents.iter().filter_map(|(agent, latencies)| {
            let avg = latencies.iter().sum::<f64>() / latencies.len() as f64;
            if avg > threshold_ms { Some(format!("{} avg={:.1}ms", agent, avg)) } else { None }
        }).collect()
    }

    fn list(&self, agent: &str) -> Vec<String> {
        self.samples.iter().filter(|s| s.agent == agent)
            .map(|s| format!("t={} lat={:.1}ms mem={}kb", s.timestamp, s.latency_ms, s.memory_kb)).collect()
    }
}

type SharedAgentProfiler = Arc<std::sync::Mutex<AgentProfiler>>;

