/// Batch job processor.
#[derive(Clone, Debug, PartialEq)]
enum BatchStatus { Pending, Running, Done, PartialFail }

#[derive(Clone, Debug)]
struct BatchJob {
    id: String,
    total: usize,
    completed: usize,
    failed: usize,
    status: BatchStatus,
}

struct BatchProcessor {
    jobs: Vec<BatchJob>,
    next_id: u64,
}

impl BatchProcessor {
    fn new() -> Self { Self { jobs: Vec::new(), next_id: 1 } }

    fn submit(&mut self, total: usize) -> String {
        let id = format!("batch-{}", self.next_id);
        self.next_id += 1;
        self.jobs.push(BatchJob { id: id.clone(), total, completed: 0, failed: 0, status: BatchStatus::Pending });
        id
    }

    fn start(&mut self, id: &str) -> bool {
        if let Some(j) = self.jobs.iter_mut().find(|j| j.id == id && j.status == BatchStatus::Pending) {
            j.status = BatchStatus::Running;
            true
        } else { false }
    }

    fn complete_item(&mut self, id: &str, success: bool) -> Option<(usize, usize)> {
        let j = self.jobs.iter_mut().find(|j| j.id == id)?;
        if success { j.completed += 1; } else { j.failed += 1; }
        if j.completed + j.failed >= j.total {
            j.status = if j.failed > 0 { BatchStatus::PartialFail } else { BatchStatus::Done };
        }
        Some((j.completed, j.total))
    }

    fn progress(&self, id: &str) -> Option<(usize, usize, usize)> {
        self.jobs.iter().find(|j| j.id == id).map(|j| (j.completed, j.failed, j.total))
    }

    fn list(&self) -> Vec<String> {
        self.jobs.iter().map(|j| format!("{} {}/{} failed={} {:?}", j.id, j.completed, j.total, j.failed, j.status)).collect()
    }
}

type SharedBatchProcessor = Arc<std::sync::Mutex<BatchProcessor>>;

/// Encrypted-at-rest secret vault.
#[derive(Clone, Debug)]
struct VaultAccess { agent: String, accessed_at: u64 }

#[derive(Clone, Debug)]
struct VaultEntry {
    key: String,
    value_hash: u64, // we don't store plaintext, just hash for verification
    rotation_count: u32,
    access_log: Vec<VaultAccess>,
}

struct SecretVault {
    entries: Vec<VaultEntry>,
    clock: u64,
}

impl SecretVault {
    fn new() -> Self { Self { entries: Vec::new(), clock: 0 } }
    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn store(&mut self, key: &str, value_hash: u64) {
        self.entries.retain(|e| e.key != key);
        self.entries.push(VaultEntry { key: key.to_string(), value_hash, rotation_count: 0, access_log: Vec::new() });
    }

    fn access(&mut self, key: &str, agent: &str) -> Option<u64> {
        let clock = self.clock;
        let entry = self.entries.iter_mut().find(|e| e.key == key)?;
        entry.access_log.push(VaultAccess { agent: agent.to_string(), accessed_at: clock });
        Some(entry.value_hash)
    }

    fn rotate(&mut self, key: &str, new_hash: u64) -> bool {
        if let Some(e) = self.entries.iter_mut().find(|e| e.key == key) {
            e.value_hash = new_hash;
            e.rotation_count += 1;
            true
        } else { false }
    }

    fn audit(&self, key: &str) -> Vec<String> {
        self.entries.iter().find(|e| e.key == key)
            .map(|e| e.access_log.iter().map(|a| format!("{} at t={}", a.agent, a.accessed_at)).collect())
            .unwrap_or_default()
    }

    fn list(&self) -> Vec<String> {
        self.entries.iter().map(|e| format!("{} rotations={} accesses={}", e.key, e.rotation_count, e.access_log.len())).collect()
    }
}

type SharedSecretVault = Arc<std::sync::Mutex<SecretVault>>;

/// Epidemic-style gossip protocol.
#[derive(Clone, Debug)]
struct AgentGossipMsg {
    from: String,
    key: String,
    value: String,
    generation: u64,
}

struct AgentGossipProto {
    state: std::collections::HashMap<String, (String, u64)>, // key → (value, generation)
    messages: Vec<AgentGossipMsg>,
    generation: u64,
}

impl AgentGossipProto {
    fn new() -> Self { Self { state: std::collections::HashMap::new(), messages: Vec::new(), generation: 0 } }

    fn update(&mut self, from: &str, key: &str, value: &str) {
        self.generation += 1;
        self.state.insert(key.to_string(), (value.to_string(), self.generation));
        self.messages.push(AgentGossipMsg {
            from: from.to_string(), key: key.to_string(), value: value.to_string(), generation: self.generation,
        });
    }

    fn receive(&mut self, msg: &AgentGossipMsg) -> bool {
        if let Some((_, gen)) = self.state.get(&msg.key) {
            if msg.generation <= *gen { return false; } // stale
        }
        self.state.insert(msg.key.clone(), (msg.value.clone(), msg.generation));
        true
    }

    fn get(&self, key: &str) -> Option<&str> {
        self.state.get(key).map(|(v, _)| v.as_str())
    }

    fn converged(&self, other: &AgentGossipProto) -> bool {
        self.state == other.state
    }

    fn list(&self) -> Vec<String> {
        self.state.iter().map(|(k, (v, g))| format!("{} = {} (gen={})", k, v, g)).collect()
    }
}

type SharedAgentGossipProto = Arc<std::sync::Mutex<AgentGossipProto>>;

/// Checkpoint/snapshot manager.
#[derive(Clone, Debug)]
struct CpMetadata {
    label: String,
    size_bytes: u64,
}

#[derive(Clone, Debug)]
struct Checkpoint {
    id: String,
    timestamp: u64,
    data: std::collections::HashMap<String, String>,
    metadata: CpMetadata,
}

struct CheckpointMgr {
    checkpoints: Vec<Checkpoint>,
    next_id: u64,
    clock: u64,
}

impl CheckpointMgr {
    fn new() -> Self { Self { checkpoints: Vec::new(), next_id: 1, clock: 0 } }
    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn save(&mut self, label: &str, data: std::collections::HashMap<String, String>) -> String {
        let id = format!("cp-{}", self.next_id);
        self.next_id += 1;
        let size = data.values().map(|v| v.len() as u64).sum();
        self.checkpoints.push(Checkpoint {
            id: id.clone(), timestamp: self.clock, data,
            metadata: CpMetadata { label: label.to_string(), size_bytes: size },
        });
        id
    }

    fn restore(&self, id: &str) -> Option<&std::collections::HashMap<String, String>> {
        self.checkpoints.iter().find(|c| c.id == id).map(|c| &c.data)
    }

    fn diff(&self, id1: &str, id2: &str) -> Vec<String> {
        let c1 = self.checkpoints.iter().find(|c| c.id == id1);
        let c2 = self.checkpoints.iter().find(|c| c.id == id2);
        match (c1, c2) {
            (Some(a), Some(b)) => {
                let mut diffs = Vec::new();
                for (k, v1) in &a.data {
                    match b.data.get(k) {
                        Some(v2) if v1 != v2 => diffs.push(format!("{}: {} → {}", k, v1, v2)),
                        None => diffs.push(format!("{}: {} → (removed)", k, v1)),
                        _ => {}
                    }
                }
                for k in b.data.keys() {
                    if !a.data.contains_key(k) { diffs.push(format!("{}: (added) → {}", k, b.data[k])); }
                }
                diffs
            }
            _ => Vec::new(),
        }
    }

    fn prune(&mut self, keep: usize) {
        if self.checkpoints.len() > keep {
            let remove = self.checkpoints.len() - keep;
            self.checkpoints.drain(0..remove);
        }
    }

    fn list(&self) -> Vec<String> {
        self.checkpoints.iter().map(|c| format!("{} t={} label={} size={}b", c.id, c.timestamp, c.metadata.label, c.metadata.size_bytes)).collect()
    }
}

type SharedCheckpointMgr = Arc<std::sync::Mutex<CheckpointMgr>>;

/// Agent service mesh.
#[derive(Clone, Debug)]
struct AgentMeshNode {
    id: String,
    service: String,
    healthy: bool,
}

#[derive(Clone, Debug)]
struct AgentMeshLink {
    from: String,
    to: String,
    latency_ms: f64,
}

struct AgentServiceMesh {
    nodes: Vec<AgentMeshNode>,
    links: Vec<AgentMeshLink>,
}

impl AgentServiceMesh {
    fn new() -> Self { Self { nodes: Vec::new(), links: Vec::new() } }

    fn register(&mut self, id: &str, service: &str) {
        if !self.nodes.iter().any(|n| n.id == id) {
            self.nodes.push(AgentMeshNode { id: id.to_string(), service: service.to_string(), healthy: true });
        }
    }

    fn link(&mut self, from: &str, to: &str, latency_ms: f64) {
        self.links.push(AgentMeshLink { from: from.to_string(), to: to.to_string(), latency_ms });
    }

    fn set_health(&mut self, id: &str, healthy: bool) -> bool {
        if let Some(n) = self.nodes.iter_mut().find(|n| n.id == id) {
            n.healthy = healthy;
            true
        } else { false }
    }

    fn discover(&self, service: &str) -> Vec<String> {
        self.nodes.iter().filter(|n| n.service == service && n.healthy).map(|n| n.id.clone()).collect()
    }

    fn route(&self, service: &str) -> Option<String> {
        // Pick lowest-latency healthy node
        let healthy: Vec<&AgentMeshNode> = self.nodes.iter().filter(|n| n.service == service && n.healthy).collect();
        if healthy.is_empty() { return None; }
        // Find node with lowest avg latency from incoming links
        let mut best = healthy[0].id.clone();
        let mut best_lat = f64::MAX;
        for n in &healthy {
            let avg: f64 = {
                let lats: Vec<f64> = self.links.iter().filter(|l| l.to == n.id).map(|l| l.latency_ms).collect();
                if lats.is_empty() { 0.0 } else { lats.iter().sum::<f64>() / lats.len() as f64 }
            };
            if avg < best_lat { best_lat = avg; best = n.id.clone(); }
        }
        Some(best)
    }

    fn list(&self) -> Vec<String> {
        self.nodes.iter().map(|n| format!("{} service={} healthy={}", n.id, n.service, n.healthy)).collect()
    }
}

type SharedAgentServiceMesh = Arc<std::sync::Mutex<AgentServiceMesh>>;

