/// Backfill engine for historical data processing.
#[derive(Clone, Debug, PartialEq)]
enum BackfillState { Pending, Running, Paused, Done }

#[derive(Clone, Debug)]
struct BackfillJob {
    id: String,
    range_start: u64,
    range_end: u64,
    current: u64,
    state: BackfillState,
}

struct BackfillEngine {
    jobs: Vec<BackfillJob>,
    next_id: u64,
}

impl BackfillEngine {
    fn new() -> Self { Self { jobs: Vec::new(), next_id: 1 } }

    fn create(&mut self, start: u64, end: u64) -> String {
        let id = format!("bf-{}", self.next_id);
        self.next_id += 1;
        self.jobs.push(BackfillJob { id: id.clone(), range_start: start, range_end: end, current: start, state: BackfillState::Pending });
        id
    }

    fn start(&mut self, id: &str) -> bool {
        if let Some(j) = self.jobs.iter_mut().find(|j| j.id == id && j.state == BackfillState::Pending) {
            j.state = BackfillState::Running; true
        } else { false }
    }

    fn advance(&mut self, id: &str, amount: u64) -> Option<u64> {
        let j = self.jobs.iter_mut().find(|j| j.id == id && j.state == BackfillState::Running)?;
        j.current = (j.current + amount).min(j.range_end);
        if j.current >= j.range_end { j.state = BackfillState::Done; }
        Some(j.current)
    }

    fn pause(&mut self, id: &str) -> bool {
        if let Some(j) = self.jobs.iter_mut().find(|j| j.id == id && j.state == BackfillState::Running) {
            j.state = BackfillState::Paused; true
        } else { false }
    }

    fn resume(&mut self, id: &str) -> bool {
        if let Some(j) = self.jobs.iter_mut().find(|j| j.id == id && j.state == BackfillState::Paused) {
            j.state = BackfillState::Running; true
        } else { false }
    }

    fn progress(&self, id: &str) -> Option<f64> {
        let j = self.jobs.iter().find(|j| j.id == id)?;
        let range = j.range_end - j.range_start;
        if range == 0 { return Some(100.0); }
        Some((j.current - j.range_start) as f64 / range as f64 * 100.0)
    }

    fn list(&self) -> Vec<String> {
        self.jobs.iter().map(|j| format!("{} [{:?}] {}/{}", j.id, j.state, j.current, j.range_end)).collect()
    }
}

type SharedBackfillEngine = Arc<std::sync::Mutex<BackfillEngine>>;

/// TTL-based capability cache.
#[derive(Clone, Debug)]
struct CapCacheEntry {
    agent: String,
    capability: String,
    cached_at: u64,
    ttl: u64,
}

struct CapCache {
    entries: Vec<CapCacheEntry>,
    clock: u64,
    hits: u64,
    misses: u64,
}

impl CapCache {
    fn new() -> Self { Self { entries: Vec::new(), clock: 0, hits: 0, misses: 0 } }
    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn put(&mut self, agent: &str, capability: &str, ttl: u64) {
        self.entries.retain(|e| !(e.agent == agent && e.capability == capability));
        self.entries.push(CapCacheEntry { agent: agent.to_string(), capability: capability.to_string(), cached_at: self.clock, ttl });
    }

    fn get(&mut self, agent: &str, capability: &str) -> bool {
        let clock = self.clock;
        if let Some(e) = self.entries.iter().find(|e| e.agent == agent && e.capability == capability && clock - e.cached_at < e.ttl) {
            let _ = e;
            self.hits += 1; true
        } else {
            self.misses += 1; false
        }
    }

    fn invalidate(&mut self, agent: &str) {
        self.entries.retain(|e| e.agent != agent);
    }

    fn stats(&self) -> (u64, u64) { (self.hits, self.misses) }

    fn list(&self) -> Vec<String> {
        self.entries.iter().map(|e| format!("{}/{} ttl={}s", e.agent, e.capability, e.ttl)).collect()
    }
}

type SharedCapCache = Arc<std::sync::Mutex<CapCache>>;

/// Bounded event replay buffer with cursors.
#[derive(Clone, Debug)]
struct ReplayEntry {
    seq: u64,
    data: String,
}

struct ReplayBuffer {
    entries: Vec<ReplayEntry>,
    capacity: usize,
    next_seq: u64,
    cursors: std::collections::HashMap<String, u64>, // consumer → last_read_seq
}

impl ReplayBuffer {
    fn new(capacity: usize) -> Self {
        Self { entries: Vec::new(), capacity, next_seq: 1, cursors: std::collections::HashMap::new() }
    }

    fn append(&mut self, data: &str) -> u64 {
        let seq = self.next_seq;
        self.next_seq += 1;
        self.entries.push(ReplayEntry { seq, data: data.to_string() });
        if self.entries.len() > self.capacity { self.entries.remove(0); }
        seq
    }

    fn replay(&self, consumer: &str, limit: usize) -> Vec<&ReplayEntry> {
        let cursor = self.cursors.get(consumer).copied().unwrap_or(0);
        self.entries.iter().filter(|e| e.seq > cursor).take(limit).collect()
    }

    fn ack(&mut self, consumer: &str, seq: u64) {
        self.cursors.insert(consumer.to_string(), seq);
    }

    fn cursor(&self, consumer: &str) -> u64 {
        self.cursors.get(consumer).copied().unwrap_or(0)
    }

    fn list(&self) -> Vec<String> {
        self.entries.iter().map(|e| format!("#{}: {}", e.seq, e.data)).collect()
    }
}

type SharedReplayBuffer = Arc<std::sync::Mutex<ReplayBuffer>>;

/// Priority-weighted routing table.
#[derive(Clone, Debug)]
struct RouteEntry {
    id: String,
    target: String,
    priority: u32,
    healthy: bool,
    requests: u64,
}

struct RoutingTable {
    routes: Vec<RouteEntry>,
}

impl RoutingTable {
    fn new() -> Self { Self { routes: Vec::new() } }

    fn add(&mut self, id: &str, target: &str, priority: u32) {
        self.routes.push(RouteEntry { id: id.to_string(), target: target.to_string(), priority, healthy: true, requests: 0 });
        self.routes.sort_by(|a, b| b.priority.cmp(&a.priority));
    }

    fn resolve(&mut self) -> Option<String> {
        if let Some(r) = self.routes.iter_mut().find(|r| r.healthy) {
            r.requests += 1;
            Some(r.target.clone())
        } else { None }
    }

    fn set_health(&mut self, id: &str, healthy: bool) -> bool {
        if let Some(r) = self.routes.iter_mut().find(|r| r.id == id) {
            r.healthy = healthy; true
        } else { false }
    }

    fn stats(&self) -> Vec<String> {
        self.routes.iter().map(|r| format!("{} → {} prio={} healthy={} reqs={}", r.id, r.target, r.priority, r.healthy, r.requests)).collect()
    }

    fn list(&self) -> Vec<String> {
        self.routes.iter().map(|r| format!("{} → {} (prio={})", r.id, r.target, r.priority)).collect()
    }
}

type SharedRoutingTable = Arc<std::sync::Mutex<RoutingTable>>;

/// External dependency health monitor.
#[derive(Clone, Debug, PartialEq)]
enum DepStatus { Healthy, Degraded, Down }

#[derive(Clone, Debug)]
struct DepHealthEntry {
    name: String,
    status: DepStatus,
    failures: u32,
    threshold: u32,
    recovered: bool,
}

struct DepHealthMon {
    deps: Vec<DepHealthEntry>,
}

impl DepHealthMon {
    fn new() -> Self { Self { deps: Vec::new() } }

    fn register(&mut self, name: &str, threshold: u32) {
        self.deps.push(DepHealthEntry { name: name.to_string(), status: DepStatus::Healthy, failures: 0, threshold, recovered: false });
    }

    fn report_failure(&mut self, name: &str) -> Option<DepStatus> {
        let d = self.deps.iter_mut().find(|d| d.name == name)?;
        d.failures += 1;
        d.recovered = false;
        d.status = if d.failures >= d.threshold { DepStatus::Down } else { DepStatus::Degraded };
        Some(d.status.clone())
    }

    fn report_success(&mut self, name: &str) -> bool {
        if let Some(d) = self.deps.iter_mut().find(|d| d.name == name) {
            d.failures = 0;
            d.status = DepStatus::Healthy;
            d.recovered = true;
            true
        } else { false }
    }

    fn cascade_risk(&self) -> Vec<String> {
        self.deps.iter().filter(|d| d.status == DepStatus::Down).map(|d| d.name.clone()).collect()
    }

    fn list(&self) -> Vec<String> {
        self.deps.iter().map(|d| format!("{} {:?} failures={} recovered={}", d.name, d.status, d.failures, d.recovered)).collect()
    }
}

type SharedDepHealthMon = Arc<std::sync::Mutex<DepHealthMon>>;

