/// Per-agent request throttling.
#[derive(Clone, Debug, PartialEq)]
enum ThrottleState { Normal, Throttled, Blocked }

#[derive(Clone, Debug)]
struct ThrottlePolicy { max_rps: u32, burst: u32 }

struct ThrottleCtrl {
    agents: std::collections::HashMap<String, (ThrottlePolicy, u32, ThrottleState)>, // (policy, current_count, state)
}

impl ThrottleCtrl {
    fn new() -> Self { Self { agents: std::collections::HashMap::new() } }

    fn register(&mut self, agent: &str, max_rps: u32, burst: u32) {
        self.agents.insert(agent.to_string(), (ThrottlePolicy { max_rps, burst }, 0, ThrottleState::Normal));
    }

    fn request(&mut self, agent: &str) -> ThrottleState {
        if let Some((policy, count, state)) = self.agents.get_mut(agent) {
            *count += 1;
            if *count > policy.max_rps + policy.burst {
                *state = ThrottleState::Blocked;
            } else if *count > policy.max_rps {
                *state = ThrottleState::Throttled;
            }
            state.clone()
        } else { ThrottleState::Blocked }
    }

    fn reset(&mut self, agent: &str) {
        if let Some((_, count, state)) = self.agents.get_mut(agent) {
            *count = 0; *state = ThrottleState::Normal;
        }
    }

    fn status(&self, agent: &str) -> Option<ThrottleState> {
        self.agents.get(agent).map(|(_, _, s)| s.clone())
    }

    fn list(&self) -> Vec<String> {
        self.agents.iter().map(|(a, (p, c, s))| format!("{} rps={}/{} burst={} {:?}", a, c, p.max_rps, p.burst, s)).collect()
    }
}

type SharedThrottleCtrl = Arc<std::sync::Mutex<ThrottleCtrl>>;

/// Entity-relationship knowledge graph.
#[derive(Clone, Debug)]
struct KGraphNode { id: String, label: String, props: std::collections::HashMap<String, String> }

#[derive(Clone, Debug)]
struct KGraphEdge { from: String, to: String, relation: String }

struct KGraph {
    nodes: Vec<KGraphNode>,
    edges: Vec<KGraphEdge>,
}

impl KGraph {
    fn new() -> Self { Self { nodes: Vec::new(), edges: Vec::new() } }

    fn add_node(&mut self, id: &str, label: &str) {
        if !self.nodes.iter().any(|n| n.id == id) {
            self.nodes.push(KGraphNode { id: id.to_string(), label: label.to_string(), props: std::collections::HashMap::new() });
        }
    }

    fn add_edge(&mut self, from: &str, to: &str, relation: &str) {
        self.edges.push(KGraphEdge { from: from.to_string(), to: to.to_string(), relation: relation.to_string() });
    }

    fn neighbors(&self, id: &str) -> Vec<(String, String)> {
        self.edges.iter().filter(|e| e.from == id).map(|e| (e.to.clone(), e.relation.clone())).collect()
    }

    fn path(&self, from: &str, to: &str) -> Option<Vec<String>> {
        let mut visited = std::collections::HashSet::new();
        let mut queue: std::collections::VecDeque<(String, Vec<String>)> = std::collections::VecDeque::new();
        queue.push_back((from.to_string(), vec![from.to_string()]));
        while let Some((current, path)) = queue.pop_front() {
            if current == to { return Some(path); }
            if !visited.insert(current.clone()) { continue; }
            for e in &self.edges {
                if e.from == current && !visited.contains(&e.to) {
                    let mut p = path.clone();
                    p.push(e.to.clone());
                    queue.push_back((e.to.clone(), p));
                }
            }
        }
        None
    }

    fn list(&self) -> Vec<String> {
        self.nodes.iter().map(|n| format!("{} ({})", n.id, n.label)).collect()
    }
}

type SharedKGraph = Arc<std::sync::Mutex<KGraph>>;

/// Agent state migration manager.
#[derive(Clone, Debug, PartialEq)]
enum MigrationState { Pending, Running, Done, RolledBack }

#[derive(Clone, Debug)]
struct Migration {
    id: String,
    from_version: String,
    to_version: String,
    state: MigrationState,
}

struct MigrationMgr {
    migrations: Vec<Migration>,
    next_id: u64,
}

impl MigrationMgr {
    fn new() -> Self { Self { migrations: Vec::new(), next_id: 1 } }

    fn create(&mut self, from: &str, to: &str) -> String {
        let id = format!("mig-{}", self.next_id);
        self.next_id += 1;
        self.migrations.push(Migration { id: id.clone(), from_version: from.to_string(), to_version: to.to_string(), state: MigrationState::Pending });
        id
    }

    fn run(&mut self, id: &str) -> bool {
        if let Some(m) = self.migrations.iter_mut().find(|m| m.id == id && m.state == MigrationState::Pending) {
            m.state = MigrationState::Running; true
        } else { false }
    }

    fn complete(&mut self, id: &str) -> bool {
        if let Some(m) = self.migrations.iter_mut().find(|m| m.id == id && m.state == MigrationState::Running) {
            m.state = MigrationState::Done; true
        } else { false }
    }

    fn rollback(&mut self, id: &str) -> bool {
        if let Some(m) = self.migrations.iter_mut().find(|m| m.id == id && (m.state == MigrationState::Running || m.state == MigrationState::Done)) {
            m.state = MigrationState::RolledBack; true
        } else { false }
    }

    fn list(&self) -> Vec<String> {
        self.migrations.iter().map(|m| format!("{} {} → {} {:?}", m.id, m.from_version, m.to_version, m.state)).collect()
    }
}

type SharedMigrationMgr = Arc<std::sync::Mutex<MigrationMgr>>;

/// Load-based request shedder.
#[derive(Clone, Debug)]
enum ShedAction { Accept, Shed, Degrade }

struct LoadShedder {
    threshold: f64,
    degrade_threshold: f64,
    current_load: f64,
    shed_count: u64,
}

impl LoadShedder {
    fn new(threshold: f64, degrade_threshold: f64) -> Self {
        Self { threshold, degrade_threshold, current_load: 0.0, shed_count: 0 }
    }

    fn set_load(&mut self, load: f64) { self.current_load = load; }

    fn evaluate(&mut self) -> ShedAction {
        if self.current_load >= self.threshold {
            self.shed_count += 1;
            ShedAction::Shed
        } else if self.current_load >= self.degrade_threshold {
            ShedAction::Degrade
        } else {
            ShedAction::Accept
        }
    }

    fn stats(&self) -> (f64, u64) { (self.current_load, self.shed_count) }

    fn list(&self) -> Vec<String> {
        vec![format!("load={:.1}% threshold={:.1}% shed={}", self.current_load * 100.0, self.threshold * 100.0, self.shed_count)]
    }
}

type SharedLoadShedder = Arc<std::sync::Mutex<LoadShedder>>;

/// Distributed tracing telemetry collector.
#[derive(Clone, Debug)]
struct TelemetrySpan {
    trace_id: String,
    span_id: String,
    parent: Option<String>,
    name: String,
    start: u64,
    end: Option<u64>,
}

struct TelemetryCollector {
    spans: Vec<TelemetrySpan>,
    next_id: u64,
}

impl TelemetryCollector {
    fn new() -> Self { Self { spans: Vec::new(), next_id: 1 } }

    fn start_span(&mut self, trace_id: &str, name: &str, parent: Option<&str>, start: u64) -> String {
        let span_id = format!("span-{}", self.next_id);
        self.next_id += 1;
        self.spans.push(TelemetrySpan {
            trace_id: trace_id.to_string(), span_id: span_id.clone(),
            parent: parent.map(|s| s.to_string()), name: name.to_string(), start, end: None,
        });
        span_id
    }

    fn end_span(&mut self, span_id: &str, end: u64) -> bool {
        if let Some(s) = self.spans.iter_mut().find(|s| s.span_id == span_id) {
            s.end = Some(end); true
        } else { false }
    }

    fn trace(&self, trace_id: &str) -> Vec<&TelemetrySpan> {
        self.spans.iter().filter(|s| s.trace_id == trace_id).collect()
    }

    fn duration(&self, span_id: &str) -> Option<u64> {
        let s = self.spans.iter().find(|s| s.span_id == span_id)?;
        s.end.map(|e| e - s.start)
    }

    fn list(&self, limit: usize) -> Vec<String> {
        self.spans.iter().rev().take(limit).map(|s| {
            format!("{}/{} {} dur={:?}", s.trace_id, s.span_id, s.name, s.end.map(|e| e - s.start))
        }).collect()
    }
}

type SharedTelemetryCollector = Arc<std::sync::Mutex<TelemetryCollector>>;

/// A/B testing feature gate with percentage rollout.
#[derive(Clone, Debug)]
struct FeatureGate {
    name: String,
    rollout_pct: f64,
    enabled: bool,
    overrides: std::collections::HashMap<String, bool>,
}

struct FeatureGateRegistry {
    gates: Vec<FeatureGate>,
}

impl FeatureGateRegistry {
    fn new() -> Self { Self { gates: Vec::new() } }

    fn add(&mut self, name: &str, rollout_pct: f64) {
        self.gates.push(FeatureGate {
            name: name.to_string(), rollout_pct, enabled: true,
            overrides: std::collections::HashMap::new(),
        });
    }

    fn check(&self, name: &str, user_id: &str) -> bool {
        if let Some(g) = self.gates.iter().find(|g| g.name == name) {
            if !g.enabled { return false; }
            if let Some(&ov) = g.overrides.get(user_id) { return ov; }
            let hash = user_id.bytes().fold(0u64, |acc, b| acc.wrapping_mul(31).wrapping_add(b as u64));
            (hash % 100) < (g.rollout_pct as u64)
        } else { false }
    }

    fn set_override(&mut self, gate: &str, user_id: &str, value: bool) {
        if let Some(g) = self.gates.iter_mut().find(|g| g.name == gate) {
            g.overrides.insert(user_id.to_string(), value);
        }
    }

    fn toggle(&mut self, name: &str) -> Option<bool> {
        if let Some(g) = self.gates.iter_mut().find(|g| g.name == name) {
            g.enabled = !g.enabled; Some(g.enabled)
        } else { None }
    }

    fn list(&self) -> Vec<String> {
        self.gates.iter().map(|g| format!("{} {}% {} overrides={}",
            g.name, g.rollout_pct, if g.enabled { "ON" } else { "OFF" }, g.overrides.len())).collect()
    }
}

type SharedFeatureGateRegistry = Arc<std::sync::Mutex<FeatureGateRegistry>>;

/// Generic resource pool — checkout/return with utilization tracking.
#[derive(Clone, Debug)]
struct ResPoolSlot { id: String, checked_out_by: Option<String> }

struct ResPoolMgr {
    slots: Vec<ResPoolSlot>,
    total_checkouts: u64,
}

impl ResPoolMgr {
    fn new(capacity: usize) -> Self {
        let slots = (0..capacity).map(|i| ResPoolSlot { id: format!("slot-{}", i), checked_out_by: None }).collect();
        Self { slots, total_checkouts: 0 }
    }

    fn checkout(&mut self, agent: &str) -> Option<String> {
        if let Some(slot) = self.slots.iter_mut().find(|s| s.checked_out_by.is_none()) {
            slot.checked_out_by = Some(agent.to_string());
            self.total_checkouts += 1;
            Some(slot.id.clone())
        } else { None }
    }

    fn release(&mut self, slot_id: &str) -> bool {
        if let Some(slot) = self.slots.iter_mut().find(|s| s.id == slot_id) {
            slot.checked_out_by = None; true
        } else { false }
    }

    fn utilization(&self) -> f64 {
        let used = self.slots.iter().filter(|s| s.checked_out_by.is_some()).count();
        used as f64 / self.slots.len().max(1) as f64
    }

    fn available(&self) -> usize {
        self.slots.iter().filter(|s| s.checked_out_by.is_none()).count()
    }

    fn list(&self) -> Vec<String> {
        self.slots.iter().map(|s| format!("{} {}", s.id,
            s.checked_out_by.as_deref().unwrap_or("free"))).collect()
    }
}

type SharedResPoolMgr = Arc<std::sync::Mutex<ResPoolMgr>>;

/// Append-only event sourcing log with snapshot support.
#[derive(Clone, Debug)]
struct EsEvent { seq: u64, event_type: String, payload: String }

struct EventSourcingLog {
    events: Vec<EsEvent>,
    next_seq: u64,
    snapshots: Vec<(u64, String)>, // (at_seq, snapshot_data)
}

impl EventSourcingLog {
    fn new() -> Self { Self { events: Vec::new(), next_seq: 1, snapshots: Vec::new() } }

    fn append(&mut self, event_type: &str, payload: &str) -> u64 {
        let seq = self.next_seq;
        self.next_seq += 1;
        self.events.push(EsEvent { seq, event_type: event_type.to_string(), payload: payload.to_string() });
        seq
    }

    fn snapshot(&mut self, data: &str) {
        self.snapshots.push((self.next_seq - 1, data.to_string()));
    }

    fn replay_from(&self, seq: u64) -> Vec<&EsEvent> {
        self.events.iter().filter(|e| e.seq >= seq).collect()
    }

    fn latest_snapshot(&self) -> Option<&(u64, String)> {
        self.snapshots.last()
    }

    fn list(&self, limit: usize) -> Vec<String> {
        self.events.iter().rev().take(limit).map(|e| format!("#{} {} {}", e.seq, e.event_type, &e.payload[..e.payload.len().min(40)])).collect()
    }
}

type SharedEventSourcingLog = Arc<std::sync::Mutex<EventSourcingLog>>;

/// Task-to-agent affinity scoring and routing.
#[derive(Clone, Debug)]
struct AffinityScore { agent: String, task_type: String, score: f64, sticky: bool }

struct AgentAffinityScorer {
    scores: Vec<AffinityScore>,
}

impl AgentAffinityScorer {
    fn new() -> Self { Self { scores: Vec::new() } }

    fn set(&mut self, agent: &str, task_type: &str, score: f64, sticky: bool) {
        if let Some(s) = self.scores.iter_mut().find(|s| s.agent == agent && s.task_type == task_type) {
            s.score = score; s.sticky = sticky;
        } else {
            self.scores.push(AffinityScore { agent: agent.to_string(), task_type: task_type.to_string(), score, sticky });
        }
    }

    fn best_for(&self, task_type: &str) -> Option<String> {
        self.scores.iter().filter(|s| s.task_type == task_type)
            .max_by(|a, b| a.score.partial_cmp(&b.score).unwrap_or(std::cmp::Ordering::Equal))
            .map(|s| s.agent.clone())
    }

    fn boost(&mut self, agent: &str, task_type: &str, amount: f64) {
        if let Some(s) = self.scores.iter_mut().find(|s| s.agent == agent && s.task_type == task_type) {
            s.score += amount;
        }
    }

    fn list(&self) -> Vec<String> {
        self.scores.iter().map(|s| format!("{} → {} score={:.2} sticky={}", s.task_type, s.agent, s.score, s.sticky)).collect()
    }
}

type SharedAgentAffinityScorer = Arc<std::sync::Mutex<AgentAffinityScorer>>;

/// Multi-dimensional health scoreboard.
#[derive(Clone, Debug)]
struct HealthDim { name: String, value: f64, weight: f64 }

struct HealthScoreboard {
    agents: std::collections::HashMap<String, Vec<HealthDim>>,
}

impl HealthScoreboard {
    fn new() -> Self { Self { agents: std::collections::HashMap::new() } }

    fn set(&mut self, agent: &str, dim: &str, value: f64, weight: f64) {
        let dims = self.agents.entry(agent.to_string()).or_default();
        if let Some(d) = dims.iter_mut().find(|d| d.name == dim) {
            d.value = value; d.weight = weight;
        } else {
            dims.push(HealthDim { name: dim.to_string(), value, weight });
        }
    }

    fn composite(&self, agent: &str) -> f64 {
        if let Some(dims) = self.agents.get(agent) {
            let total_w: f64 = dims.iter().map(|d| d.weight).sum();
            if total_w == 0.0 { return 0.0; }
            dims.iter().map(|d| d.value * d.weight).sum::<f64>() / total_w
        } else { 0.0 }
    }

    fn dims(&self, agent: &str) -> Vec<String> {
        self.agents.get(agent).map(|ds| ds.iter().map(|d| format!("{}={:.2} w={:.1}", d.name, d.value, d.weight)).collect()).unwrap_or_default()
    }

    fn ranking(&self) -> Vec<(String, f64)> {
        let mut r: Vec<_> = self.agents.keys().map(|a| (a.clone(), self.composite(a))).collect();
        r.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        r
    }

    fn list(&self) -> Vec<String> {
        self.ranking().iter().map(|(a, s)| format!("{} composite={:.2}", a, s)).collect()
    }
}

type SharedHealthScoreboard = Arc<std::sync::Mutex<HealthScoreboard>>;

/// Sliding window event counter.
struct SlidingWindowCounter {
    buckets: Vec<(u64, u64)>, // (timestamp, count)
    window_size: u64,
    bucket_size: u64,
}

impl SlidingWindowCounter {
    fn new(window_size: u64, bucket_size: u64) -> Self {
        Self { buckets: Vec::new(), window_size, bucket_size }
    }

    fn record(&mut self, ts: u64) {
        let bucket_ts = ts / self.bucket_size * self.bucket_size;
        if let Some(b) = self.buckets.iter_mut().find(|(t, _)| *t == bucket_ts) {
            b.1 += 1;
        } else {
            self.buckets.push((bucket_ts, 1));
        }
    }

    fn count(&self, now: u64) -> u64 {
        let cutoff = now.saturating_sub(self.window_size);
        self.buckets.iter().filter(|(t, _)| *t >= cutoff).map(|(_, c)| c).sum()
    }

    fn prune(&mut self, now: u64) {
        let cutoff = now.saturating_sub(self.window_size);
        self.buckets.retain(|(t, _)| *t >= cutoff);
    }

    fn list(&self) -> Vec<String> {
        self.buckets.iter().map(|(t, c)| format!("t={} count={}", t, c)).collect()
    }
}

type SharedSlidingWindowCounter = Arc<std::sync::Mutex<SlidingWindowCounter>>;

/// Rule-based policy evaluation engine.
#[derive(Clone, Debug)]
struct EngineRule {
    name: String,
    condition: String,
    action: String,
    priority: u32,
    enabled: bool,
}

struct RuleEngine {
    rules: Vec<EngineRule>,
}

impl RuleEngine {
    fn new() -> Self { Self { rules: Vec::new() } }

    fn add(&mut self, name: &str, condition: &str, action: &str, priority: u32) {
        self.rules.push(EngineRule {
            name: name.to_string(), condition: condition.to_string(),
            action: action.to_string(), priority, enabled: true,
        });
        self.rules.sort_by(|a, b| b.priority.cmp(&a.priority));
    }

    fn evaluate(&self, input: &str) -> Vec<String> {
        self.rules.iter()
            .filter(|r| r.enabled && input.contains(&r.condition))
            .map(|r| r.action.clone())
            .collect()
    }

    fn toggle(&mut self, name: &str) -> Option<bool> {
        if let Some(r) = self.rules.iter_mut().find(|r| r.name == name) {
            r.enabled = !r.enabled; Some(r.enabled)
        } else { None }
    }

    fn list(&self) -> Vec<String> {
        self.rules.iter().map(|r| format!("{} [p={}] {} if '{}' → '{}' ",
            r.name, r.priority, if r.enabled { "ON" } else { "OFF" }, r.condition, r.action)).collect()
    }
}

type SharedRuleEngine = Arc<std::sync::Mutex<RuleEngine>>;

/// Per-agent resource quota enforcement.
#[derive(Clone, Debug)]
struct AgentQuotaEntry { agent: String, limit: u64, used: u64 }

struct AgentQuotaMgr {
    quotas: Vec<AgentQuotaEntry>,
}

impl AgentQuotaMgr {
    fn new() -> Self { Self { quotas: Vec::new() } }

    fn set(&mut self, agent: &str, limit: u64) {
        if let Some(q) = self.quotas.iter_mut().find(|q| q.agent == agent) {
            q.limit = limit;
        } else {
            self.quotas.push(AgentQuotaEntry { agent: agent.to_string(), limit, used: 0 });
        }
    }

    fn consume(&mut self, agent: &str, amount: u64) -> bool {
        if let Some(q) = self.quotas.iter_mut().find(|q| q.agent == agent) {
            if q.used + amount <= q.limit { q.used += amount; true } else { false }
        } else { false }
    }

    fn remaining(&self, agent: &str) -> Option<u64> {
        self.quotas.iter().find(|q| q.agent == agent).map(|q| q.limit.saturating_sub(q.used))
    }

    fn reset(&mut self, agent: &str) {
        if let Some(q) = self.quotas.iter_mut().find(|q| q.agent == agent) { q.used = 0; }
    }

    fn list(&self) -> Vec<String> {
        self.quotas.iter().map(|q| format!("{} {}/{}", q.agent, q.used, q.limit)).collect()
    }
}

type SharedAgentQuotaMgr = Arc<std::sync::Mutex<AgentQuotaMgr>>;

/// W3C-style trace context propagation.
#[derive(Clone, Debug)]
struct TraceCtx {
    trace_id: String,
    span_id: String,
    baggage: std::collections::HashMap<String, String>,
}

struct TraceCtxRegistry {
    contexts: std::collections::HashMap<String, TraceCtx>,
    next_id: u64,
}

impl TraceCtxRegistry {
    fn new() -> Self { Self { contexts: std::collections::HashMap::new(), next_id: 1 } }

    fn create(&mut self, trace_id: &str) -> String {
        let span_id = format!("ctx-{}", self.next_id);
        self.next_id += 1;
        self.contexts.insert(span_id.clone(), TraceCtx {
            trace_id: trace_id.to_string(), span_id: span_id.clone(),
            baggage: std::collections::HashMap::new(),
        });
        span_id
    }

    fn set_baggage(&mut self, ctx_id: &str, key: &str, value: &str) {
        if let Some(ctx) = self.contexts.get_mut(ctx_id) {
            ctx.baggage.insert(key.to_string(), value.to_string());
        }
    }

    fn get_baggage(&self, ctx_id: &str, key: &str) -> Option<String> {
        self.contexts.get(ctx_id)?.baggage.get(key).cloned()
    }

    fn inject(&self, ctx_id: &str) -> Option<String> {
        let ctx = self.contexts.get(ctx_id)?;
        Some(format!("traceparent: 00-{}-{}-01", ctx.trace_id, ctx.span_id))
    }

    fn list(&self) -> Vec<String> {
        self.contexts.values().map(|c| format!("{}/{} baggage={}", c.trace_id, c.span_id, c.baggage.len())).collect()
    }
}

type SharedTraceCtxRegistry = Arc<std::sync::Mutex<TraceCtxRegistry>>;

/// Transactional rollback journal with savepoints.
#[derive(Clone, Debug)]
struct RjEntry { seq: u64, key: String, old_value: Option<String>, new_value: String }

struct RollbackJournal {
    entries: Vec<RjEntry>,
    savepoints: Vec<(String, u64)>, // (name, entry_count_at_save)
    next_seq: u64,
}

impl RollbackJournal {
    fn new() -> Self { Self { entries: Vec::new(), savepoints: Vec::new(), next_seq: 1 } }

    fn record(&mut self, key: &str, old: Option<&str>, new_val: &str) -> u64 {
        let seq = self.next_seq;
        self.next_seq += 1;
        self.entries.push(RjEntry {
            seq, key: key.to_string(), old_value: old.map(|s| s.to_string()), new_value: new_val.to_string(),
        });
        seq
    }

    fn savepoint(&mut self, name: &str) {
        self.savepoints.push((name.to_string(), self.entries.len() as u64));
    }

    fn rollback_to(&mut self, name: &str) -> Vec<RjEntry> {
        if let Some(pos) = self.savepoints.iter().position(|(n, _)| n == name) {
            let (_, count) = self.savepoints[pos];
            let undone: Vec<RjEntry> = self.entries.drain(count as usize..).rev().collect();
            self.savepoints.truncate(pos);
            undone
        } else { Vec::new() }
    }

    fn list(&self) -> Vec<String> {
        self.entries.iter().map(|e| format!("#{} {} {:?} → {}", e.seq, e.key, e.old_value, e.new_value)).collect()
    }
}

type SharedRollbackJournal = Arc<std::sync::Mutex<RollbackJournal>>;

/// Multi-circuit breaker registry with per-service state.
#[derive(Clone, Debug, PartialEq)]
enum CbRegState { Closed, Open, HalfOpen }

#[derive(Clone, Debug)]
struct CbRegEntry { name: String, state: CbRegState, failures: u32, max_failures: u32, successes_in_half: u32 }

struct CircuitBreakerRegistry {
    breakers: Vec<CbRegEntry>,
}

impl CircuitBreakerRegistry {
    fn new() -> Self { Self { breakers: Vec::new() } }

    fn register(&mut self, name: &str, max_failures: u32) {
        self.breakers.push(CbRegEntry { name: name.to_string(), state: CbRegState::Closed, failures: 0, max_failures, successes_in_half: 0 });
    }

    fn record_failure(&mut self, name: &str) -> Option<CbRegState> {
        let cb = self.breakers.iter_mut().find(|c| c.name == name)?;
        cb.failures += 1;
        if cb.failures >= cb.max_failures { cb.state = CbRegState::Open; }
        Some(cb.state.clone())
    }

    fn record_success(&mut self, name: &str) -> Option<CbRegState> {
        let cb = self.breakers.iter_mut().find(|c| c.name == name)?;
        if cb.state == CbRegState::HalfOpen {
            cb.successes_in_half += 1;
            if cb.successes_in_half >= 2 { cb.state = CbRegState::Closed; cb.failures = 0; cb.successes_in_half = 0; }
        }
        Some(cb.state.clone())
    }

    fn half_open(&mut self, name: &str) -> bool {
        if let Some(cb) = self.breakers.iter_mut().find(|c| c.name == name && c.state == CbRegState::Open) {
            cb.state = CbRegState::HalfOpen; cb.successes_in_half = 0; true
        } else { false }
    }

    fn state(&self, name: &str) -> Option<CbRegState> {
        self.breakers.iter().find(|c| c.name == name).map(|c| c.state.clone())
    }

    fn list(&self) -> Vec<String> {
        self.breakers.iter().map(|c| format!("{} {:?} failures={}/{}", c.name, c.state, c.failures, c.max_failures)).collect()
    }
}

type SharedCircuitBreakerRegistry = Arc<std::sync::Mutex<CircuitBreakerRegistry>>;

/// Priority queue with aging and starvation prevention.
#[derive(Clone, Debug)]
struct PrioItem { id: String, priority: u32, age: u32, payload: String }

struct PrioQueueMgr {
    items: Vec<PrioItem>,
    next_id: u64,
}

impl PrioQueueMgr {
    fn new() -> Self { Self { items: Vec::new(), next_id: 1 } }

    fn push(&mut self, priority: u32, payload: &str) -> String {
        let id = format!("pq-{}", self.next_id);
        self.next_id += 1;
        self.items.push(PrioItem { id: id.clone(), priority, age: 0, payload: payload.to_string() });
        id
    }

    fn pop(&mut self) -> Option<PrioItem> {
        if self.items.is_empty() { return None; }
        // effective priority = priority + age (aging prevents starvation)
        let idx = self.items.iter().enumerate()
            .max_by_key(|(_, item)| item.priority + item.age)
            .map(|(i, _)| i)?;
        Some(self.items.remove(idx))
    }

    fn age_all(&mut self) {
        for item in &mut self.items { item.age += 1; }
    }

    fn reprioritize(&mut self, id: &str, new_prio: u32) -> bool {
        if let Some(item) = self.items.iter_mut().find(|i| i.id == id) {
            item.priority = new_prio; true
        } else { false }
    }

    fn len(&self) -> usize { self.items.len() }

    fn list(&self) -> Vec<String> {
        self.items.iter().map(|i| format!("{} p={} age={} {}", i.id, i.priority, i.age, &i.payload[..i.payload.len().min(30)])).collect()
    }
}

type SharedPrioQueueMgr = Arc<std::sync::Mutex<PrioQueueMgr>>;

/// Schema-based configuration validator.
#[derive(Clone, Debug)]
struct CfgField { name: String, required: bool, field_type: String }

struct ConfigValidator {
    schemas: std::collections::HashMap<String, Vec<CfgField>>,
}

impl ConfigValidator {
    fn new() -> Self { Self { schemas: std::collections::HashMap::new() } }

    fn define(&mut self, schema_name: &str, fields: Vec<(&str, bool, &str)>) {
        let fields = fields.into_iter().map(|(n, r, t)| CfgField { name: n.to_string(), required: r, field_type: t.to_string() }).collect();
        self.schemas.insert(schema_name.to_string(), fields);
    }

    fn validate(&self, schema: &str, config: &std::collections::HashMap<String, String>) -> Vec<String> {
        let mut errors = Vec::new();
        if let Some(fields) = self.schemas.get(schema) {
            for f in fields {
                if f.required && !config.contains_key(&f.name) {
                    errors.push(format!("missing required field: {}", f.name));
                }
                if let Some(val) = config.get(&f.name) {
                    match f.field_type.as_str() {
                        "int" => { if val.parse::<i64>().is_err() { errors.push(format!("{}: expected int", f.name)); } }
                        "float" => { if val.parse::<f64>().is_err() { errors.push(format!("{}: expected float", f.name)); } }
                        "bool" => { if val != "true" && val != "false" { errors.push(format!("{}: expected bool", f.name)); } }
                        _ => {}
                    }
                }
            }
        } else {
            errors.push(format!("schema '{}' not found", schema));
        }
        errors
    }

    fn list(&self) -> Vec<String> {
        self.schemas.iter().map(|(name, fields)| format!("{} ({} fields)", name, fields.len())).collect()
    }
}

type SharedConfigValidator = Arc<std::sync::Mutex<ConfigValidator>>;

/// Token/cost budget per agent per time period.
#[derive(Clone, Debug)]
struct BudgetEntry { agent: String, budget: f64, spent: f64, period: String }

struct AgentBudgetMgr {
    entries: Vec<BudgetEntry>,
}

impl AgentBudgetMgr {
    fn new() -> Self { Self { entries: Vec::new() } }

    fn set(&mut self, agent: &str, budget: f64, period: &str) {
        if let Some(e) = self.entries.iter_mut().find(|e| e.agent == agent) {
            e.budget = budget; e.period = period.to_string();
        } else {
            self.entries.push(BudgetEntry { agent: agent.to_string(), budget, spent: 0.0, period: period.to_string() });
        }
    }

    fn spend(&mut self, agent: &str, amount: f64) -> bool {
        if let Some(e) = self.entries.iter_mut().find(|e| e.agent == agent) {
            if e.spent + amount <= e.budget { e.spent += amount; true } else { false }
        } else { false }
    }

    fn remaining(&self, agent: &str) -> Option<f64> {
        self.entries.iter().find(|e| e.agent == agent).map(|e| e.budget - e.spent)
    }

    fn reset(&mut self, agent: &str) {
        if let Some(e) = self.entries.iter_mut().find(|e| e.agent == agent) { e.spent = 0.0; }
    }

    fn list(&self) -> Vec<String> {
        self.entries.iter().map(|e| format!("{} ${:.2}/${:.2} ({})", e.agent, e.spent, e.budget, e.period)).collect()
    }
}

type SharedAgentBudgetMgr = Arc<std::sync::Mutex<AgentBudgetMgr>>;

/// Data retention policy with TTL-based expiry.
#[derive(Clone, Debug)]
struct RetentionRule { name: String, ttl_secs: u64, created_at: u64 }

struct RetentionPolicyMgr {
    rules: Vec<RetentionRule>,
    clock: u64,
}

impl RetentionPolicyMgr {
    fn new() -> Self { Self { rules: Vec::new(), clock: 0 } }

    fn add(&mut self, name: &str, ttl_secs: u64) {
        self.rules.push(RetentionRule { name: name.to_string(), ttl_secs, created_at: self.clock });
    }

    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn expired(&self) -> Vec<String> {
        self.rules.iter().filter(|r| self.clock.saturating_sub(r.created_at) >= r.ttl_secs)
            .map(|r| r.name.clone()).collect()
    }

    fn cleanup(&mut self) -> usize {
        let before = self.rules.len();
        self.rules.retain(|r| self.clock.saturating_sub(r.created_at) < r.ttl_secs);
        before - self.rules.len()
    }

    fn list(&self) -> Vec<String> {
        self.rules.iter().map(|r| {
            let remaining = r.ttl_secs.saturating_sub(self.clock.saturating_sub(r.created_at));
            format!("{} ttl={}s remaining={}s", r.name, r.ttl_secs, remaining)
        }).collect()
    }
}

type SharedRetentionPolicyMgr = Arc<std::sync::Mutex<RetentionPolicyMgr>>;

/// Topological dependency resolver with cycle detection.
struct DependencyResolver {
    deps: std::collections::HashMap<String, Vec<String>>,
}

impl DependencyResolver {
    fn new() -> Self { Self { deps: std::collections::HashMap::new() } }

    fn add(&mut self, item: &str, depends_on: &[&str]) {
        self.deps.insert(item.to_string(), depends_on.iter().map(|s| s.to_string()).collect());
    }

    fn resolve(&self) -> Result<Vec<String>, String> {
        let mut visited = std::collections::HashSet::new();
        let mut stack = std::collections::HashSet::new();
        let mut order = Vec::new();
        for key in self.deps.keys() {
            self.visit(key, &mut visited, &mut stack, &mut order)?;
        }
        Ok(order)
    }

    fn visit(&self, node: &str, visited: &mut std::collections::HashSet<String>,
             stack: &mut std::collections::HashSet<String>, order: &mut Vec<String>) -> Result<(), String> {
        if stack.contains(node) { return Err(format!("cycle detected at '{}'", node)); }
        if visited.contains(node) { return Ok(()); }
        stack.insert(node.to_string());
        if let Some(deps) = self.deps.get(node) {
            for d in deps { self.visit(d, visited, stack, order)?; }
        }
        stack.remove(node);
        visited.insert(node.to_string());
        order.push(node.to_string());
        Ok(())
    }

    fn list(&self) -> Vec<String> {
        self.deps.iter().map(|(k, v)| format!("{} → [{}]", k, v.join(", "))).collect()
    }
}

type SharedDependencyResolver = Arc<std::sync::Mutex<DependencyResolver>>;

/// Backpressure flow controller with watermark levels.
#[derive(Clone, Debug, PartialEq)]
enum FlowState { Running, Paused, Degraded }

struct FlowController {
    high_watermark: u64,
    low_watermark: u64,
    current: u64,
    state: FlowState,
}

impl FlowController {
    fn new(low: u64, high: u64) -> Self {
        Self { high_watermark: high, low_watermark: low, current: 0, state: FlowState::Running }
    }

    fn add(&mut self, amount: u64) -> FlowState {
        self.current += amount;
        if self.current >= self.high_watermark { self.state = FlowState::Paused; }
        else if self.current >= self.low_watermark { self.state = FlowState::Degraded; }
        self.state.clone()
    }

    fn drain(&mut self, amount: u64) -> FlowState {
        self.current = self.current.saturating_sub(amount);
        if self.current < self.low_watermark { self.state = FlowState::Running; }
        else if self.current < self.high_watermark { self.state = FlowState::Degraded; }
        self.state.clone()
    }

    fn state(&self) -> FlowState { self.state.clone() }

    fn list(&self) -> Vec<String> {
        vec![format!("current={} low={} high={} {:?}", self.current, self.low_watermark, self.high_watermark, self.state)]
    }
}

type SharedFlowController = Arc<std::sync::Mutex<FlowController>>;

/// Immutable audit log.
#[derive(Clone, Debug)]
struct AuditLogEntry { seq: u64, actor: String, action: String, resource: String, ts: u64 }

struct AuditLogMgr {
    records: Vec<AuditLogEntry>,
    next_seq: u64,
    clock: u64,
}

impl AuditLogMgr {
    fn new() -> Self { Self { records: Vec::new(), next_seq: 1, clock: 0 } }

    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn record(&mut self, actor: &str, action: &str, resource: &str) -> u64 {
        let seq = self.next_seq;
        self.next_seq += 1;
        self.records.push(AuditLogEntry { seq, actor: actor.to_string(), action: action.to_string(), resource: resource.to_string(), ts: self.clock });
        seq
    }

    fn by_actor(&self, actor: &str) -> Vec<&AuditLogEntry> {
        self.records.iter().filter(|r| r.actor == actor).collect()
    }

    fn by_action(&self, action: &str) -> Vec<&AuditLogEntry> {
        self.records.iter().filter(|r| r.action == action).collect()
    }

    fn list(&self, limit: usize) -> Vec<String> {
        self.records.iter().rev().take(limit).map(|r| format!("#{} {}:{} on {} @{}", r.seq, r.actor, r.action, r.resource, r.ts)).collect()
    }
}

type SharedAuditLogMgr = Arc<std::sync::Mutex<AuditLogMgr>>;

/// Version-aware capability negotiation.
#[derive(Clone, Debug)]
struct VerCapEntry { agent: String, capability: String, version: u32 }

struct VersionCapNeg {
    entries: Vec<VerCapEntry>,
}

impl VersionCapNeg {
    fn new() -> Self { Self { entries: Vec::new() } }

    fn advertise(&mut self, agent: &str, capability: &str, version: u32) {
        if let Some(e) = self.entries.iter_mut().find(|e| e.agent == agent && e.capability == capability) {
            e.version = version;
        } else {
            self.entries.push(VerCapEntry { agent: agent.to_string(), capability: capability.to_string(), version });
        }
    }

    fn negotiate(&self, cap: &str, min_version: u32) -> Vec<String> {
        self.entries.iter().filter(|e| e.capability == cap && e.version >= min_version)
            .map(|e| format!("{} v{}", e.agent, e.version)).collect()
    }

    fn best(&self, cap: &str) -> Option<(String, u32)> {
        self.entries.iter().filter(|e| e.capability == cap)
            .max_by_key(|e| e.version)
            .map(|e| (e.agent.clone(), e.version))
    }

    fn list(&self) -> Vec<String> {
        self.entries.iter().map(|e| format!("{} {} v{}", e.agent, e.capability, e.version)).collect()
    }
}

type SharedVersionCapNeg = Arc<std::sync::Mutex<VersionCapNeg>>;

/// Alert manager with rules and silencing.
#[derive(Clone, Debug)]
struct AlertRule { name: String, condition: String, severity: String, silenced: bool, fire_count: u64 }

struct AlertManager {
    rules: Vec<AlertRule>,
}

impl AlertManager {
    fn new() -> Self { Self { rules: Vec::new() } }

    fn add_rule(&mut self, name: &str, condition: &str, severity: &str) {
        self.rules.push(AlertRule { name: name.to_string(), condition: condition.to_string(), severity: severity.to_string(), silenced: false, fire_count: 0 });
    }

    fn check(&mut self, input: &str) -> Vec<String> {
        let mut fired = Vec::new();
        for r in &mut self.rules {
            if !r.silenced && input.contains(&r.condition) {
                r.fire_count += 1;
                fired.push(format!("[{}] {} ({})", r.severity, r.name, r.condition));
            }
        }
        fired
    }

    fn silence(&mut self, name: &str) -> bool {
        if let Some(r) = self.rules.iter_mut().find(|r| r.name == name) { r.silenced = true; true } else { false }
    }

    fn unsilence(&mut self, name: &str) -> bool {
        if let Some(r) = self.rules.iter_mut().find(|r| r.name == name) { r.silenced = false; true } else { false }
    }

    fn list(&self) -> Vec<String> {
        self.rules.iter().map(|r| format!("{} [{}] if '{}' {} fired={}",
            r.name, r.severity, r.condition, if r.silenced { "SILENCED" } else { "ACTIVE" }, r.fire_count)).collect()
    }
}

type SharedAlertManager = Arc<std::sync::Mutex<AlertManager>>;

/// Task deadline tracking with overdue detection.
#[derive(Clone, Debug)]
struct DeadlineTask { id: String, name: String, deadline: u64, grace: u64, completed: bool }

struct TaskDeadlineMgr {
    tasks: Vec<DeadlineTask>,
    clock: u64,
    next_id: u64,
}

impl TaskDeadlineMgr {
    fn new() -> Self { Self { tasks: Vec::new(), clock: 0, next_id: 1 } }
    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn add(&mut self, name: &str, deadline: u64, grace: u64) -> String {
        let id = format!("dl-{}", self.next_id); self.next_id += 1;
        self.tasks.push(DeadlineTask { id: id.clone(), name: name.to_string(), deadline, grace, completed: false });
        id
    }

    fn complete(&mut self, id: &str) -> bool {
        if let Some(t) = self.tasks.iter_mut().find(|t| t.id == id) { t.completed = true; true } else { false }
    }

    fn overdue(&self) -> Vec<String> {
        self.tasks.iter().filter(|t| !t.completed && self.clock > t.deadline + t.grace)
            .map(|t| format!("{} '{}' due={} overdue_by={}", t.id, t.name, t.deadline, self.clock - t.deadline)).collect()
    }

    fn list(&self) -> Vec<String> {
        self.tasks.iter().map(|t| {
            let status = if t.completed { "DONE" } else if self.clock > t.deadline + t.grace { "OVERDUE" }
                else if self.clock > t.deadline { "GRACE" } else { "PENDING" };
            format!("{} '{}' deadline={} [{}]", t.id, t.name, t.deadline, status)
        }).collect()
    }
}

type SharedTaskDeadlineMgr = Arc<std::sync::Mutex<TaskDeadlineMgr>>;

/// Agent reputation scoring system.
struct AgentReputationSys {
    scores: std::collections::HashMap<String, f64>,
    events: Vec<(String, f64)>,
}

impl AgentReputationSys {
    fn new() -> Self { Self { scores: std::collections::HashMap::new(), events: Vec::new() } }

    fn record(&mut self, agent: &str, delta: f64) {
        *self.scores.entry(agent.to_string()).or_insert(0.5) += delta;
        let score = self.scores.get_mut(agent).unwrap();
        *score = score.clamp(0.0, 1.0);
        self.events.push((agent.to_string(), delta));
    }

    fn score(&self, agent: &str) -> f64 {
        *self.scores.get(agent).unwrap_or(&0.5)
    }

    fn trust_level(&self, agent: &str) -> &str {
        let s = self.score(agent);
        if s >= 0.8 { "high" } else if s >= 0.5 { "medium" } else { "low" }
    }

    fn decay_all(&mut self, factor: f64) {
        for (_, s) in self.scores.iter_mut() { *s *= factor; }
    }

    fn list(&self) -> Vec<String> {
        self.scores.iter().map(|(a, s)| format!("{} score={:.2} trust={}", a, s, self.trust_level(a))).collect()
    }
}

type SharedAgentReputationSys = Arc<std::sync::Mutex<AgentReputationSys>>;

/// Point-in-time snapshot store with diff.
#[derive(Clone, Debug)]
struct Snapshot { id: String, ts: u64, data: std::collections::HashMap<String, String> }

struct SnapshotStore {
    snapshots: Vec<Snapshot>,
    next_id: u64,
}

impl SnapshotStore {
    fn new() -> Self { Self { snapshots: Vec::new(), next_id: 1 } }

    fn take(&mut self, ts: u64, data: std::collections::HashMap<String, String>) -> String {
        let id = format!("snap-{}", self.next_id); self.next_id += 1;
        self.snapshots.push(Snapshot { id: id.clone(), ts, data });
        id
    }

    fn get(&self, id: &str) -> Option<&Snapshot> {
        self.snapshots.iter().find(|s| s.id == id)
    }

    fn diff(&self, id_a: &str, id_b: &str) -> Vec<String> {
        let a = self.get(id_a);
        let b = self.get(id_b);
        let mut diffs = Vec::new();
        if let (Some(a), Some(b)) = (a, b) {
            for (k, va) in &a.data {
                match b.data.get(k) {
                    Some(vb) if va != vb => diffs.push(format!("~ {} '{}' → '{}'", k, va, vb)),
                    None => diffs.push(format!("- {} '{}'", k, va)),
                    _ => {}
                }
            }
            for (k, vb) in &b.data {
                if !a.data.contains_key(k) { diffs.push(format!("+ {} '{}'", k, vb)); }
            }
        }
        diffs
    }

    fn list(&self) -> Vec<String> {
        self.snapshots.iter().map(|s| format!("{} ts={} keys={}", s.id, s.ts, s.data.len())).collect()
    }
}

type SharedSnapshotStore = Arc<std::sync::Mutex<SnapshotStore>>;

/// Content-addressable storage with hash-based dedup.
struct ContentHasher {
    store: std::collections::HashMap<String, String>, // hash → content
}

impl ContentHasher {
    fn new() -> Self { Self { store: std::collections::HashMap::new() } }

    fn hash(content: &str) -> String {
        let h = content.bytes().fold(0u64, |acc, b| acc.wrapping_mul(31).wrapping_add(b as u64));
        format!("{:016x}", h)
    }

    fn put(&mut self, content: &str) -> String {
        let h = Self::hash(content);
        self.store.entry(h.clone()).or_insert_with(|| content.to_string());
        h
    }

    fn get(&self, hash: &str) -> Option<&String> { self.store.get(hash) }

    fn verify(&self, hash: &str) -> bool {
        self.store.get(hash).map(|c| Self::hash(c) == hash).unwrap_or(false)
    }

    fn list(&self) -> Vec<String> {
        self.store.iter().map(|(h, c)| format!("{} len={}", h, c.len())).collect()
    }
}

type SharedContentHasher = Arc<std::sync::Mutex<ContentHasher>>;

/// Fine-grained permission matrix.
struct PermissionMatrix {
    perms: std::collections::HashMap<String, std::collections::HashSet<String>>,
}

impl PermissionMatrix {
    fn new() -> Self { Self { perms: std::collections::HashMap::new() } }

    fn grant(&mut self, role: &str, permission: &str) {
        self.perms.entry(role.to_string()).or_default().insert(permission.to_string());
    }

    fn revoke(&mut self, role: &str, permission: &str) {
        if let Some(ps) = self.perms.get_mut(role) { ps.remove(permission); }
    }

    fn check(&self, role: &str, permission: &str) -> bool {
        self.perms.get(role).map(|ps| ps.contains(permission)).unwrap_or(false)
    }

    fn permissions_for(&self, role: &str) -> Vec<String> {
        self.perms.get(role).map(|ps| ps.iter().cloned().collect()).unwrap_or_default()
    }

    fn list(&self) -> Vec<String> {
        self.perms.iter().map(|(r, ps)| format!("{}: [{}]", r, ps.iter().cloned().collect::<Vec<_>>().join(", "))).collect()
    }
}

type SharedPermissionMatrix = Arc<std::sync::Mutex<PermissionMatrix>>;

/// Leader election with term numbers.
#[derive(Clone, Debug)]
struct LeaderElection {
    candidates: Vec<String>,
    leader: Option<String>,
    term: u64,
    votes: std::collections::HashMap<String, String>, // voter → candidate
}

impl LeaderElection {
    fn new() -> Self { Self { candidates: Vec::new(), leader: None, term: 0, votes: std::collections::HashMap::new() } }

    fn register(&mut self, agent: &str) {
        if !self.candidates.contains(&agent.to_string()) { self.candidates.push(agent.to_string()); }
    }

    fn vote(&mut self, voter: &str, candidate: &str) {
        self.votes.insert(voter.to_string(), candidate.to_string());
    }

    fn tally(&mut self) -> Option<String> {
        let mut counts: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
        for c in self.votes.values() { *counts.entry(c.clone()).or_default() += 1; }
        let winner = counts.into_iter().max_by_key(|(_, v)| *v).map(|(k, _)| k);
        if let Some(ref w) = winner { self.leader = Some(w.clone()); self.term += 1; self.votes.clear(); }
        winner
    }

    fn step_down(&mut self) { self.leader = None; }

    fn leader(&self) -> Option<&String> { self.leader.as_ref() }

    fn list(&self) -> Vec<String> {
        let mut out = vec![format!("term={} leader={}", self.term, self.leader.as_deref().unwrap_or("none"))];
        out.extend(self.candidates.iter().map(|c| format!("  candidate: {}", c)));
        out
    }
}

type SharedLeaderElection = Arc<std::sync::Mutex<LeaderElection>>;

/// Idempotent message deduplication.
struct MessageDedup {
    seen: std::collections::HashMap<String, u64>, // id → timestamp
    ttl: u64,
    clock: u64,
}

impl MessageDedup {
    fn new(ttl: u64) -> Self { Self { seen: std::collections::HashMap::new(), ttl, clock: 0 } }
    fn set_clock(&mut self, t: u64) { self.clock = t; }

    fn check(&mut self, msg_id: &str) -> bool {
        self.prune();
        if self.seen.contains_key(msg_id) { false } // duplicate
        else { self.seen.insert(msg_id.to_string(), self.clock); true } // new
    }

    fn prune(&mut self) {
        self.seen.retain(|_, ts| self.clock.saturating_sub(*ts) < self.ttl);
    }

    fn list(&self) -> Vec<String> {
        self.seen.iter().map(|(id, ts)| format!("{} ts={}", id, ts)).collect()
    }
}

type SharedMessageDedup = Arc<std::sync::Mutex<MessageDedup>>;

/// Group-based task throttling with fair sharing.
#[derive(Clone, Debug)]
struct ThrottleGroup { name: String, limit: u32, current: u32 }

struct TaskThrottleGroup {
    groups: Vec<ThrottleGroup>,
}

impl TaskThrottleGroup {
    fn new() -> Self { Self { groups: Vec::new() } }

    fn add_group(&mut self, name: &str, limit: u32) {
        self.groups.push(ThrottleGroup { name: name.to_string(), limit, current: 0 });
    }

    fn acquire(&mut self, group: &str) -> bool {
        if let Some(g) = self.groups.iter_mut().find(|g| g.name == group) {
            if g.current < g.limit { g.current += 1; true } else { false }
        } else { false }
    }

    fn release(&mut self, group: &str) {
        if let Some(g) = self.groups.iter_mut().find(|g| g.name == group) {
            g.current = g.current.saturating_sub(1);
        }
    }

    fn list(&self) -> Vec<String> {
        self.groups.iter().map(|g| format!("{} {}/{}", g.name, g.current, g.limit)).collect()
    }
}

type SharedTaskThrottleGroup = Arc<std::sync::Mutex<TaskThrottleGroup>>;

/// Bridge metrics to alerts — threshold crossing detection.
#[derive(Clone, Debug)]
struct MetricThreshold { name: String, metric: String, threshold: f64, above: bool, fired: bool }

struct MetricAlertBridge {
    thresholds: Vec<MetricThreshold>,
}

impl MetricAlertBridge {
    fn new() -> Self { Self { thresholds: Vec::new() } }

    fn add(&mut self, name: &str, metric: &str, threshold: f64, above: bool) {
        self.thresholds.push(MetricThreshold { name: name.to_string(), metric: metric.to_string(), threshold, above, fired: false });
    }

    fn check(&mut self, metric: &str, value: f64) -> Vec<String> {
        let mut alerts = Vec::new();
        for t in &mut self.thresholds {
            if t.metric == metric {
                let crossed = if t.above { value >= t.threshold } else { value <= t.threshold };
                if crossed && !t.fired { t.fired = true; alerts.push(format!("ALERT: {} ({}={:.2} threshold={:.2})", t.name, metric, value, t.threshold)); }
                else if !crossed { t.fired = false; }
            }
        }
        alerts
    }

    fn list(&self) -> Vec<String> {
        self.thresholds.iter().map(|t| format!("{} {} {} {:.2} fired={}",
            t.name, t.metric, if t.above { ">" } else { "<" }, t.threshold, t.fired)).collect()
    }
}

type SharedMetricAlertBridge = Arc<std::sync::Mutex<MetricAlertBridge>>;

/// Searchable agent capability index.
struct AgentCapabilityIndex {
    entries: Vec<(String, Vec<String>)>, // agent → capabilities
}

impl AgentCapabilityIndex {
    fn new() -> Self { Self { entries: Vec::new() } }

    fn register(&mut self, agent: &str, caps: Vec<&str>) {
        let caps: Vec<String> = caps.into_iter().map(|s| s.to_string()).collect();
        if let Some(e) = self.entries.iter_mut().find(|(a, _)| a == agent) {
            e.1 = caps;
        } else {
            self.entries.push((agent.to_string(), caps));
        }
    }

    fn search(&self, query: &str) -> Vec<String> {
        self.entries.iter().filter(|(_, caps)| caps.iter().any(|c| c.contains(query)))
            .map(|(a, _)| a.clone()).collect()
    }

    fn capabilities_of(&self, agent: &str) -> Vec<String> {
        self.entries.iter().find(|(a, _)| a == agent).map(|(_, c)| c.clone()).unwrap_or_default()
    }

    fn list(&self) -> Vec<String> {
        self.entries.iter().map(|(a, c)| format!("{}: [{}]", a, c.join(", "))).collect()
    }
}

type SharedAgentCapabilityIndex = Arc<std::sync::Mutex<AgentCapabilityIndex>>;

