/// Peer-to-peer state gossip — rumor spreading with convergence detection.
struct GossipSyncMgr {
    rumors: Vec<GossipRumor>,
    peers: Vec<String>,
    max_rounds: u32,
}

struct GossipRumor {
    id: String,
    payload: String,
    origin: String,
    round: u32,
    seen_by: Vec<String>,
}

impl GossipSyncMgr {
    fn new() -> Self {
        Self { rumors: Vec::new(), peers: Vec::new(), max_rounds: 10 }
    }
    fn add_peer(&mut self, peer: &str) {
        if !self.peers.contains(&peer.to_string()) {
            self.peers.push(peer.to_string());
        }
    }
    fn remove_peer(&mut self, peer: &str) {
        self.peers.retain(|p| p != peer);
    }
    fn spread(&mut self, id: &str, payload: &str, origin: &str) {
        self.rumors.push(GossipRumor {
            id: id.to_string(),
            payload: payload.to_string(),
            origin: origin.to_string(),
            round: 0,
            seen_by: vec![origin.to_string()],
        });
    }
    fn tick(&mut self) {
        for r in &mut self.rumors {
            if r.round < self.max_rounds {
                r.round += 1;
                for p in &self.peers {
                    if !r.seen_by.contains(p) {
                        r.seen_by.push(p.clone());
                    }
                }
            }
        }
    }
    fn converged(&self, id: &str) -> bool {
        if let Some(r) = self.rumors.iter().find(|r| r.id == id) {
            self.peers.iter().all(|p| r.seen_by.contains(p))
        } else {
            false
        }
    }
    fn get(&self, id: &str) -> Option<&GossipRumor> {
        self.rumors.iter().find(|r| r.id == id)
    }
    fn list(&self) -> &[GossipRumor] {
        &self.rumors
    }
}

type SharedGossipSyncMgr = Arc<std::sync::Mutex<GossipSyncMgr>>;

/// Schema versioning — register schemas, check backward/forward compatibility.
struct SchemaVersionReg {
    schemas: Vec<SchemaDef>,
}

struct SchemaDef {
    name: String,
    version: u32,
    fields: Vec<String>,
    ts: u64,
}

impl SchemaVersionReg {
    fn new() -> Self {
        Self { schemas: Vec::new() }
    }
    fn register(&mut self, name: &str, version: u32, fields: Vec<String>) {
        self.schemas.push(SchemaDef {
            name: name.to_string(),
            version,
            fields,
            ts: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
        });
    }
    fn latest(&self, name: &str) -> Option<&SchemaDef> {
        self.schemas.iter().filter(|s| s.name == name).max_by_key(|s| s.version)
    }
    fn get(&self, name: &str, version: u32) -> Option<&SchemaDef> {
        self.schemas.iter().find(|s| s.name == name && s.version == version)
    }
    fn backward_compatible(&self, name: &str, v_old: u32, v_new: u32) -> bool {
        let old = self.get(name, v_old);
        let new = self.get(name, v_new);
        match (old, new) {
            (Some(o), Some(n)) => o.fields.iter().all(|f| n.fields.contains(f)),
            _ => false,
        }
    }
    fn forward_compatible(&self, name: &str, v_old: u32, v_new: u32) -> bool {
        let old = self.get(name, v_old);
        let new = self.get(name, v_new);
        match (old, new) {
            (Some(o), Some(n)) => n.fields.iter().all(|f| o.fields.contains(f)),
            _ => false,
        }
    }
    fn versions_of(&self, name: &str) -> Vec<u32> {
        self.schemas.iter().filter(|s| s.name == name).map(|s| s.version).collect()
    }
}

type SharedSchemaVersionReg = Arc<std::sync::Mutex<SchemaVersionReg>>;

/// Batch execution — accumulate items, flush on size or manual trigger.
struct TaskBatchExec {
    batches: std::collections::HashMap<String, Vec<BatchItem>>,
    batch_size: usize,
    flushed: Vec<(String, Vec<BatchItem>)>,
}

#[derive(Clone)]
struct BatchItem {
    id: String,
    payload: String,
    ts: u64,
}

impl TaskBatchExec {
    fn new(batch_size: usize) -> Self {
        Self {
            batches: std::collections::HashMap::new(),
            batch_size,
            flushed: Vec::new(),
        }
    }
    fn add(&mut self, queue: &str, id: &str, payload: &str) -> bool {
        let items = self.batches.entry(queue.to_string()).or_default();
        items.push(BatchItem {
            id: id.to_string(),
            payload: payload.to_string(),
            ts: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
        });
        if items.len() >= self.batch_size {
            let batch = std::mem::take(items);
            self.flushed.push((queue.to_string(), batch));
            true
        } else {
            false
        }
    }
    fn flush(&mut self, queue: &str) -> Option<Vec<BatchItem>> {
        if let Some(items) = self.batches.get_mut(queue) {
            if items.is_empty() {
                return None;
            }
            let batch = std::mem::take(items);
            self.flushed.push((queue.to_string(), batch.clone()));
            Some(batch)
        } else {
            None
        }
    }
    fn pending(&self, queue: &str) -> usize {
        self.batches.get(queue).map(|v| v.len()).unwrap_or(0)
    }
    fn flushed_count(&self) -> usize {
        self.flushed.len()
    }
    fn queues(&self) -> Vec<String> {
        self.batches.keys().cloned().collect()
    }
}

type SharedTaskBatchExec = Arc<std::sync::Mutex<TaskBatchExec>>;

/// Failure domain isolation — assign agents to zones, quarantine/restore zones.
#[derive(Clone, PartialEq)]
enum IsoZoneStatus {
    Active,
    Quarantined,
}

struct AgentIsoZone {
    zones: std::collections::HashMap<String, IsoZoneStatus>,
    assignments: std::collections::HashMap<String, String>, // agent -> zone
}

impl AgentIsoZone {
    fn new() -> Self {
        Self {
            zones: std::collections::HashMap::new(),
            assignments: std::collections::HashMap::new(),
        }
    }
    fn create_zone(&mut self, zone: &str) {
        self.zones.entry(zone.to_string()).or_insert(IsoZoneStatus::Active);
    }
    fn assign(&mut self, agent: &str, zone: &str) {
        self.create_zone(zone);
        self.assignments.insert(agent.to_string(), zone.to_string());
    }
    fn quarantine(&mut self, zone: &str) {
        if let Some(s) = self.zones.get_mut(zone) {
            *s = IsoZoneStatus::Quarantined;
        }
    }
    fn restore(&mut self, zone: &str) {
        if let Some(s) = self.zones.get_mut(zone) {
            *s = IsoZoneStatus::Active;
        }
    }
    fn is_quarantined(&self, zone: &str) -> bool {
        self.zones.get(zone) == Some(&IsoZoneStatus::Quarantined)
    }
    fn agents_in_zone(&self, zone: &str) -> Vec<String> {
        self.assignments.iter()
            .filter(|(_, z)| z.as_str() == zone)
            .map(|(a, _)| a.clone())
            .collect()
    }
    fn zone_of(&self, agent: &str) -> Option<&str> {
        self.assignments.get(agent).map(|s| s.as_str())
    }
    fn list_zones(&self) -> Vec<(String, IsoZoneStatus)> {
        self.zones.iter().map(|(k, v)| (k.clone(), v.clone())).collect()
    }
}

type SharedAgentIsoZone = Arc<std::sync::Mutex<AgentIsoZone>>;

/// Log compaction — append entries, tombstone marking, compact to remove tombstoned.
struct LogCompactor {
    entries: Vec<CompactionEntry>,
    compaction_count: u32,
}

struct CompactionEntry {
    key: String,
    value: String,
    tombstone: bool,
    ts: u64,
}

impl LogCompactor {
    fn new() -> Self {
        Self { entries: Vec::new(), compaction_count: 0 }
    }
    fn append(&mut self, key: &str, value: &str) {
        self.entries.push(CompactionEntry {
            key: key.to_string(),
            value: value.to_string(),
            tombstone: false,
            ts: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
        });
    }
    fn delete(&mut self, key: &str) {
        self.entries.push(CompactionEntry {
            key: key.to_string(),
            value: String::new(),
            tombstone: true,
            ts: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
        });
    }
    fn compact(&mut self) {
        let mut latest: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
        for (i, e) in self.entries.iter().enumerate() {
            latest.insert(e.key.clone(), i);
        }
        let keep: std::collections::HashSet<usize> = latest.values().copied().collect();
        let mut compacted: Vec<CompactionEntry> = Vec::new();
        for (i, e) in self.entries.drain(..).enumerate() {
            if keep.contains(&i) && !e.tombstone {
                compacted.push(e);
            }
        }
        self.entries = compacted;
        self.compaction_count += 1;
    }
    fn get(&self, key: &str) -> Option<&str> {
        let latest = self.entries.iter().rev().find(|e| e.key == key)?;
        if latest.tombstone { None } else { Some(latest.value.as_str()) }
    }
    fn len(&self) -> usize {
        self.entries.len()
    }
    fn compaction_count(&self) -> u32 {
        self.compaction_count
    }
}

type SharedLogCompactor = Arc<std::sync::Mutex<LogCompactor>>;

