/// Cache coherence — key-value cache with TTL and LRU eviction.
struct CacheSyncMgr {
    entries: std::collections::HashMap<String, CacheSyncEntry>,
    max_size: usize,
    eviction_order: Vec<String>,
}

struct CacheSyncEntry {
    value: String,
    ts: u64,
    ttl_secs: u64,
}

impl CacheSyncMgr {
    fn new(max_size: usize) -> Self {
        Self { entries: std::collections::HashMap::new(), max_size, eviction_order: Vec::new() }
    }
    fn put(&mut self, key: &str, value: &str, ttl_secs: u64) {
        let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs();
        if self.entries.len() >= self.max_size && !self.entries.contains_key(key) {
            if let Some(evict_key) = self.eviction_order.first().cloned() {
                self.entries.remove(&evict_key);
                self.eviction_order.retain(|k| k != &evict_key);
            }
        }
        self.eviction_order.retain(|k| k != key);
        self.eviction_order.push(key.to_string());
        self.entries.insert(key.to_string(), CacheSyncEntry { value: value.to_string(), ts: now, ttl_secs });
    }
    fn get(&mut self, key: &str) -> Option<&str> {
        let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs();
        if let Some(e) = self.entries.get(key) {
            if e.ttl_secs > 0 && now - e.ts > e.ttl_secs {
                self.entries.remove(key);
                self.eviction_order.retain(|k| k != key);
                return None;
            }
            self.eviction_order.retain(|k| k != key);
            self.eviction_order.push(key.to_string());
            self.entries.get(key).map(|e| e.value.as_str())
        } else {
            None
        }
    }
    fn invalidate(&mut self, key: &str) {
        self.entries.remove(key);
        self.eviction_order.retain(|k| k != key);
    }
    fn len(&self) -> usize { self.entries.len() }
    fn keys(&self) -> Vec<String> { self.entries.keys().cloned().collect() }
}

type SharedCacheSyncMgr = Arc<std::sync::Mutex<CacheSyncMgr>>;

/// DAG-based task dependencies — add tasks, add edges, find ready-to-run.
struct TaskDependencyGraph {
    tasks: std::collections::HashSet<String>,
    deps: Vec<(String, String)>, // (dependency, dependent)
    completed: std::collections::HashSet<String>,
}

impl TaskDependencyGraph {
    fn new() -> Self {
        Self { tasks: std::collections::HashSet::new(), deps: Vec::new(), completed: std::collections::HashSet::new() }
    }
    fn add_task(&mut self, task: &str) {
        self.tasks.insert(task.to_string());
    }
    fn add_dep(&mut self, task: &str, depends_on: &str) {
        self.tasks.insert(task.to_string());
        self.tasks.insert(depends_on.to_string());
        self.deps.push((depends_on.to_string(), task.to_string()));
    }
    fn complete(&mut self, task: &str) {
        self.completed.insert(task.to_string());
    }
    fn ready(&self) -> Vec<String> {
        self.tasks.iter().filter(|t| {
            !self.completed.contains(t.as_str()) &&
            self.deps.iter().filter(|(_, dep)| dep == *t).all(|(prereq, _)| self.completed.contains(prereq.as_str()))
        }).cloned().collect()
    }
    fn is_complete(&self) -> bool {
        self.tasks.iter().all(|t| self.completed.contains(t))
    }
    fn pending_count(&self) -> usize {
        self.tasks.len() - self.completed.len()
    }
}

type SharedTaskDependencyGraph = Arc<std::sync::Mutex<TaskDependencyGraph>>;

/// Aggregate heartbeat stats — per-agent last-seen, detect fleet-wide outages.
struct AgentHeartbeatAgg {
    heartbeats: std::collections::HashMap<String, u64>, // agent -> last_ts
    threshold_secs: u64,
}

impl AgentHeartbeatAgg {
    fn new(threshold_secs: u64) -> Self {
        Self { heartbeats: std::collections::HashMap::new(), threshold_secs }
    }
    fn beat(&mut self, agent: &str) {
        let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs();
        self.heartbeats.insert(agent.to_string(), now);
    }
    fn beat_with_ts(&mut self, agent: &str, ts: u64) {
        self.heartbeats.insert(agent.to_string(), ts);
    }
    fn stale_agents(&self, now: u64) -> Vec<String> {
        self.heartbeats.iter()
            .filter(|(_, ts)| now - *ts > self.threshold_secs)
            .map(|(a, _)| a.clone())
            .collect()
    }
    fn fleet_health(&self, now: u64) -> f64 {
        if self.heartbeats.is_empty() { return 1.0; }
        let healthy = self.heartbeats.values().filter(|ts| now - *ts <= self.threshold_secs).count();
        healthy as f64 / self.heartbeats.len() as f64
    }
    fn agent_count(&self) -> usize { self.heartbeats.len() }
    fn last_seen(&self, agent: &str) -> Option<u64> { self.heartbeats.get(agent).copied() }
}

type SharedAgentHeartbeatAgg = Arc<std::sync::Mutex<AgentHeartbeatAgg>>;

