/// Resource locking — lock/unlock, detect held locks, timeout-based release.
struct ResourceLockMgr {
    locks: std::collections::HashMap<String, ResourceLock>,
}

struct ResourceLock {
    owner: String,
    acquired_at: u64,
}

impl ResourceLockMgr {
    fn new() -> Self { Self { locks: std::collections::HashMap::new() } }
    fn try_lock(&mut self, resource: &str, owner: &str) -> bool {
        if self.locks.contains_key(resource) { return false; }
        let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs();
        self.locks.insert(resource.to_string(), ResourceLock { owner: owner.to_string(), acquired_at: now });
        true
    }
    fn unlock(&mut self, resource: &str, owner: &str) -> bool {
        if let Some(lock) = self.locks.get(resource) {
            if lock.owner == owner {
                self.locks.remove(resource);
                return true;
            }
        }
        false
    }
    fn owner_of(&self, resource: &str) -> Option<&str> {
        self.locks.get(resource).map(|l| l.owner.as_str())
    }
    fn locks_by(&self, owner: &str) -> Vec<String> {
        self.locks.iter().filter(|(_, l)| l.owner == owner).map(|(r, _)| r.clone()).collect()
    }
    fn force_release(&mut self, resource: &str) -> bool {
        self.locks.remove(resource).is_some()
    }
    fn list(&self) -> Vec<(String, String)> {
        self.locks.iter().map(|(r, l)| (r.clone(), l.owner.clone())).collect()
    }
}

type SharedResourceLockMgr = Arc<std::sync::Mutex<ResourceLockMgr>>;

