/// Replay buffer — append events, seek by offset, replay a window.
struct EventReplayBuffer {
    events: Vec<RBufEvent>,
}

struct RBufEvent {
    seq: u64,
    payload: String,
    ts: u64,
}

impl EventReplayBuffer {
    fn new() -> Self { Self { events: Vec::new() } }
    fn append(&mut self, payload: &str) -> u64 {
        let seq = self.events.len() as u64;
        let ts = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs();
        self.events.push(RBufEvent { seq, payload: payload.to_string(), ts });
        seq
    }
    fn replay_from(&self, offset: u64, limit: usize) -> Vec<&RBufEvent> {
        self.events.iter().filter(|e| e.seq >= offset).take(limit).collect()
    }
    fn latest_seq(&self) -> Option<u64> {
        self.events.last().map(|e| e.seq)
    }
    fn len(&self) -> usize { self.events.len() }
    fn get(&self, seq: u64) -> Option<&RBufEvent> {
        self.events.get(seq as usize)
    }
}

type SharedEventReplayBuffer = Arc<std::sync::Mutex<EventReplayBuffer>>;

/// Credential vault — store secrets, grant/revoke access per agent.
struct AgentCredentialVault {
    secrets: std::collections::HashMap<String, String>,
    acl: std::collections::HashMap<String, Vec<String>>, // secret_name -> allowed agents
}

impl AgentCredentialVault {
    fn new() -> Self { Self { secrets: std::collections::HashMap::new(), acl: std::collections::HashMap::new() } }
    fn store(&mut self, name: &str, value: &str) {
        self.secrets.insert(name.to_string(), value.to_string());
    }
    fn grant(&mut self, name: &str, agent: &str) {
        self.acl.entry(name.to_string()).or_default().push(agent.to_string());
    }
    fn revoke(&mut self, name: &str, agent: &str) {
        if let Some(list) = self.acl.get_mut(name) {
            list.retain(|a| a != agent);
        }
    }
    fn get(&self, name: &str, agent: &str) -> Option<&str> {
        if self.acl.get(name).map(|l| l.contains(&agent.to_string())).unwrap_or(false) {
            self.secrets.get(name).map(|s| s.as_str())
        } else {
            None
        }
    }
    fn list_secrets(&self) -> Vec<String> { self.secrets.keys().cloned().collect() }
    fn allowed_agents(&self, name: &str) -> Vec<String> {
        self.acl.get(name).cloned().unwrap_or_default()
    }
}

type SharedAgentCredentialVault = Arc<std::sync::Mutex<AgentCredentialVault>>;

/// Metric rollup — aggregate values over time windows, downsample.
struct MetricRollupEngine {
    series: std::collections::HashMap<String, Vec<(u64, f64)>>, // metric -> [(ts, value)]
}

impl MetricRollupEngine {
    fn new() -> Self { Self { series: std::collections::HashMap::new() } }
    fn record(&mut self, metric: &str, ts: u64, value: f64) {
        self.series.entry(metric.to_string()).or_default().push((ts, value));
    }
    fn rollup_avg(&self, metric: &str, window_start: u64, window_end: u64) -> Option<f64> {
        let points: Vec<f64> = self.series.get(metric)?
            .iter().filter(|(ts, _)| *ts >= window_start && *ts <= window_end)
            .map(|(_, v)| *v).collect();
        if points.is_empty() { return None; }
        Some(points.iter().sum::<f64>() / points.len() as f64)
    }
    fn rollup_max(&self, metric: &str, window_start: u64, window_end: u64) -> Option<f64> {
        self.series.get(metric)?
            .iter().filter(|(ts, _)| *ts >= window_start && *ts <= window_end)
            .map(|(_, v)| *v).max_by(|a, b| a.partial_cmp(b).unwrap())
    }
    fn count(&self, metric: &str) -> usize {
        self.series.get(metric).map(|v| v.len()).unwrap_or(0)
    }
    fn metrics(&self) -> Vec<String> { self.series.keys().cloned().collect() }
}

type SharedMetricRollupEngine = Arc<std::sync::Mutex<MetricRollupEngine>>;

/// Retry scheduling — exponential backoff, max attempts, jitter.
struct TaskRetryScheduler {
    tasks: std::collections::HashMap<String, RetryState>,
}

struct RetryState {
    attempts: u32,
    max_attempts: u32,
    base_delay_ms: u64,
    next_retry_ms: u64,
    exhausted: bool,
}

impl TaskRetryScheduler {
    fn new() -> Self { Self { tasks: std::collections::HashMap::new() } }
    fn register(&mut self, task: &str, max_attempts: u32, base_delay_ms: u64) {
        self.tasks.insert(task.to_string(), RetryState {
            attempts: 0, max_attempts, base_delay_ms, next_retry_ms: base_delay_ms, exhausted: false,
        });
    }
    fn fail(&mut self, task: &str) -> Option<u64> {
        let s = self.tasks.get_mut(task)?;
        s.attempts += 1;
        if s.attempts >= s.max_attempts {
            s.exhausted = true;
            return None;
        }
        s.next_retry_ms = s.base_delay_ms * (1u64 << s.attempts.min(10));
        Some(s.next_retry_ms)
    }
    fn reset(&mut self, task: &str) {
        if let Some(s) = self.tasks.get_mut(task) {
            s.attempts = 0;
            s.exhausted = false;
            s.next_retry_ms = s.base_delay_ms;
        }
    }
    fn is_exhausted(&self, task: &str) -> bool {
        self.tasks.get(task).map(|s| s.exhausted).unwrap_or(false)
    }
    fn attempts(&self, task: &str) -> u32 {
        self.tasks.get(task).map(|s| s.attempts).unwrap_or(0)
    }
    fn list(&self) -> Vec<(String, u32, bool)> {
        self.tasks.iter().map(|(k, v)| (k.clone(), v.attempts, v.exhausted)).collect()
    }
}

type SharedTaskRetryScheduler = Arc<std::sync::Mutex<TaskRetryScheduler>>;

/// Multi-layer config merge — defaults < env < user, last layer wins.
struct ConfigMergeEngine {
    layers: Vec<(String, std::collections::HashMap<String, String>)>,
}

impl ConfigMergeEngine {
    fn new() -> Self { Self { layers: Vec::new() } }
    fn add_layer(&mut self, name: &str) {
        self.layers.push((name.to_string(), std::collections::HashMap::new()));
    }
    fn set(&mut self, layer: &str, key: &str, value: &str) {
        if let Some((_, map)) = self.layers.iter_mut().find(|(n, _)| n == layer) {
            map.insert(key.to_string(), value.to_string());
        }
    }
    fn resolve(&self, key: &str) -> Option<String> {
        for (_, map) in self.layers.iter().rev() {
            if let Some(v) = map.get(key) {
                return Some(v.clone());
            }
        }
        None
    }
    fn all_resolved(&self) -> std::collections::HashMap<String, String> {
        let mut merged = std::collections::HashMap::new();
        for (_, map) in &self.layers {
            for (k, v) in map {
                merged.insert(k.clone(), v.clone());
            }
        }
        merged
    }
    fn layer_names(&self) -> Vec<String> {
        self.layers.iter().map(|(n, _)| n.clone()).collect()
    }
}

type SharedConfigMergeEngine = Arc<std::sync::Mutex<ConfigMergeEngine>>;

