/// Workflow checkpointing — save/restore state at named checkpoints.
struct WorkflowCheckpointer {
    checkpoints: std::collections::HashMap<String, Vec<(String, String)>>, // workflow -> [(name, data)]
}

impl WorkflowCheckpointer {
    fn new() -> Self { Self { checkpoints: std::collections::HashMap::new() } }
    fn save(&mut self, workflow: &str, name: &str, data: &str) {
        self.checkpoints.entry(workflow.to_string()).or_default()
            .push((name.to_string(), data.to_string()));
    }
    fn restore(&self, workflow: &str, name: &str) -> Option<&str> {
        self.checkpoints.get(workflow)?
            .iter().rev().find(|(n, _)| n == name)
            .map(|(_, d)| d.as_str())
    }
    fn latest(&self, workflow: &str) -> Option<(&str, &str)> {
        self.checkpoints.get(workflow)?.last().map(|(n, d)| (n.as_str(), d.as_str()))
    }
    fn list(&self, workflow: &str) -> Vec<&str> {
        self.checkpoints.get(workflow).map(|v| v.iter().map(|(n, _)| n.as_str()).collect()).unwrap_or_default()
    }
    fn workflows(&self) -> Vec<String> { self.checkpoints.keys().cloned().collect() }
}

