/// Per-agent cooldown — set cooldown periods, check readiness.
struct AgentCooldownMgr {
    cooldowns: std::collections::HashMap<String, (u64, u64)>, // agent -> (cooldown_until_ts, duration_secs)
}

impl AgentCooldownMgr {
    fn new() -> Self { Self { cooldowns: std::collections::HashMap::new() } }
    fn set_cooldown(&mut self, agent: &str, duration_secs: u64) {
        let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs();
        self.cooldowns.insert(agent.to_string(), (now + duration_secs, duration_secs));
    }
    fn set_cooldown_at(&mut self, agent: &str, now: u64, duration_secs: u64) {
        self.cooldowns.insert(agent.to_string(), (now + duration_secs, duration_secs));
    }
    fn is_ready(&self, agent: &str, now: u64) -> bool {
        match self.cooldowns.get(agent) {
            Some((until, _)) => now >= *until,
            None => true,
        }
    }
    fn remaining(&self, agent: &str, now: u64) -> u64 {
        match self.cooldowns.get(agent) {
            Some((until, _)) => if now < *until { until - now } else { 0 },
            None => 0,
        }
    }
    fn reset(&mut self, agent: &str) {
        self.cooldowns.remove(agent);
    }
    fn list(&self) -> Vec<(String, u64)> {
        self.cooldowns.iter().map(|(a, (_, d))| (a.clone(), *d)).collect()
    }
}

type SharedAgentCooldownMgr = Arc<std::sync::Mutex<AgentCooldownMgr>>;

/// Multi-stage data pipeline — push data through ordered stages.
struct DPStage {
    name: String,
    transform: String, // description of transform
}

struct DataPipelineMgr {
    pipelines: std::collections::HashMap<String, Vec<DPStage>>,
    results: std::collections::HashMap<String, Vec<String>>,
}

impl DataPipelineMgr {
    fn new() -> Self { Self { pipelines: std::collections::HashMap::new(), results: std::collections::HashMap::new() } }
    fn create(&mut self, pipeline: &str, stages: Vec<(&str, &str)>) {
        let s: Vec<DPStage> = stages.into_iter()
            .map(|(n, t)| DPStage { name: n.to_string(), transform: t.to_string() })
            .collect();
        self.pipelines.insert(pipeline.to_string(), s);
    }
    fn push(&mut self, pipeline: &str, data: &str) -> Vec<String> {
        let stages = match self.pipelines.get(pipeline) {
            Some(s) => s.len(),
            None => return Vec::new(),
        };
        let mut result = data.to_string();
        let mut trace = Vec::new();
        for i in 0..stages {
            let stage_name = &self.pipelines[pipeline][i].name;
            result = format!("{}[{}]", result, stage_name);
            trace.push(result.clone());
        }
        self.results.entry(pipeline.to_string()).or_default().push(result);
        trace
    }
    fn stage_count(&self, pipeline: &str) -> usize {
        self.pipelines.get(pipeline).map(|s| s.len()).unwrap_or(0)
    }
    fn output(&self, pipeline: &str) -> Vec<&str> {
        self.results.get(pipeline).map(|v| v.iter().map(|s| s.as_str()).collect()).unwrap_or_default()
    }
    fn list(&self) -> Vec<String> { self.pipelines.keys().cloned().collect() }
}

type SharedDataPipelineMgr = Arc<std::sync::Mutex<DataPipelineMgr>>;

/// Shared quota pool — agents share a pool, fair allocation.
struct QuotaPoolSharer {
    pools: std::collections::HashMap<String, (u64, u64)>, // pool -> (total, used)
}

impl QuotaPoolSharer {
    fn new() -> Self { Self { pools: std::collections::HashMap::new() } }
    fn create_pool(&mut self, name: &str, total: u64) {
        self.pools.insert(name.to_string(), (total, 0));
    }
    fn acquire(&mut self, pool: &str, amount: u64) -> bool {
        if let Some((total, used)) = self.pools.get_mut(pool) {
            if *used + amount <= *total {
                *used += amount;
                return true;
            }
        }
        false
    }
    fn release(&mut self, pool: &str, amount: u64) {
        if let Some((_, used)) = self.pools.get_mut(pool) {
            *used = used.saturating_sub(amount);
        }
    }
    fn available(&self, pool: &str) -> u64 {
        self.pools.get(pool).map(|(t, u)| t - u).unwrap_or(0)
    }
    fn utilization(&self, pool: &str) -> f64 {
        self.pools.get(pool).map(|(t, u)| if *t == 0 { 0.0 } else { *u as f64 / *t as f64 }).unwrap_or(0.0)
    }
    fn list(&self) -> Vec<(String, u64, u64)> {
        self.pools.iter().map(|(n, (t, u))| (n.clone(), *t, *u)).collect()
    }
}

type SharedQuotaPoolSharer = Arc<std::sync::Mutex<QuotaPoolSharer>>;

/// Composable event filter chain — evaluate events through ordered filters.
struct EventFilter {
    name: String,
    pattern: String, // simple pattern match
    action: String,  // "pass" or "drop"
}

struct EventFilterChain {
    filters: Vec<EventFilter>,
}

impl EventFilterChain {
    fn new() -> Self { Self { filters: Vec::new() } }
    fn add(&mut self, name: &str, pattern: &str, action: &str) {
        self.filters.push(EventFilter {
            name: name.to_string(),
            pattern: pattern.to_string(),
            action: action.to_string(),
        });
    }
    fn evaluate(&self, event: &str) -> bool {
        for f in &self.filters {
            if event.contains(&f.pattern) {
                return f.action == "pass";
            }
        }
        true // default pass
    }
    fn remove(&mut self, name: &str) {
        self.filters.retain(|f| f.name != name);
    }
    fn len(&self) -> usize { self.filters.len() }
    fn list(&self) -> Vec<(&str, &str, &str)> {
        self.filters.iter().map(|f| (f.name.as_str(), f.pattern.as_str(), f.action.as_str())).collect()
    }
}

type SharedEventFilterChain = Arc<std::sync::Mutex<EventFilterChain>>;

