/// Workload prediction — moving average from historical load samples.
struct WorkloadPredictor {
    samples: Vec<f64>,
    window: usize,
}

impl WorkloadPredictor {
    fn new(window: usize) -> Self { Self { samples: Vec::new(), window: window.max(1) } }
    fn record(&mut self, load: f64) { self.samples.push(load); }
    fn predict(&self) -> f64 {
        if self.samples.is_empty() { return 0.0; }
        let start = if self.samples.len() > self.window { self.samples.len() - self.window } else { 0 };
        let window = &self.samples[start..];
        window.iter().sum::<f64>() / window.len() as f64
    }
    fn trend(&self) -> f64 {
        if self.samples.len() < 2 { return 0.0; }
        let last = *self.samples.last().unwrap();
        let prev = self.samples[self.samples.len() - 2];
        last - prev
    }
    fn sample_count(&self) -> usize { self.samples.len() }
    fn clear(&mut self) { self.samples.clear(); }
}

type SharedWorkloadPredictor = Arc<std::sync::Mutex<WorkloadPredictor>>;

/// Agent reputation — score agents on success/failure, with decay.
struct AgentReputation {
    scores: std::collections::HashMap<String, f64>,
}

impl AgentReputation {
    fn new() -> Self { Self { scores: std::collections::HashMap::new() } }
    fn record_success(&mut self, agent: &str, weight: f64) {
        let s = self.scores.entry(agent.to_string()).or_insert(50.0);
        *s = (*s + weight).min(100.0);
    }
    fn record_failure(&mut self, agent: &str, weight: f64) {
        let s = self.scores.entry(agent.to_string()).or_insert(50.0);
        *s = (*s - weight).max(0.0);
    }
    fn score(&self, agent: &str) -> f64 {
        self.scores.get(agent).copied().unwrap_or(50.0)
    }
    fn decay(&mut self, factor: f64) {
        for s in self.scores.values_mut() {
            *s *= factor;
        }
    }
    fn top_agents(&self, n: usize) -> Vec<(String, f64)> {
        let mut sorted: Vec<_> = self.scores.iter().map(|(k, v)| (k.clone(), *v)).collect();
        sorted.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        sorted.truncate(n);
        sorted
    }
    fn agents(&self) -> Vec<String> { self.scores.keys().cloned().collect() }
}

type SharedAgentReputation = Arc<std::sync::Mutex<AgentReputation>>;

/// Task escalation — chain of escalation levels, escalate after N failures.
struct TaskEscalation {
    chains: std::collections::HashMap<String, Vec<String>>, // task -> escalation chain
    failures: std::collections::HashMap<String, usize>,
    threshold: usize,
}

impl TaskEscalation {
    fn new(threshold: usize) -> Self {
        Self { chains: std::collections::HashMap::new(), failures: std::collections::HashMap::new(), threshold }
    }
    fn set_chain(&mut self, task: &str, chain: Vec<String>) {
        self.chains.insert(task.to_string(), chain);
    }
    fn record_failure(&mut self, task: &str) {
        *self.failures.entry(task.to_string()).or_insert(0) += 1;
    }
    fn current_level(&self, task: &str) -> usize {
        let fails = self.failures.get(task).copied().unwrap_or(0);
        if self.threshold == 0 { return 0; }
        fails / self.threshold
    }
    fn current_handler(&self, task: &str) -> Option<&str> {
        let chain = self.chains.get(task)?;
        let level = self.current_level(task).min(chain.len().saturating_sub(1));
        chain.get(level).map(|s| s.as_str())
    }
    fn is_fully_escalated(&self, task: &str) -> bool {
        let chain_len = self.chains.get(task).map(|c| c.len()).unwrap_or(0);
        if chain_len == 0 { return true; }
        self.current_level(task) >= chain_len - 1
    }
    fn reset(&mut self, task: &str) { self.failures.remove(task); }
}

type SharedTaskEscalation = Arc<std::sync::Mutex<TaskEscalation>>;

/// Per-key rate limiting — window-based counters.
struct RateLimitBucket {
    limits: std::collections::HashMap<String, (usize, usize)>, // key -> (count, max)
}

impl RateLimitBucket {
    fn new() -> Self { Self { limits: std::collections::HashMap::new() } }
    fn set_limit(&mut self, key: &str, max: usize) {
        self.limits.entry(key.to_string()).or_insert((0, max)).1 = max;
    }
    fn try_acquire(&mut self, key: &str) -> bool {
        if let Some((count, max)) = self.limits.get_mut(key) {
            if *count < *max { *count += 1; true } else { false }
        } else {
            false
        }
    }
    fn remaining(&self, key: &str) -> usize {
        self.limits.get(key).map(|(c, m)| m.saturating_sub(*c)).unwrap_or(0)
    }
    fn reset(&mut self, key: &str) {
        if let Some((count, _)) = self.limits.get_mut(key) { *count = 0; }
    }
    fn reset_all(&mut self) {
        for (count, _) in self.limits.values_mut() { *count = 0; }
    }
    fn keys(&self) -> Vec<String> { self.limits.keys().cloned().collect() }
}

type SharedRateLimitBucket = Arc<std::sync::Mutex<RateLimitBucket>>;

