/// Per-source ingress rate control — allow/deny based on request count per window.
struct IngressThrottler {
    counts: std::collections::HashMap<String, usize>,
    limits: std::collections::HashMap<String, usize>,
}

impl IngressThrottler {
    fn new() -> Self { Self { counts: std::collections::HashMap::new(), limits: std::collections::HashMap::new() } }
    fn set_limit(&mut self, source: &str, max: usize) {
        self.limits.insert(source.to_string(), max);
        self.counts.entry(source.to_string()).or_insert(0);
    }
    fn allow(&mut self, source: &str) -> bool {
        let max = self.limits.get(source).copied().unwrap_or(usize::MAX);
        let count = self.counts.entry(source.to_string()).or_insert(0);
        if *count < max { *count += 1; true } else { false }
    }
    fn reset(&mut self, source: &str) {
        if let Some(c) = self.counts.get_mut(source) { *c = 0; }
    }
    fn reset_all(&mut self) {
        for c in self.counts.values_mut() { *c = 0; }
    }
    fn denied_count(&self, source: &str) -> usize {
        let max = self.limits.get(source).copied().unwrap_or(usize::MAX);
        let count = self.counts.get(source).copied().unwrap_or(0);
        count.saturating_sub(max)
    }
    fn sources(&self) -> Vec<String> { self.limits.keys().cloned().collect() }
}

type SharedIngressThrottler = Arc<std::sync::Mutex<IngressThrottler>>;

/// Task duration log — record task durations, compute avg and p99.
struct TaskDurationLog {
    durations: std::collections::HashMap<String, Vec<f64>>, // task_type -> durations_ms
}

impl TaskDurationLog {
    fn new() -> Self { Self { durations: std::collections::HashMap::new() } }
    fn record(&mut self, task_type: &str, duration_ms: f64) {
        self.durations.entry(task_type.to_string()).or_default().push(duration_ms);
    }
    fn avg(&self, task_type: &str) -> f64 {
        let d = match self.durations.get(task_type) { Some(v) if !v.is_empty() => v, _ => return 0.0 };
        d.iter().sum::<f64>() / d.len() as f64
    }
    fn p99(&self, task_type: &str) -> f64 {
        let d = match self.durations.get(task_type) { Some(v) if !v.is_empty() => v, _ => return 0.0 };
        let mut sorted = d.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let idx = ((sorted.len() as f64) * 0.99).ceil() as usize;
        sorted[idx.min(sorted.len()) - 1]
    }
    fn count(&self, task_type: &str) -> usize {
        self.durations.get(task_type).map(|v| v.len()).unwrap_or(0)
    }
    fn task_types(&self) -> Vec<String> { self.durations.keys().cloned().collect() }
    fn clear(&mut self, task_type: &str) { self.durations.remove(task_type); }
}

type SharedTaskDurationLog = Arc<std::sync::Mutex<TaskDurationLog>>;

/// Per-tenant quota tracking — allocate, consume, check remaining.
struct TenantQuotaTracker {
    quotas: std::collections::HashMap<String, (usize, usize)>, // tenant -> (used, limit)
}

impl TenantQuotaTracker {
    fn new() -> Self { Self { quotas: std::collections::HashMap::new() } }
    fn set_quota(&mut self, tenant: &str, limit: usize) {
        self.quotas.entry(tenant.to_string()).or_insert((0, limit)).1 = limit;
    }
    fn consume(&mut self, tenant: &str, amount: usize) -> bool {
        if let Some((used, limit)) = self.quotas.get_mut(tenant) {
            if *used + amount <= *limit { *used += amount; true } else { false }
        } else { false }
    }
    fn remaining(&self, tenant: &str) -> usize {
        self.quotas.get(tenant).map(|(u, l)| l.saturating_sub(*u)).unwrap_or(0)
    }
    fn utilization(&self, tenant: &str) -> f64 {
        self.quotas.get(tenant).map(|(u, l)| if *l == 0 { 0.0 } else { *u as f64 / *l as f64 }).unwrap_or(0.0)
    }
    fn reset(&mut self, tenant: &str) {
        if let Some((used, _)) = self.quotas.get_mut(tenant) { *used = 0; }
    }
    fn tenants(&self) -> Vec<String> { self.quotas.keys().cloned().collect() }
}

type SharedTenantQuotaTracker = Arc<std::sync::Mutex<TenantQuotaTracker>>;

