/// Vector clock — distributed version tracking, merge, compare.
struct VersionVector {
    clocks: std::collections::HashMap<String, u64>,
}

impl VersionVector {
    fn new() -> Self { Self { clocks: std::collections::HashMap::new() } }
    fn increment(&mut self, node: &str) {
        *self.clocks.entry(node.to_string()).or_insert(0) += 1;
    }
    fn get(&self, node: &str) -> u64 {
        self.clocks.get(node).copied().unwrap_or(0)
    }
    fn merge(&mut self, other: &VersionVector) {
        for (k, v) in &other.clocks {
            let entry = self.clocks.entry(k.clone()).or_insert(0);
            *entry = (*entry).max(*v);
        }
    }
    fn dominates(&self, other: &VersionVector) -> bool {
        for (k, v) in &other.clocks {
            if self.get(k) < *v { return false; }
        }
        true
    }
    fn concurrent_with(&self, other: &VersionVector) -> bool {
        !self.dominates(other) && !other.dominates(self)
    }
    fn nodes(&self) -> Vec<String> { self.clocks.keys().cloned().collect() }
}

type SharedVersionVector = Arc<std::sync::Mutex<VersionVector>>;

/// Backpressure valve — open/close based on watermark thresholds.
struct BackpressureValve {
    current_load: usize,
    high_watermark: usize,
    low_watermark: usize,
    closed: bool,
}

impl BackpressureValve {
    fn new(low: usize, high: usize) -> Self {
        Self { current_load: 0, high_watermark: high, low_watermark: low, closed: false }
    }
    fn add_load(&mut self, n: usize) {
        self.current_load += n;
        if self.current_load >= self.high_watermark { self.closed = true; }
    }
    fn remove_load(&mut self, n: usize) {
        self.current_load = self.current_load.saturating_sub(n);
        if self.current_load <= self.low_watermark { self.closed = false; }
    }
    fn is_open(&self) -> bool { !self.closed }
    fn load(&self) -> usize { self.current_load }
    fn utilization(&self) -> f64 {
        if self.high_watermark == 0 { 0.0 } else { self.current_load as f64 / self.high_watermark as f64 }
    }
}

type SharedBackpressureValve = Arc<std::sync::Mutex<BackpressureValve>>;

/// Lease-based ownership for agents — acquire, renew, expire.
struct AgentLeaseManager {
    leases: std::collections::HashMap<String, (String, u64)>, // resource -> (owner, expiry_ts)
}

impl AgentLeaseManager {
    fn new() -> Self { Self { leases: std::collections::HashMap::new() } }
    fn acquire(&mut self, resource: &str, owner: &str, now: u64, ttl: u64) -> bool {
        if let Some((_, exp)) = self.leases.get(resource) {
            if *exp > now { return false; } // already held
        }
        self.leases.insert(resource.to_string(), (owner.to_string(), now + ttl));
        true
    }
    fn renew(&mut self, resource: &str, owner: &str, now: u64, ttl: u64) -> bool {
        if let Some((o, exp)) = self.leases.get_mut(resource) {
            if o == owner && *exp > now { *exp = now + ttl; return true; }
        }
        false
    }
    fn release(&mut self, resource: &str, owner: &str) -> bool {
        if let Some((o, _)) = self.leases.get(resource) {
            if o == owner { self.leases.remove(resource); return true; }
        }
        false
    }
    fn holder(&self, resource: &str, now: u64) -> Option<&str> {
        self.leases.get(resource).and_then(|(o, exp)| if *exp > now { Some(o.as_str()) } else { None })
    }
    fn expire(&mut self, now: u64) {
        self.leases.retain(|_, (_, exp)| *exp > now);
    }
}

type SharedAgentLeaseManager = Arc<std::sync::Mutex<AgentLeaseManager>>;

/// Cooperative cancellation tokens.
struct TaskCancelToken {
    cancelled: std::collections::HashSet<String>,
}

impl TaskCancelToken {
    fn new() -> Self { Self { cancelled: std::collections::HashSet::new() } }
    fn cancel(&mut self, token: &str) { self.cancelled.insert(token.to_string()); }
    fn is_cancelled(&self, token: &str) -> bool { self.cancelled.contains(token) }
    fn reset(&mut self, token: &str) { self.cancelled.remove(token); }
    fn active_cancellations(&self) -> usize { self.cancelled.len() }
    fn cancel_all_with_prefix(&mut self, prefix: &str) {
        // mark all existing as cancelled that match prefix — just record the prefix itself
        self.cancelled.insert(format!("__prefix:{}", prefix));
    }
    fn is_prefix_cancelled(&self, token: &str) -> bool {
        self.cancelled.iter().any(|c| {
            if let Some(p) = c.strip_prefix("__prefix:") { token.starts_with(p) } else { c == token }
        })
    }
}

type SharedTaskCancelToken = Arc<std::sync::Mutex<TaskCancelToken>>;

/// Health check aggregator — multiple sources, overall status.
#[derive(Clone, PartialEq, Debug)]
enum HCAggStatus { Healthy, Degraded, Unhealthy, Unknown }

struct HealthCheckAggregator {
    checks: std::collections::HashMap<String, HCAggStatus>,
}

impl HealthCheckAggregator {
    fn new() -> Self { Self { checks: std::collections::HashMap::new() } }
    fn report(&mut self, source: &str, status: HCAggStatus) {
        self.checks.insert(source.to_string(), status);
    }
    fn status_of(&self, source: &str) -> &HCAggStatus {
        self.checks.get(source).unwrap_or(&HCAggStatus::Unknown)
    }
    fn overall(&self) -> HCAggStatus {
        if self.checks.is_empty() { return HCAggStatus::Unknown; }
        let has_unhealthy = self.checks.values().any(|s| *s == HCAggStatus::Unhealthy);
        let has_degraded = self.checks.values().any(|s| *s == HCAggStatus::Degraded);
        if has_unhealthy { HCAggStatus::Unhealthy }
        else if has_degraded { HCAggStatus::Degraded }
        else { HCAggStatus::Healthy }
    }
    fn sources(&self) -> Vec<String> { self.checks.keys().cloned().collect() }
    fn healthy_count(&self) -> usize {
        self.checks.values().filter(|s| **s == HCAggStatus::Healthy).count()
    }
}

type SharedHealthCheckAggregator = Arc<std::sync::Mutex<HealthCheckAggregator>>;

