/// Agent credit ledger — track credits (budget) per agent.
struct AgentCreditLedger {
    balances: std::collections::HashMap<String, f64>,
}

impl AgentCreditLedger {
    fn new() -> Self { Self { balances: std::collections::HashMap::new() } }
    fn deposit(&mut self, agent: &str, amount: f64) {
        *self.balances.entry(agent.to_string()).or_insert(0.0) += amount;
    }
    fn spend(&mut self, agent: &str, amount: f64) -> bool {
        if let Some(bal) = self.balances.get_mut(agent) {
            if *bal >= amount { *bal -= amount; true } else { false }
        } else { false }
    }
    fn balance(&self, agent: &str) -> f64 {
        self.balances.get(agent).copied().unwrap_or(0.0)
    }
    fn total_balance(&self) -> f64 { self.balances.values().sum() }
    fn agents(&self) -> Vec<String> { self.balances.keys().cloned().collect() }
    fn reset(&mut self, agent: &str) { self.balances.remove(agent); }
}

type SharedAgentCreditLedger = Arc<std::sync::Mutex<AgentCreditLedger>>;

