/// Config snapshot — take snapshots, diff between two.
struct ConfigSnapshot {
    snapshots: Vec<(String, std::collections::HashMap<String, String>)>, // (label, config)
}

impl ConfigSnapshot {
    fn new() -> Self { Self { snapshots: Vec::new() } }
    fn take_snapshot(&mut self, label: &str, config: std::collections::HashMap<String, String>) {
        self.snapshots.push((label.to_string(), config));
    }
    fn get(&self, label: &str) -> Option<&std::collections::HashMap<String, String>> {
        self.snapshots.iter().find(|(l, _)| l == label).map(|(_, c)| c)
    }
    fn diff(&self, label_a: &str, label_b: &str) -> Vec<(String, Option<String>, Option<String>)> {
        let a = self.get(label_a);
        let b = self.get(label_b);
        let mut result = Vec::new();
        if let (Some(a), Some(b)) = (a, b) {
            let mut all_keys: Vec<String> = a.keys().chain(b.keys()).cloned().collect();
            all_keys.sort(); all_keys.dedup();
            for k in all_keys {
                let va = a.get(&k).cloned();
                let vb = b.get(&k).cloned();
                if va != vb { result.push((k, va, vb)); }
            }
        }
        result
    }
    fn labels(&self) -> Vec<&str> { self.snapshots.iter().map(|(l, _)| l.as_str()).collect() }
    fn count(&self) -> usize { self.snapshots.len() }
}

type SharedConfigSnapshot = Arc<std::sync::Mutex<ConfigSnapshot>>;

/// Retry policy registry — per-task retry configuration.
struct RetryPolicyEntry {
    max_retries: usize,
    backoff_ms: u64,
    backoff_multiplier: f64,
}

struct RetryPolicyRegistry {
    policies: std::collections::HashMap<String, RetryPolicyEntry>,
}

impl RetryPolicyRegistry {
    fn new() -> Self { Self { policies: std::collections::HashMap::new() } }
    fn register(&mut self, task_type: &str, max_retries: usize, backoff_ms: u64, multiplier: f64) {
        self.policies.insert(task_type.to_string(), RetryPolicyEntry { max_retries, backoff_ms, backoff_multiplier: multiplier });
    }
    fn get_policy(&self, task_type: &str) -> Option<(usize, u64, f64)> {
        self.policies.get(task_type).map(|p| (p.max_retries, p.backoff_ms, p.backoff_multiplier))
    }
    fn delay_for_attempt(&self, task_type: &str, attempt: usize) -> Option<u64> {
        self.policies.get(task_type).map(|p| {
            (p.backoff_ms as f64 * p.backoff_multiplier.powi(attempt as i32)) as u64
        })
    }
    fn should_retry(&self, task_type: &str, attempt: usize) -> bool {
        self.policies.get(task_type).map(|p| attempt < p.max_retries).unwrap_or(false)
    }
    fn remove(&mut self, task_type: &str) { self.policies.remove(task_type); }
    fn list(&self) -> Vec<String> { self.policies.keys().cloned().collect() }
}

type SharedRetryPolicyRegistry = Arc<std::sync::Mutex<RetryPolicyRegistry>>;

