/// Bloom filter — probabilistic set membership (simple hash-based).
struct BloomFilterSet {
    bits: Vec<bool>,
    size: usize,
    count: usize,
}

impl BloomFilterSet {
    fn new(size: usize) -> Self { Self { bits: vec![false; size.max(64)], size: size.max(64), count: 0 } }
    fn insert(&mut self, item: &str) {
        let h1 = Self::hash1(item, self.size);
        let h2 = Self::hash2(item, self.size);
        let h3 = (h1 + h2) % self.size;
        if !self.bits[h1] || !self.bits[h2] || !self.bits[h3] { self.count += 1; }
        self.bits[h1] = true;
        self.bits[h2] = true;
        self.bits[h3] = true;
    }
    fn maybe_contains(&self, item: &str) -> bool {
        let h1 = Self::hash1(item, self.size);
        let h2 = Self::hash2(item, self.size);
        let h3 = (h1 + h2) % self.size;
        self.bits[h1] && self.bits[h2] && self.bits[h3]
    }
    fn approx_count(&self) -> usize { self.count }
    fn fill_ratio(&self) -> f64 {
        self.bits.iter().filter(|b| **b).count() as f64 / self.size as f64
    }
    fn hash1(s: &str, size: usize) -> usize {
        let mut h: usize = 5381;
        for b in s.bytes() { h = h.wrapping_mul(33).wrapping_add(b as usize); }
        h % size
    }
    fn hash2(s: &str, size: usize) -> usize {
        let mut h: usize = 0;
        for b in s.bytes() { h = h.wrapping_mul(31).wrapping_add(b as usize).wrapping_add(17); }
        h % size
    }
}

type SharedBloomFilterSet = Arc<std::sync::Mutex<BloomFilterSet>>;

/// Agent task history — record task outcomes per agent.
struct AgentTaskHistory {
    history: std::collections::HashMap<String, Vec<(String, bool)>>, // agent -> [(task, success)]
}

impl AgentTaskHistory {
    fn new() -> Self { Self { history: std::collections::HashMap::new() } }
    fn record(&mut self, agent: &str, task: &str, success: bool) {
        self.history.entry(agent.to_string()).or_default().push((task.to_string(), success));
    }
    fn success_rate(&self, agent: &str) -> f64 {
        let h = match self.history.get(agent) { Some(v) if !v.is_empty() => v, _ => return 0.0 };
        h.iter().filter(|(_, s)| *s).count() as f64 / h.len() as f64
    }
    fn task_count(&self, agent: &str) -> usize {
        self.history.get(agent).map(|v| v.len()).unwrap_or(0)
    }
    fn recent(&self, agent: &str, n: usize) -> Vec<(&str, bool)> {
        self.history.get(agent).map(|v| {
            let start = v.len().saturating_sub(n);
            v[start..].iter().map(|(t, s)| (t.as_str(), *s)).collect()
        }).unwrap_or_default()
    }
    fn agents(&self) -> Vec<String> { self.history.keys().cloned().collect() }
}

type SharedAgentTaskHistory = Arc<std::sync::Mutex<AgentTaskHistory>>;

/// Sliding window increment counter — count events within a time window.
struct SlidingWindowIncr {
    events: Vec<u64>, // timestamps
    window_secs: u64,
}

impl SlidingWindowIncr {
    fn new(window_secs: u64) -> Self { Self { events: Vec::new(), window_secs } }
    fn record_at(&mut self, ts: u64) { self.events.push(ts); }
    fn count_at(&self, now: u64) -> usize {
        let cutoff = now.saturating_sub(self.window_secs);
        self.events.iter().filter(|t| **t >= cutoff).count()
    }
    fn prune(&mut self, now: u64) {
        let cutoff = now.saturating_sub(self.window_secs);
        self.events.retain(|t| *t >= cutoff);
    }
    fn total_ever(&self) -> usize { self.events.len() }
    fn rate_per_sec(&self, now: u64) -> f64 {
        if self.window_secs == 0 { return 0.0; }
        self.count_at(now) as f64 / self.window_secs as f64
    }
}

type SharedSlidingWindowIncr = Arc<std::sync::Mutex<SlidingWindowIncr>>;

/// Resource pool balancer — round-robin distribution across pool members.
struct ResourcePoolBalancer {
    members: Vec<String>,
    next: usize,
    dispatch_counts: std::collections::HashMap<String, usize>,
}

impl ResourcePoolBalancer {
    fn new() -> Self { Self { members: Vec::new(), next: 0, dispatch_counts: std::collections::HashMap::new() } }
    fn add_member(&mut self, member: &str) {
        self.members.push(member.to_string());
    }
    fn remove_member(&mut self, member: &str) {
        self.members.retain(|m| m != member);
        if self.next >= self.members.len() && !self.members.is_empty() { self.next = 0; }
    }
    fn next_member(&mut self) -> Option<&str> {
        if self.members.is_empty() { return None; }
        let member = &self.members[self.next];
        *self.dispatch_counts.entry(member.clone()).or_insert(0) += 1;
        self.next = (self.next + 1) % self.members.len();
        Some(member)
    }
    fn member_count(&self) -> usize { self.members.len() }
    fn dispatches(&self, member: &str) -> usize {
        self.dispatch_counts.get(member).copied().unwrap_or(0)
    }
}

type SharedResourcePoolBalancer = Arc<std::sync::Mutex<ResourcePoolBalancer>>;

/// Event sourcing journal — append-only event log, replay.
struct EventSourcingJournal {
    events: Vec<(u64, String, String)>, // (seq, event_type, payload)
    next_seq: u64,
}

impl EventSourcingJournal {
    fn new() -> Self { Self { events: Vec::new(), next_seq: 1 } }
    fn append(&mut self, event_type: &str, payload: &str) -> u64 {
        let seq = self.next_seq;
        self.events.push((seq, event_type.to_string(), payload.to_string()));
        self.next_seq += 1;
        seq
    }
    fn replay_from(&self, from_seq: u64) -> Vec<(u64, &str, &str)> {
        self.events.iter().filter(|(s, _, _)| *s >= from_seq)
            .map(|(s, t, p)| (*s, t.as_str(), p.as_str())).collect()
    }
    fn latest_seq(&self) -> u64 { self.next_seq - 1 }
    fn event_count(&self) -> usize { self.events.len() }
    fn events_of_type(&self, event_type: &str) -> Vec<(u64, &str)> {
        self.events.iter().filter(|(_, t, _)| t == event_type)
            .map(|(s, _, p)| (*s, p.as_str())).collect()
    }
}

type SharedEventSourcingJournal = Arc<std::sync::Mutex<EventSourcingJournal>>;

