/// Token bucket pool — per-key token bucket allocation.
struct TokenBucketPool {
    buckets: std::collections::HashMap<String, (usize, usize)>, // key -> (tokens, capacity)
}

impl TokenBucketPool {
    fn new() -> Self { Self { buckets: std::collections::HashMap::new() } }
    fn create_bucket(&mut self, key: &str, capacity: usize) {
        self.buckets.insert(key.to_string(), (capacity, capacity));
    }
    fn try_consume(&mut self, key: &str, n: usize) -> bool {
        if let Some((tokens, _)) = self.buckets.get_mut(key) {
            if *tokens >= n { *tokens -= n; true } else { false }
        } else { false }
    }
    fn refill(&mut self, key: &str, n: usize) {
        if let Some((tokens, cap)) = self.buckets.get_mut(key) {
            *tokens = (*tokens + n).min(*cap);
        }
    }
    fn refill_all(&mut self) {
        for (tokens, cap) in self.buckets.values_mut() { *tokens = *cap; }
    }
    fn tokens(&self, key: &str) -> usize {
        self.buckets.get(key).map(|(t, _)| *t).unwrap_or(0)
    }
    fn keys(&self) -> Vec<String> { self.buckets.keys().cloned().collect() }
}

type SharedTokenBucketPool = Arc<std::sync::Mutex<TokenBucketPool>>;

/// Request deduplication — by hash within window.
struct RequestDedup {
    seen: std::collections::HashMap<String, u64>, // hash -> expiry_ts
}

impl RequestDedup {
    fn new() -> Self { Self { seen: std::collections::HashMap::new() } }
    fn is_duplicate(&mut self, hash: &str, now: u64, window: u64) -> bool {
        self.seen.retain(|_, exp| *exp > now);
        if self.seen.contains_key(hash) { return true; }
        self.seen.insert(hash.to_string(), now + window);
        false
    }
    fn len(&self) -> usize { self.seen.len() }
    fn clear(&mut self) { self.seen.clear(); }
    fn prune(&mut self, now: u64) { self.seen.retain(|_, exp| *exp > now); }
}

type SharedRequestDedup = Arc<std::sync::Mutex<RequestDedup>>;

/// Partition rebalancer — assign partitions to nodes, rebalance.
struct PartitionRebalancer {
    assignments: std::collections::HashMap<usize, String>, // partition -> node
    nodes: Vec<String>,
}

impl PartitionRebalancer {
    fn new() -> Self { Self { assignments: std::collections::HashMap::new(), nodes: Vec::new() } }
    fn add_node(&mut self, node: &str) {
        if !self.nodes.contains(&node.to_string()) { self.nodes.push(node.to_string()); }
    }
    fn remove_node(&mut self, node: &str) {
        self.nodes.retain(|n| n != node);
        self.assignments.retain(|_, n| n != node);
    }
    fn rebalance(&mut self, num_partitions: usize) {
        if self.nodes.is_empty() { return; }
        self.assignments.clear();
        for p in 0..num_partitions {
            let node = &self.nodes[p % self.nodes.len()];
            self.assignments.insert(p, node.clone());
        }
    }
    fn partition_owner(&self, partition: usize) -> Option<&str> {
        self.assignments.get(&partition).map(|s| s.as_str())
    }
    fn partitions_for(&self, node: &str) -> Vec<usize> {
        self.assignments.iter().filter(|(_, n)| n.as_str() == node).map(|(p, _)| *p).collect()
    }
    fn node_count(&self) -> usize { self.nodes.len() }
}

type SharedPartitionRebalancer = Arc<std::sync::Mutex<PartitionRebalancer>>;

