/// Execute a trigger's action — sends to the action channel for the REPL to process.
fn execute_trigger_action(trigger: &EventTrigger, action_tx: &TriggerActionTx) {
    let action = match &trigger.action {
        TriggerAction::Alert(msg) => PendingTriggerAction::Alert {
            trigger_name: trigger.name.clone(),
            message: msg.clone(),
        },
        TriggerAction::RestartUnhealthy => PendingTriggerAction::RestartUnhealthy {
            trigger_name: trigger.name.clone(),
        },
        TriggerAction::ScaleUp(role) => PendingTriggerAction::ScaleUp {
            trigger_name: trigger.name.clone(),
            role: role.clone(),
        },
    };
    let _ = action_tx.send(action);
}

