    #[test]
    fn test_parse_delegation_basic() {
        let text = "I think @delegate(gsea-coder, implement retry logic) would be best.";
        let result = parse_delegation(text);
        assert_eq!(result, Some(("gsea-coder".to_string(), "implement retry logic".to_string())));
    }

    #[test]
    fn test_parse_delegation_with_spaces() {
        let text = "@delegate( gsea-reviewer , review the retry module )";
        let result = parse_delegation(text);
        assert_eq!(result, Some(("gsea-reviewer".to_string(), "review the retry module".to_string())));
    }

    #[test]
    fn test_parse_delegation_no_match() {
        assert!(parse_delegation("no delegation here").is_none());
        assert!(parse_delegation("@delegate(").is_none());
        assert!(parse_delegation("@delegate()").is_none());
    }

    #[test]
    fn test_parse_delegation_empty_parts() {
        assert!(parse_delegation("@delegate(, task)").is_none());
        assert!(parse_delegation("@delegate(agent, )").is_none());
    }

