    // ─── PekkoSession serialization ────────────────────────────────

    #[test]
    fn test_pekko_session_roundtrip() {
        let mut stats = std::collections::HashMap::new();
        let mut s = AgentStats::default();
        s.record_success(100);
        s.record_success(200);
        s.record_failure();
        s.record_react(3, true);
        stats.insert("gsea-coder".to_string(), s);

        let mut msg_counts = std::collections::HashMap::new();
        msg_counts.insert("gsea-coder".to_string(), 42u64);

        let mut histories = std::collections::HashMap::new();
        histories.insert("gsea-coder".to_string(), vec![
            llm::Message { role: "system".into(), content: "You are a coder.".into() },
            llm::Message { role: "user".into(), content: "Write a function.".into() },
            llm::Message { role: "assistant".into(), content: "pub fn foo() {}".into() },
        ]);

        let session = PekkoSession {
            saved_at: "2025-01-01T00:00:00Z".to_string(),
            model: "gemma4:26b".to_string(),
            agent_stats: stats,
            brain_stats: serde_json::json!({"working": 0, "episodic": 5}),
            agent_message_counts: msg_counts,
            conversation_histories: histories,
            dynamic_agents: vec![("gsea-coder-2".to_string(), "coder".to_string())],
            queued_tasks: Vec::new(),
            queue_stats: None,
        };

        let json = serde_json::to_string_pretty(&session).unwrap();
        let restored: PekkoSession = serde_json::from_str(&json).unwrap();

        assert_eq!(restored.saved_at, "2025-01-01T00:00:00Z");
        assert_eq!(restored.model, "gemma4:26b");
        let coder = &restored.agent_stats["gsea-coder"];
        assert_eq!(coder.tasks_completed, 2);
        assert_eq!(coder.tasks_failed, 1);
        assert_eq!(coder.total_output_chars, 300);
        assert_eq!(coder.react_iterations, 3);
        assert_eq!(coder.react_successes, 1);
        assert_eq!(restored.agent_message_counts["gsea-coder"], 42);
        // Check conversation history
        let history = &restored.conversation_histories["gsea-coder"];
        assert_eq!(history.len(), 3);
        assert_eq!(history[0].role, "system");
        assert_eq!(history[2].content, "pub fn foo() {}");
        // Check dynamic agents
        assert_eq!(restored.dynamic_agents.len(), 1);
        assert_eq!(restored.dynamic_agents[0].0, "gsea-coder-2");
        assert_eq!(restored.dynamic_agents[0].1, "coder");
    }

    #[test]
    fn test_pekko_session_empty() {
        let session = PekkoSession {
            saved_at: String::new(),
            model: "auto".to_string(),
            agent_stats: std::collections::HashMap::new(),
            brain_stats: serde_json::json!({}),
            agent_message_counts: std::collections::HashMap::new(),
            conversation_histories: std::collections::HashMap::new(),
            dynamic_agents: Vec::new(),
            queued_tasks: Vec::new(),
            queue_stats: None,
        };
        let json = serde_json::to_string(&session).unwrap();
        let restored: PekkoSession = serde_json::from_str(&json).unwrap();
        assert!(restored.agent_stats.is_empty());
        assert!(restored.agent_message_counts.is_empty());
        assert!(restored.conversation_histories.is_empty());
        assert!(restored.dynamic_agents.is_empty());
        assert!(restored.queued_tasks.is_empty());
    }

