    #[test]
    fn test_count_agents_by_role_detects_roles() {
        // We can't easily create ActorRefs in tests, but we can test the
        // logic indirectly via the role-detection heuristic.
        // Test the role classification logic directly:
        let test_ids = vec![
            ("gsea-main", "coordinator"),
            ("gsea-coder", "coder"),
            ("gsea-coder-2", "coder"),
            ("gsea-reviewer", "reviewer"),
            ("gsea-tester", "tester"),
            ("gsea-tester-2", "tester"),
        ];
        let mut counts: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
        for (id, _) in &test_ids {
            let role = if id.contains("coder") { "coder" }
                else if id.contains("reviewer") { "reviewer" }
                else if id.contains("tester") { "tester" }
                else { "coordinator" };
            *counts.entry(role.to_string()).or_default() += 1;
        }
        assert_eq!(counts["coder"], 2);
        assert_eq!(counts["reviewer"], 1);
        assert_eq!(counts["tester"], 2);
        assert_eq!(counts["coordinator"], 1);
    }

    // ─── ScalingMetrics ────────────────────────────────────────────

    #[test]
    fn test_scaling_metrics_response_time() {
        let mut metrics = ScalingMetrics::default();
        assert_eq!(metrics.avg_response_time(), 0);

        metrics.record_response_time(1000);
        metrics.record_response_time(3000);
        assert_eq!(metrics.avg_response_time(), 2000);

        metrics.record_response_time(2000);
        assert_eq!(metrics.avg_response_time(), 2000);
    }

    #[test]
    fn test_scaling_metrics_rolling_window() {
        let mut metrics = ScalingMetrics::default();
        // Fill beyond 50 measurements
        for i in 0..60 {
            metrics.record_response_time(i * 100);
        }
        assert_eq!(metrics.response_times.len(), 50);
    }

    #[test]
    fn test_scaling_metrics_pending() {
        let mut metrics = ScalingMetrics::default();
        metrics.increment_pending("coder");
        metrics.increment_pending("coder");
        metrics.increment_pending("reviewer");
        assert_eq!(metrics.pending_tasks["coder"], 2);
        assert_eq!(metrics.pending_tasks["reviewer"], 1);

        metrics.decrement_pending("coder");
        assert_eq!(metrics.pending_tasks["coder"], 1);

        // Decrement below zero saturates at 0
        metrics.decrement_pending("reviewer");
        metrics.decrement_pending("reviewer");
        assert_eq!(metrics.pending_tasks["reviewer"], 0);
    }

    #[test]
    fn test_scaling_metrics_cooldown() {
        let mut metrics = ScalingMetrics::default();
        let cooldown = std::time::Duration::from_secs(60);

        assert!(metrics.can_scale(cooldown)); // No prior event

        metrics.last_scale_event = Some(std::time::Instant::now());
        assert!(!metrics.can_scale(cooldown)); // Just happened
    }

    // ─── AutoScaler ────────────────────────────────────────────────

    #[test]
    fn test_autoscaler_disabled() {
        let scaler = AutoScaler::default();
        let metrics = ScalingMetrics::default();
        let counts = std::collections::HashMap::new();
        assert!(scaler.evaluate(&metrics, &counts).is_none());
    }

    #[test]
    fn test_autoscaler_queue_pressure() {
        let mut scaler = AutoScaler::default();
        scaler.enabled = true;

        let mut metrics = ScalingMetrics::default();
        metrics.increment_pending("coder");
        metrics.increment_pending("coder");
        metrics.increment_pending("coder"); // hits threshold of 3

        let mut counts = std::collections::HashMap::new();
        counts.insert("coder".to_string(), 1usize);

        let result = scaler.evaluate(&metrics, &counts);
        assert_eq!(result, Some("coder".to_string()));
    }

    #[test]
    fn test_autoscaler_at_max() {
        let mut scaler = AutoScaler::default();
        scaler.enabled = true;
        scaler.max_per_role = 2;

        let mut metrics = ScalingMetrics::default();
        for _ in 0..5 { metrics.increment_pending("coder"); }

        let mut counts = std::collections::HashMap::new();
        counts.insert("coder".to_string(), 2usize); // already at max

        assert!(scaler.evaluate(&metrics, &counts).is_none());
    }

    #[test]
    fn test_autoscaler_latency_trigger() {
        let mut scaler = AutoScaler::default();
        scaler.enabled = true;
        scaler.latency_threshold_ms = 5000;

        let mut metrics = ScalingMetrics::default();
        // High latency
        for _ in 0..10 { metrics.record_response_time(10_000); }
        metrics.increment_pending("reviewer");

        let mut counts = std::collections::HashMap::new();
        counts.insert("reviewer".to_string(), 1usize);

        let result = scaler.evaluate(&metrics, &counts);
        assert_eq!(result, Some("reviewer".to_string()));
    }

    #[test]
    fn test_autoscaler_scale_down() {
        let mut scaler = AutoScaler::default();
        scaler.enabled = true;
        scaler.latency_threshold_ms = 30_000;

        let mut metrics = ScalingMetrics::default();
        // Low latency
        for _ in 0..10 { metrics.record_response_time(1_000); }

        let mut counts = std::collections::HashMap::new();
        counts.insert("coder".to_string(), 3usize);

        let mut stats = std::collections::HashMap::new();
        stats.insert("gsea-coder".to_string(), AgentStats::default());
        let mut s2 = AgentStats::default();
        s2.record_success(100);
        stats.insert("gsea-coder-2".to_string(), s2);
        let s3 = AgentStats::default();
        // gsea-coder-3 has 0 tasks — least productive, should be removed
        stats.insert("gsea-coder-3".to_string(), s3);

        let result = scaler.evaluate_scale_down(&metrics, &counts, &stats);
        assert_eq!(result, Some("gsea-coder-3".to_string()));
    }

