    // ─── MetricsDashboard ──────────────────────────────────────────

    #[test]
    fn test_percentiles_empty() {
        let (p50, p90, p95, p99) = MetricsDashboard::percentiles(&[]);
        assert_eq!((p50, p90, p95, p99), (0, 0, 0, 0));
    }

    #[test]
    fn test_percentiles_single() {
        let (p50, p90, p95, p99) = MetricsDashboard::percentiles(&[100]);
        assert_eq!(p50, 100);
        assert_eq!(p99, 100);
    }

    #[test]
    fn test_percentiles_distribution() {
        let times: Vec<u64> = (1..=100).collect();
        let (p50, p90, _p95, p99) = MetricsDashboard::percentiles(&times);
        assert!(p50 >= 50 && p50 <= 51); // ~50th percentile
        assert!(p90 >= 90 && p90 <= 91); // ~90th percentile
        assert_eq!(p99, 100); // max
    }

    #[test]
    fn test_throughput() {
        assert_eq!(MetricsDashboard::throughput(0, 0), 0.0);
        let tpm = MetricsDashboard::throughput(60, 60);
        assert!((tpm - 60.0).abs() < 0.01);

        let tpm2 = MetricsDashboard::throughput(30, 120);
        assert!((tpm2 - 15.0).abs() < 0.01);
    }

    #[test]
    fn test_error_rate() {
        let empty: std::collections::HashMap<String, AgentStats> = std::collections::HashMap::new();
        assert_eq!(MetricsDashboard::error_rate(&empty), 0.0);

        let mut stats = std::collections::HashMap::new();
        let mut s = AgentStats::default();
        s.record_success(100);
        s.record_success(100);
        s.record_failure();
        stats.insert("test".to_string(), s);
        let rate = MetricsDashboard::error_rate(&stats);
        assert!((rate - 33.33).abs() < 0.1);
    }

