    // ─── EventBus integration tests ──────────────────────────────

    #[test]
    fn test_event_bus_publish_and_read() {
        let bus = EventBus::builder()
            .add_topic(TopicConfig::new("agent.task").partitions(2))
            .add_topic(TopicConfig::new("agent.result").partitions(2))
            .build()
            .unwrap();
        let handle = EventBusHandle::new(bus);

        let event = serde_json::json!({"agent": "gsea-coder", "task": "write code"});
        handle.publish("agent.task", &PartitionKey::new("gsea-coder"), event.to_string().into_bytes()).unwrap();

        let msgs = handle.read_all("agent.task").unwrap();
        assert_eq!(msgs.len(), 1);
        let parsed: serde_json::Value = serde_json::from_slice(&msgs[0]).unwrap();
        assert_eq!(parsed["agent"], "gsea-coder");
    }

    #[test]
    fn test_event_bus_multiple_topics() {
        let bus = EventBus::builder()
            .add_topic(TopicConfig::new("agent.task").partitions(1))
            .add_topic(TopicConfig::new("agent.health").partitions(1))
            .add_topic(TopicConfig::new("agent.scale").partitions(1))
            .build()
            .unwrap();
        let handle = EventBusHandle::new(bus);

        handle.publish("agent.task", &PartitionKey::new("a"), b"task1".to_vec()).unwrap();
        handle.publish("agent.task", &PartitionKey::new("b"), b"task2".to_vec()).unwrap();
        handle.publish("agent.health", &PartitionKey::new("a"), b"healthy".to_vec()).unwrap();
        handle.publish("agent.scale", &PartitionKey::new("a"), b"up".to_vec()).unwrap();

        assert_eq!(handle.read_all("agent.task").unwrap().len(), 2);
        assert_eq!(handle.read_all("agent.health").unwrap().len(), 1);
        assert_eq!(handle.read_all("agent.scale").unwrap().len(), 1);
    }

