    #[test]
    fn test_event_bus_subscribe_receives() {
        use std::sync::atomic::{AtomicU32, Ordering};
        let bus = EventBus::builder()
            .add_topic(TopicConfig::new("agent.task").partitions(1))
            .build().unwrap();
        let handle = EventBusHandle::new(bus);

        let counter = Arc::new(AtomicU32::new(0));
        let cc = counter.clone();
        handle.subscribe("agent.task", move |_, _| { cc.fetch_add(1, Ordering::SeqCst); }).unwrap();

        handle.publish("agent.task", &PartitionKey::new("a"), b"t1".to_vec()).unwrap();
        handle.publish("agent.task", &PartitionKey::new("b"), b"t2".to_vec()).unwrap();
        assert_eq!(counter.load(Ordering::SeqCst), 2);
        assert_eq!(handle.read_all("agent.task").unwrap().len(), 2);
    }

    #[test]
    fn test_event_bus_unsubscribe() {
        use std::sync::atomic::{AtomicU32, Ordering};
        let bus = EventBus::builder()
            .add_topic(TopicConfig::new("agent.health").partitions(1))
            .build().unwrap();
        let handle = EventBusHandle::new(bus);

        let counter = Arc::new(AtomicU32::new(0));
        let cc = counter.clone();
        let sub_id = handle.subscribe("agent.health", move |_, _| { cc.fetch_add(1, Ordering::SeqCst); }).unwrap();

        handle.publish("agent.health", &PartitionKey::new("x"), b"h1".to_vec()).unwrap();
        assert_eq!(counter.load(Ordering::SeqCst), 1);

        handle.unsubscribe("agent.health", sub_id).unwrap();
        handle.publish("agent.health", &PartitionKey::new("x"), b"h2".to_vec()).unwrap();
        assert_eq!(counter.load(Ordering::SeqCst), 1); // still 1
    }

    #[test]
    fn test_event_bus_subscriber_count() {
        let bus = EventBus::builder()
            .add_topic(TopicConfig::new("agent.scale").partitions(1))
            .build().unwrap();
        let handle = EventBusHandle::new(bus);

        assert_eq!(handle.subscriber_count("agent.scale").unwrap(), 0);
        let s1 = handle.subscribe("agent.scale", |_, _| {}).unwrap();
        assert_eq!(handle.subscriber_count("agent.scale").unwrap(), 1);
        handle.unsubscribe("agent.scale", s1).unwrap();
        assert_eq!(handle.subscriber_count("agent.scale").unwrap(), 0);
    }

