    // ─── Memory Consolidation Tests ──────────────────────────────

    #[test]
    fn test_consolidation_grouping() {
        // Test the keyword-overlap grouping algorithm
        let items = vec![
            "The parser failed on invalid JSON input with nested arrays",
            "JSON parsing error when input contains nested arrays and objects",
            "Database connection timeout after 30 seconds of waiting",
            "Connection pool exhausted, database queries timing out",
            "Unique unrelated memory about deployment",
        ];

        let mut groups: Vec<Vec<usize>> = Vec::new();
        let mut assigned: Vec<bool> = vec![false; items.len()];

        for i in 0..items.len() {
            if assigned[i] { continue; }
            let mut group = vec![i];
            assigned[i] = true;

            let words_i: std::collections::HashSet<&str> = items[i]
                .split_whitespace()
                .filter(|w| w.len() > 3)
                .collect();

            for j in (i + 1)..items.len() {
                if assigned[j] { continue; }
                let words_j: std::collections::HashSet<&str> = items[j]
                    .split_whitespace()
                    .filter(|w| w.len() > 3)
                    .collect();

                let overlap = words_i.intersection(&words_j).count();
                let min_size = words_i.len().min(words_j.len()).max(1);
                let similarity = overlap as f64 / min_size as f64;

                if similarity > 0.3 {
                    group.push(j);
                    assigned[j] = true;
                }
            }
            groups.push(group);
        }

        // JSON-related should cluster, DB-related should cluster, unique stays alone
        assert!(groups.len() >= 2, "Expected at least 2 clusters, got {}", groups.len());
        assert!(groups.len() <= 4, "Expected at most 4 clusters, got {}", groups.len());
    }

