    // ─── Leaderboard Tests ───────────────────────────────────────

    #[test]
    fn test_leaderboard_sorting() {
        // Simulate agent stats for ranking
        let mut stats_map: std::collections::HashMap<String, AgentStats> = std::collections::HashMap::new();

        stats_map.insert("agent-a".to_string(), AgentStats {
            tasks_completed: 10, tasks_failed: 2,
            total_output_chars: 5000, react_iterations: 0, react_successes: 0,
        });
        stats_map.insert("agent-b".to_string(), AgentStats {
            tasks_completed: 8, tasks_failed: 0,
            total_output_chars: 3000, react_iterations: 0, react_successes: 0,
        });
        stats_map.insert("agent-c".to_string(), AgentStats {
            tasks_completed: 3, tasks_failed: 7,
            total_output_chars: 1000, react_iterations: 0, react_successes: 0,
        });

        let mut entries: Vec<(String, f64, u64)> = stats_map.iter().map(|(id, s)| {
            let total = s.tasks_completed + s.tasks_failed;
            let rate = if total > 0 { s.tasks_completed as f64 / total as f64 * 100.0 } else { 0.0 };
            (id.clone(), rate, s.tasks_completed)
        }).collect();

        entries.sort_by(|a, b| {
            b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal)
                .then(b.2.cmp(&a.2))
        });

        // agent-b (100% rate) > agent-a (83% rate) > agent-c (30% rate)
        assert_eq!(entries[0].0, "agent-b");
        assert_eq!(entries[1].0, "agent-a");
        assert_eq!(entries[2].0, "agent-c");
    }

    #[test]
    fn test_leaderboard_zero_tasks() {
        let s = AgentStats::default();
        let total = s.tasks_completed + s.tasks_failed;
        let rate = if total > 0 { s.tasks_completed as f64 / total as f64 * 100.0 } else { 0.0 };
        assert_eq!(rate, 0.0);
        assert_eq!(total, 0);
    }

