    #[test]
    fn test_queue_export_pending() {
        let mut q = TaskQueue::new();
        q.enqueue("task a".to_string(), Some("coder".to_string()), QueuePriority::High);
        q.enqueue("task b".to_string(), None, QueuePriority::Normal);
        let id = q.enqueue("task c".to_string(), None, QueuePriority::Low);
        q.complete(id, "done".to_string());

        let exported = q.export_pending();
        assert_eq!(exported.len(), 2); // only pending, not completed
        assert_eq!(exported[0].priority, "high");
        assert_eq!(exported[1].priority, "normal");
    }

    #[test]
    fn test_queue_import_tasks() {
        let mut q = TaskQueue::new();
        let saved = vec![
            SavedQueuedTask {
                id: 99, description: "restored task".to_string(),
                target_role: Some("reviewer".to_string()),
                priority: "high".to_string(), status: "pending".to_string(),
                depends_on: Vec::new(), run_at: None,
            },
            SavedQueuedTask {
                id: 100, description: "another task".to_string(),
                target_role: None,
                priority: "normal".to_string(), status: "pending".to_string(),
                depends_on: Vec::new(), run_at: None,
            },
        ];

        q.import_tasks(&saved);
        assert_eq!(q.pending().len(), 2);
        // IDs are reassigned by enqueue, not preserved
        assert_eq!(q.tasks[0].description, "restored task"); // high priority first
    }

