    #[test]
    fn test_route_registry() {
        let registry: RouteRegistry = Arc::new(std::sync::Mutex::new(Vec::new()));
        let route = EventRoute {
            name: "r1".to_string(),
            source_topic: "a".to_string(),
            dest_topic: "b".to_string(),
            filter_field: None,
            filter_value: None,
            transform: None,
            enabled: true,
            forwarded_count: 0,
        };
        registry.lock().unwrap().push(route);
        assert_eq!(registry.lock().unwrap().len(), 1);

        // Disable
        registry.lock().unwrap()[0].enabled = false;
        assert!(!registry.lock().unwrap()[0].enabled);

        // Remove
        registry.lock().unwrap().retain(|r| r.name != "r1");
        assert!(registry.lock().unwrap().is_empty());
    }

    #[test]
    fn test_leaderboard_score_calculation() {
        let completed = 10u64;
        let failed = 2u64;
        let total = completed + failed;
        let success_rate = completed as f64 / total as f64 * 100.0;
        let avg_output = 5000u64 / completed;
        let throughput_score = (avg_output as f64 / 1000.0).min(100.0);
        let score = success_rate * 0.6 + throughput_score * 0.4;

        // success_rate ~83.3, throughput_score = 0.5, score ~50.2
        assert!(score > 49.0 && score < 52.0, "score was {}", score);
    }

