    #[test]
    fn test_collab_contribution_tracking() {
        // Test the contribution collection pattern used in /collab
        let mut contributions: Vec<(String, String)> = Vec::new();

        contributions.push(("gsea-coder".to_string(), "Use async I/O for better throughput.".to_string()));
        contributions.push(("gsea-reviewer".to_string(), "Add error handling for edge cases.".to_string()));
        contributions.push(("gsea-tester".to_string(), "Need integration tests for the pipeline.".to_string()));

        assert_eq!(contributions.len(), 3);

        // Verify context building (same pattern as the command)
        let context = contributions.iter()
            .map(|(name, text)| format!("[{}]: {}", name, text))
            .collect::<Vec<_>>()
            .join("\n\n---\n\n");

        assert!(context.contains("[gsea-coder]: Use async"));
        assert!(context.contains("[gsea-reviewer]: Add error"));
        assert!(context.contains("[gsea-tester]: Need integration"));
        assert!(context.contains("---"));
    }

    #[test]
    fn test_collab_round_parsing() {
        // Test the rsplitn parsing pattern used in /collab
        let input1 = "design a caching strategy 3";
        let words: Vec<&str> = input1.rsplitn(2, ' ').collect();
        assert_eq!(words.len(), 2);
        assert_eq!(words[0].parse::<usize>().unwrap(), 3);
        assert_eq!(words[1], "design a caching strategy");

        // No rounds specified
        let input2 = "design a caching strategy";
        let words2: Vec<&str> = input2.rsplitn(2, ' ').collect();
        // "strategy" is not a number, so default rounds
        assert!(words2[0].parse::<usize>().is_err());

        // Clamp rounds
        let n: usize = 15;
        let clamped = n.max(1).min(10);
        assert_eq!(clamped, 10);
    }

    #[test]
    fn test_collab_summary_truncation() {
        // Verify the truncation pattern used when storing collab results
        let long_text = "x".repeat(500);
        let contributions = vec![
            ("agent1".to_string(), long_text.clone()),
            ("agent2".to_string(), long_text.clone()),
        ];

        let summary = contributions.iter()
            .map(|(agent, text)| format!("[{}] {}", agent, &text[..text.len().min(300)]))
            .collect::<Vec<_>>()
            .join("\n---\n");

        // Each entry capped at 300 chars of content
        for line in summary.split("\n---\n") {
            // "[agentN] " = 10 chars + 300 max content = ~310
            assert!(line.len() <= 320, "line too long: {}", line.len());
        }

        // Final summary also capped at 3000
        let final_summary = &summary[..summary.len().min(3000)];
        assert!(final_summary.len() <= 3000);
    }

