    // ─── Consensus Voting Tests ──────────────────────────────────

    #[test]
    fn test_vote_tally_approved() {
        let votes = vec![
            ("a".to_string(), "YES".to_string(), "reason".to_string()),
            ("b".to_string(), "YES".to_string(), "reason".to_string()),
            ("c".to_string(), "YES".to_string(), "reason".to_string()),
            ("d".to_string(), "NO".to_string(), "reason".to_string()),
        ];

        let yes_count = votes.iter().filter(|(_, v, _)| v == "YES").count();
        let no_count = votes.iter().filter(|(_, v, _)| v == "NO").count();
        let total = votes.len();

        assert_eq!(yes_count, 3);
        assert_eq!(no_count, 1);

        let verdict = if yes_count > no_count && yes_count * 2 > total {
            "APPROVED"
        } else if no_count > yes_count && no_count * 2 > total {
            "REJECTED"
        } else {
            "INCONCLUSIVE"
        };
        assert_eq!(verdict, "APPROVED");
    }

    #[test]
    fn test_vote_tally_half_split() {
        // 2 YES, 1 NO, 1 ABSTAIN — yes > no but 2*2 == 4, not > 4
        let yes = 2usize;
        let no = 1usize;
        let total = 4usize;
        let verdict = if yes > no && yes * 2 > total { "APPROVED" }
                      else if no > yes && no * 2 > total { "REJECTED" }
                      else { "INCONCLUSIVE" };
        assert_eq!(verdict, "INCONCLUSIVE");
    }

    #[test]
    fn test_vote_parse() {
        let text = "VOTE: YES\nREASON: The approach is sound and well-tested.";
        let vote = if text.to_uppercase().contains("VOTE: YES") { "YES" }
                   else if text.to_uppercase().contains("VOTE: NO") { "NO" }
                   else { "ABSTAIN" };
        assert_eq!(vote, "YES");

        let text2 = "After careful consideration...\nVOTE: NO\nREASON: Missing edge cases.";
        let vote2 = if text2.to_uppercase().contains("VOTE: YES") { "YES" }
                    else if text2.to_uppercase().contains("VOTE: NO") { "NO" }
                    else { "ABSTAIN" };
        assert_eq!(vote2, "NO");

        let text3 = "I'm not sure about this...";
        let vote3 = if text3.to_uppercase().contains("VOTE: YES") { "YES" }
                    else if text3.to_uppercase().contains("VOTE: NO") { "NO" }
                    else { "ABSTAIN" };
        assert_eq!(vote3, "ABSTAIN");
    }

    #[test]
    fn test_vote_inconclusive() {
        let yes = 2usize;
        let no = 2usize;
        let total = 4usize;
        let verdict = if yes > no && yes * 2 > total { "APPROVED" }
                      else if no > yes && no * 2 > total { "REJECTED" }
                      else { "INCONCLUSIVE" };
        assert_eq!(verdict, "INCONCLUSIVE");
    }

