    #[test]
    fn test_tag_basic() {
        let mut idx = TagIndex::new();
        idx.tag("mem1", "#bug");
        idx.tag("mem1", "#important");
        idx.tag("mem2", "#bug");

        assert_eq!(idx.get("#bug").len(), 2);
        assert_eq!(idx.get("#important").len(), 1);
        assert_eq!(idx.get("#nonexistent").len(), 0);
    }

    #[test]
    fn test_tag_normalization() {
        let mut idx = TagIndex::new();
        idx.tag("m1", "#Bug");
        idx.tag("m2", "bug"); // no #, still works
        idx.tag("m3", "#BUG");

        // All normalize to "bug"
        assert_eq!(idx.get("bug").len(), 3);
        assert_eq!(idx.get("#Bug").len(), 3);
    }

    #[test]
    fn test_untag() {
        let mut idx = TagIndex::new();
        idx.tag("m1", "#review");
        idx.tag("m2", "#review");
        assert_eq!(idx.get("review").len(), 2);

        idx.untag("m1", "#review");
        assert_eq!(idx.get("review").len(), 1);
        assert_eq!(idx.get("review")[0], "m2");

        // Untag last entry removes the tag entirely
        idx.untag("m2", "review");
        assert_eq!(idx.get("review").len(), 0);
        assert!(idx.list_tags().is_empty());
    }

    #[test]
    fn test_tag_search_intersection() {
        let mut idx = TagIndex::new();
        idx.tag("m1", "#bug");
        idx.tag("m1", "#critical");
        idx.tag("m2", "#bug");
        idx.tag("m2", "#minor");
        idx.tag("m3", "#critical");

        // Search for bug AND critical — only m1
        let results = idx.search(&["#bug", "#critical"]);
        assert_eq!(results.len(), 1);
        assert_eq!(results[0], "m1");

        // Search for just bug — m1 and m2
        let results2 = idx.search(&["bug"]);
        assert_eq!(results2.len(), 2);
    }

    #[test]
    fn test_tag_list() {
        let mut idx = TagIndex::new();
        idx.tag("m1", "#a");
        idx.tag("m2", "#a");
        idx.tag("m3", "#a");
        idx.tag("m1", "#b");

        let tags = idx.list_tags();
        assert_eq!(tags.len(), 2);
        // Sorted by count descending
        assert_eq!(tags[0].0, "a");
        assert_eq!(tags[0].1, 3);
        assert_eq!(tags[1].0, "b");
        assert_eq!(tags[1].1, 1);
    }

