    // ─── Task Dependency Tests ───────────────────────────────────

    #[test]
    fn test_task_deps_satisfied_no_deps() {
        let q = TaskQueue::new();
        let task = QueuedTask {
            id: 1, description: "no deps".to_string(),
            target_role: None, priority: QueuePriority::Normal,
            created_at: std::time::Instant::now(),
            status: QueuedTaskStatus::Pending,
            depends_on: Vec::new(), run_at: None,
        };
        assert!(q.deps_satisfied(&task));
    }

    #[test]
    fn test_task_deps_not_satisfied() {
        let mut q = TaskQueue::new();
        let id1 = q.enqueue("first task".to_string(), None, QueuePriority::Normal);
        let id2 = q.enqueue_with_deps("second task".to_string(), None, QueuePriority::Normal, vec![id1]);

        // id1 is pending, so id2's deps are NOT satisfied
        let task2 = q.tasks.iter().find(|t| t.id == id2).unwrap();
        assert!(!q.deps_satisfied(task2));
    }

    #[test]
    fn test_task_deps_satisfied_after_completion() {
        let mut q = TaskQueue::new();
        let id1 = q.enqueue("first".to_string(), None, QueuePriority::Normal);
        let _id2 = q.enqueue_with_deps("second".to_string(), None, QueuePriority::Normal, vec![id1]);

        // Complete id1
        q.complete(id1, "done".to_string());

        // Now id2's deps ARE satisfied
        let task2 = q.tasks.iter().find(|t| t.description == "second").unwrap();
        assert!(q.deps_satisfied(task2));
    }

    #[test]
    fn test_task_deps_blocks_steal() {
        let mut q = TaskQueue::new();
        let id1 = q.enqueue("first".to_string(), None, QueuePriority::High);
        q.enqueue_with_deps("second".to_string(), None, QueuePriority::Critical, vec![id1]);

        // Even though "second" is Critical priority, it can't be stolen because id1 is pending
        // steal should return id1 (first eligible task)
        let stolen = q.steal(None).unwrap();
        assert_eq!(stolen.id, id1);
    }

    #[test]
    fn test_task_deps_chain() {
        let mut q = TaskQueue::new();
        let id1 = q.enqueue("step 1".to_string(), None, QueuePriority::Normal);
        let id2 = q.enqueue_with_deps("step 2".to_string(), None, QueuePriority::Normal, vec![id1]);
        let _id3 = q.enqueue_with_deps("step 3".to_string(), None, QueuePriority::Normal, vec![id2]);

        // Only id1 is stealable
        let stolen = q.steal(None).unwrap();
        assert_eq!(stolen.description, "step 1");
    }

    #[test]
    fn test_saved_task_deps_roundtrip() {
        let saved = SavedQueuedTask {
            id: 1, description: "task".to_string(),
            target_role: None, priority: "high".to_string(),
            status: "pending".to_string(),
            depends_on: vec![5, 10], run_at: None,
        };

        let json = serde_json::to_string(&saved).unwrap();
        let restored: SavedQueuedTask = serde_json::from_str(&json).unwrap();
        assert_eq!(restored.depends_on, vec![5, 10]);
    }

    #[test]
    fn test_saved_task_deps_default() {
        // Old format without depends_on should deserialize with empty vec
        let json = r#"{"id":1,"description":"old","target_role":null,"priority":"normal","status":"pending"}"#;
        let restored: SavedQueuedTask = serde_json::from_str(json).unwrap();
        assert!(restored.depends_on.is_empty());
        assert!(restored.run_at.is_none());
    }

    // ─── Memory Decay Tests ──────────────────────────────────────

    #[test]
    fn test_decay_fresh_memory() {
        let mut tracker = MemoryDecayTracker::new(24.0);
        tracker.touch("mem1");
        let rel = tracker.relevance("mem1");
        // Just touched — should be very close to 1.0
        assert!(rel > 0.99, "Expected ~1.0, got {}", rel);
    }

    #[test]
    fn test_decay_untracked_memory() {
        let tracker = MemoryDecayTracker::new(24.0);
        // Untracked memory gets default 0.5
        assert!((tracker.relevance("unknown") - 0.5).abs() < 0.001);
    }

    #[test]
    fn test_decay_stale_detection() {
        let mut tracker = MemoryDecayTracker::new(24.0);
        tracker.archive_threshold = 0.9; // high threshold to trigger easily

        tracker.touch("mem1");
        // Freshly touched — should NOT be stale
        let stale = tracker.stale_memories();
        assert!(stale.is_empty(), "Fresh memory shouldn't be stale");
    }

    #[test]
    fn test_decay_tracked_count() {
        let mut tracker = MemoryDecayTracker::new(24.0);
        assert_eq!(tracker.tracked_count(), 0);
        tracker.touch("a");
        tracker.touch("b");
        assert_eq!(tracker.tracked_count(), 2);
        tracker.touch("a"); // re-touch doesn't add
        assert_eq!(tracker.tracked_count(), 2);
    }

    // ─── Agent Capability Tests ──────────────────────────────────

    #[test]
    fn test_capability_basic() {
        let mut cap = AgentCapability::new("gsea-coder");
        cap.add_role("coder");
        cap.add_skill("rust", 0.9);
        cap.add_skill("testing", 0.7);
        cap.add_specialty("code generation");

        assert_eq!(cap.agent_id, "gsea-coder");
        assert_eq!(cap.skills.len(), 2);
        assert_eq!(cap.roles.len(), 1);
        assert_eq!(cap.specialties.len(), 1);
        assert!((cap.confidence["rust"] - 0.9).abs() < 0.001);
    }

    #[test]
    fn test_capability_match_score() {
        let mut cap = AgentCapability::new("gsea-reviewer");
        cap.add_role("reviewer");
        cap.add_skill("code review", 0.9);
        cap.add_skill("security", 0.7);

        // Should match "code review"
        let score = cap.match_score("code review");
        assert!(score > 0.0, "Expected match, got {}", score);

        // Should not match unrelated
        let score2 = cap.match_score("database migration");
        assert_eq!(score2, 0.0);
    }

    #[test]
    fn test_capability_discovery() {
        let mut reg = CapabilityRegistry::new();

        let mut coder = AgentCapability::new("gsea-coder");
        coder.add_skill("rust", 0.9);
        coder.add_skill("implementation", 0.9);
        reg.register(coder);

        let mut reviewer = AgentCapability::new("gsea-reviewer");
        reviewer.add_skill("code review", 0.9);
        reviewer.add_skill("security", 0.7);
        reg.register(reviewer);

        let matches = reg.discover("security");
        assert!(!matches.is_empty());
        assert_eq!(matches[0].0, "gsea-reviewer");

        let matches2 = reg.discover("rust implementation");
        assert!(!matches2.is_empty());
        assert_eq!(matches2[0].0, "gsea-coder");
    }

    #[test]
    fn test_capability_no_match() {
        let reg = CapabilityRegistry::new();
        let matches = reg.discover("nonexistent");
        assert!(matches.is_empty());
    }

    #[test]
    fn test_capability_duplicate_skill() {
        let mut cap = AgentCapability::new("a");
        cap.add_skill("rust", 0.5);
        cap.add_skill("rust", 0.9); // update confidence, don't duplicate
        assert_eq!(cap.skills.len(), 1);
        assert!((cap.confidence["rust"] - 0.9).abs() < 0.001);
    }

    // ─── Backpressure Tests ──────────────────────────────────────

    #[test]
    fn test_backpressure_accept() {
        let mut bp = TopicBackpressure::new("test", 3, OverflowPolicy::DropOldest);
        assert_eq!(bp.check(), BackpressureAction::Accept);
        assert_eq!(bp.check(), BackpressureAction::Accept);
        assert_eq!(bp.check(), BackpressureAction::Accept);
        // 4th message exceeds limit
        assert_eq!(bp.check(), BackpressureAction::DropOldest);
        assert_eq!(bp.dropped_count, 1);
    }

    #[test]
    fn test_backpressure_dlq_policy() {
        let mut bp = TopicBackpressure::new("test", 2, OverflowPolicy::SendToDLQ);
        bp.check(); // 1
        bp.check(); // 2
        assert_eq!(bp.check(), BackpressureAction::SendToDLQ); // overflow
        assert_eq!(bp.dlq_count, 1);
    }

    #[test]
    fn test_backpressure_block_policy() {
        let mut bp = TopicBackpressure::new("test", 1, OverflowPolicy::Block);
        assert_eq!(bp.check(), BackpressureAction::Accept);
        assert_eq!(bp.check(), BackpressureAction::Block);
    }

    #[test]
    fn test_backpressure_ack() {
        let mut bp = TopicBackpressure::new("test", 2, OverflowPolicy::DropOldest);
        bp.check(); // 1
        bp.check(); // 2
        bp.ack();   // 1
        assert_eq!(bp.check(), BackpressureAction::Accept); // 2 again
    }

    #[test]
    fn test_backpressure_display() {
        assert_eq!(format!("{}", OverflowPolicy::DropOldest), "drop-oldest");
        assert_eq!(format!("{}", OverflowPolicy::SendToDLQ), "send-to-dlq");
        assert_eq!(format!("{}", OverflowPolicy::Block), "block");
    }

    // ─── Task Scheduling Tests ───────────────────────────────────

    #[test]
    fn test_task_schedule_future() {
        let mut q = TaskQueue::new();
        let future = chrono::Utc::now() + chrono::Duration::hours(1);
        let id = q.enqueue_scheduled("future task".to_string(), None, QueuePriority::Normal, Vec::new(), Some(future));

        // Task exists but is not ready
        let task = q.tasks.iter().find(|t| t.id == id).unwrap();
        assert!(!q.is_ready(task));

        // steal should not return it
        assert!(q.steal(None).is_none());
    }

    #[test]
    fn test_task_schedule_past() {
        let mut q = TaskQueue::new();
        let past = chrono::Utc::now() - chrono::Duration::hours(1);
        let id = q.enqueue_scheduled("past task".to_string(), None, QueuePriority::Normal, Vec::new(), Some(past));

        let task = q.tasks.iter().find(|t| t.id == id).unwrap();
        assert!(q.is_ready(task));

        // steal should return it
        assert!(q.steal(None).is_some());
    }

    #[test]
    fn test_task_schedule_none() {
        let mut q = TaskQueue::new();
        let id = q.enqueue("immediate task".to_string(), None, QueuePriority::Normal);

        let task = q.tasks.iter().find(|t| t.id == id).unwrap();
        assert!(q.is_ready(task));
        assert!(task.run_at.is_none());
    }

    #[test]
    fn test_task_scheduled_list() {
        let mut q = TaskQueue::new();
        let future = chrono::Utc::now() + chrono::Duration::hours(1);
        q.enqueue("immediate".to_string(), None, QueuePriority::Normal);
        q.enqueue_scheduled("scheduled".to_string(), None, QueuePriority::Normal, Vec::new(), Some(future));

        let scheduled = q.scheduled();
        assert_eq!(scheduled.len(), 1);
        assert_eq!(scheduled[0].description, "scheduled");
    }

    #[test]
    fn test_saved_task_run_at_roundtrip() {
        let run_at = chrono::Utc::now() + chrono::Duration::hours(2);
        let saved = SavedQueuedTask {
            id: 1, description: "sched".to_string(),
            target_role: None, priority: "high".to_string(),
            status: "pending".to_string(),
            depends_on: Vec::new(),
            run_at: Some(run_at.to_rfc3339()),
        };

        let json = serde_json::to_string(&saved).unwrap();
        let restored: SavedQueuedTask = serde_json::from_str(&json).unwrap();
        assert!(restored.run_at.is_some());

        // Parse back
        let parsed: chrono::DateTime<chrono::Utc> = restored.run_at.unwrap().parse().unwrap();
        assert!((parsed - run_at).num_seconds().abs() < 2);
    }

