    // ── Gossip Protocol Tests ─────────────────────────────────────────

    #[test]
    fn test_gossip_ledger_add_and_about() {
        let mut ledger = GossipLedger::new();
        assert_eq!(ledger.len(), 0);

        ledger.add("coder", "reviewer", "thorough reviews", GossipSentiment::Positive);
        ledger.add("tester", "reviewer", "slow turnaround", GossipSentiment::Negative);
        ledger.add("coder", "tester", "good coverage", GossipSentiment::Positive);

        assert_eq!(ledger.len(), 3);

        let about_reviewer = ledger.about("reviewer");
        assert_eq!(about_reviewer.len(), 2);
        assert_eq!(about_reviewer[0].observer, "coder");
        assert_eq!(about_reviewer[1].observer, "tester");

        let about_tester = ledger.about("tester");
        assert_eq!(about_tester.len(), 1);

        let about_nobody = ledger.about("nobody");
        assert_eq!(about_nobody.len(), 0);
    }

    #[test]
    fn test_gossip_reputation() {
        let mut ledger = GossipLedger::new();
        ledger.add("a", "target", "good", GossipSentiment::Positive);
        ledger.add("b", "target", "ok", GossipSentiment::Neutral);
        ledger.add("c", "target", "bad", GossipSentiment::Negative);
        ledger.add("d", "target", "great", GossipSentiment::Positive);

        let (pos, neu, neg) = ledger.reputation("target");
        assert_eq!(pos, 2);
        assert_eq!(neu, 1);
        assert_eq!(neg, 1);

        // Unknown agent has zero reputation
        let (p, n, ng) = ledger.reputation("unknown");
        assert_eq!((p, n, ng), (0, 0, 0));
    }

    #[test]
    fn test_gossip_sentiment_display() {
        assert_eq!(format!("{}", GossipSentiment::Positive), "+");
        assert_eq!(format!("{}", GossipSentiment::Neutral), "~");
        assert_eq!(format!("{}", GossipSentiment::Negative), "-");
    }

