    #[test]
    fn test_replay_filter_empty_matches_all() {
        let filter = ReplayFilter::new();
        let entry = AuditEntry::new("test-topic", serde_json::json!({"agent": "coder"}));
        assert!(filter.matches(&entry));
    }

    #[test]
    fn test_replay_filter_topic() {
        let mut filter = ReplayFilter::new();
        filter.topic = Some("agent".to_string());

        let matching = AuditEntry::new("agent-chat", serde_json::json!({}));
        let non_matching = AuditEntry::new("system-event", serde_json::json!({}));

        assert!(filter.matches(&matching));
        assert!(!filter.matches(&non_matching));
    }

    #[test]
    fn test_replay_filter_agent() {
        let mut filter = ReplayFilter::new();
        filter.agent = Some("coder".to_string());

        let matching = AuditEntry::new("topic", serde_json::json!({"agent": "coder"}));
        let from_matching = AuditEntry::new("topic", serde_json::json!({"from": "coder"}));
        let non_matching = AuditEntry::new("topic", serde_json::json!({"agent": "tester"}));
        let no_agent = AuditEntry::new("topic", serde_json::json!({"data": "x"}));

        assert!(filter.matches(&matching));
        assert!(filter.matches(&from_matching));
        assert!(!filter.matches(&non_matching));
        assert!(!filter.matches(&no_agent));
    }

    #[test]
    fn test_replay_filter_event_type() {
        let mut filter = ReplayFilter::new();
        filter.event_type = Some("error".to_string());

        let matching = AuditEntry::new("topic", serde_json::json!({"type": "error"}));
        let non_matching = AuditEntry::new("topic", serde_json::json!({"type": "info"}));

        assert!(filter.matches(&matching));
        assert!(!filter.matches(&non_matching));
    }

    #[test]
    fn test_replay_filter_time_range() {
        let now = chrono::Utc::now();
        let mut filter = ReplayFilter::new();
        filter.after = Some(now - chrono::Duration::hours(1));
        filter.before = Some(now + chrono::Duration::hours(1));

        let entry = AuditEntry::new("topic", serde_json::json!({}));
        assert!(filter.matches(&entry)); // entry created "now" is within range
    }

    #[test]
    fn test_replay_filter_combined() {
        let mut filter = ReplayFilter::new();
        filter.topic = Some("chat".to_string());
        filter.agent = Some("coder".to_string());

        let both_match = AuditEntry::new("chat-log", serde_json::json!({"agent": "coder"}));
        let topic_only = AuditEntry::new("chat-log", serde_json::json!({"agent": "tester"}));
        let agent_only = AuditEntry::new("system", serde_json::json!({"agent": "coder"}));

        assert!(filter.matches(&both_match));
        assert!(!filter.matches(&topic_only));
        assert!(!filter.matches(&agent_only));
    }

