        monitor.heartbeat_success("agent-1", 100.0);
        monitor.heartbeat_success("agent-1", 200.0);
        monitor.heartbeat_error("agent-2");

        let s1 = monitor.status("agent-1").unwrap();
        assert_eq!(s1.success_count, 2);

        let s2 = monitor.status("agent-2").unwrap();
        assert_eq!(s2.error_count, 1);
