    #[test]
    fn test_branch_create_and_switch() {
        let mut bm = BranchManager::new();
        bm.active_branch_mut().add_message("user", "hello");
        assert!(bm.create("experiment").is_ok());

        let branches = bm.list();
        assert_eq!(branches.len(), 2);

        // New branch inherits messages
        assert!(bm.switch("experiment").is_ok());
        assert_eq!(bm.active_branch().messages.len(), 1);
        assert_eq!(bm.active_branch().messages[0].1, "hello");
    }

