    #[test]
    fn test_branch_merge() {
        let mut bm = BranchManager::new();
        bm.active_branch_mut().add_message("user", "shared");
        bm.create("feature").unwrap();
        bm.switch("feature").unwrap();
        bm.active_branch_mut().add_message("assistant", "new insight");
        bm.switch("main").unwrap();

        let added = bm.merge("feature").unwrap();
        assert_eq!(added, 1); // only "new insight" is new
    }

