    // ── Rate Limiting Tests ──────────────────────────────────────────

    #[test]
    fn test_rate_limiter_allows_under_limit() {
        let mut limiter = RateLimiter::new(5, 60);
        assert!(limiter.try_acquire());
        assert!(limiter.try_acquire());
        assert!(limiter.try_acquire());
        assert_eq!(limiter.current_count(), 3);
    }

    #[test]
    fn test_rate_limiter_blocks_over_limit() {
        let mut limiter = RateLimiter::new(2, 60);
        assert!(limiter.try_acquire());
        assert!(limiter.try_acquire());
        assert!(!limiter.try_acquire()); // blocked
    }

    #[test]
    fn test_rate_limiter_reset() {
        let mut limiter = RateLimiter::new(2, 60);
        limiter.try_acquire();
        limiter.try_acquire();
        assert!(!limiter.try_acquire());

        limiter.reset();
        assert!(limiter.try_acquire()); // reset cleared the window
    }

    #[test]
    fn test_rate_limit_registry() {
        let mut registry = RateLimitRegistry::new();
        registry.set("agent-coder", 10, 60);
        registry.set("topic-chat", 100, 300);

        assert_eq!(registry.list().len(), 2);
        assert!(registry.get("agent-coder").is_some());
        assert!(registry.get("unknown").is_none());
    }

    #[test]
    fn test_rate_limit_registry_acquire() {
        let mut registry = RateLimitRegistry::new();
        registry.set("test", 1, 60);
        assert_eq!(registry.try_acquire("test"), Some(true));
        assert_eq!(registry.try_acquire("test"), Some(false));
        assert_eq!(registry.try_acquire("unknown"), None);
    }

    #[test]
    fn test_rate_limit_registry_remove() {
        let mut registry = RateLimitRegistry::new();
        registry.set("test", 10, 60);
        assert!(registry.remove("test"));
        assert!(!registry.remove("test"));
    }

    // ── Event Correlation Tests ──────────────────────────────────────

    #[test]
    fn test_correlation_rule_creation() {
        let mut rule = CorrelationRule::new("error-warning", 30, "Error+Warning detected!");
        rule.add_condition("error", "level", "error");
        rule.add_condition("warning", "level", "warn");

        assert_eq!(rule.name, "error-warning");
        assert_eq!(rule.conditions.len(), 2);
        assert_eq!(rule.window_secs, 30);
        assert!(rule.enabled);
    }

    #[test]
    fn test_correlation_engine_add_rule() {
        let mut engine = CorrelationEngine::new();
        let rule = CorrelationRule::new("test", 60, "alert");
        let idx = engine.add_rule(rule);
        assert_eq!(idx, 0);
        assert_eq!(engine.rules().len(), 1);
    }

    #[test]
    fn test_correlation_engine_fires_when_all_conditions_met() {
        let mut engine = CorrelationEngine::new();
        let mut rule = CorrelationRule::new("combo", 60, "Both fired!");
        rule.add_condition("errors", "level", "error");
        rule.add_condition("warnings", "level", "warn");
        engine.add_rule(rule);

        // First condition
        let fired = engine.process_event("errors", &serde_json::json!({"level": "error"}));
        assert!(fired.is_empty()); // not both yet

        // Second condition
        let fired = engine.process_event("warnings", &serde_json::json!({"level": "warn"}));
        assert_eq!(fired.len(), 1);
        assert_eq!(fired[0], 0);
        assert_eq!(engine.fired_alerts().len(), 1);
    }

    #[test]
    fn test_correlation_engine_no_fire_when_disabled() {
        let mut engine = CorrelationEngine::new();
        let mut rule = CorrelationRule::new("disabled", 60, "alert");
        rule.add_condition("topic", "key", "val");
        rule.enabled = false;
        engine.add_rule(rule);

        let fired = engine.process_event("topic", &serde_json::json!({"key": "val"}));
        assert!(fired.is_empty());
    }

    #[test]
    fn test_correlation_engine_enable_disable() {
        let mut engine = CorrelationEngine::new();
        let rule = CorrelationRule::new("test", 60, "alert");
        engine.add_rule(rule);

        engine.disable_rule(0);
        assert!(!engine.rules()[0].enabled);

        engine.enable_rule(0);
        assert!(engine.rules()[0].enabled);
    }

    #[test]
    fn test_correlation_no_false_positive() {
        let mut engine = CorrelationEngine::new();
        let mut rule = CorrelationRule::new("specific", 60, "alert");
        rule.add_condition("errors", "level", "critical");
        engine.add_rule(rule);

        // Wrong value
        let fired = engine.process_event("errors", &serde_json::json!({"level": "info"}));
        assert!(fired.is_empty());

        // Wrong topic
        let fired = engine.process_event("other", &serde_json::json!({"level": "critical"}));
        assert!(fired.is_empty());
    }

    // ── Quorum Tests ─────────────────────────────────────────────────

    #[test]
    fn test_quorum_config_creation() {
        let qc = QuorumConfig::new(2, 3);
        assert_eq!(qc.min_agree, 2);
        assert_eq!(qc.total_agents, 3);
        assert!(qc.enabled);
        assert!(qc.is_valid());
    }

    #[test]
    fn test_quorum_config_invalid() {
        let qc = QuorumConfig::new(4, 3); // min > total
        assert!(!qc.is_valid());

        let qc2 = QuorumConfig::new(0, 3); // min = 0
        assert!(!qc2.is_valid());
    }

    #[test]
    fn test_quorum_result_met() {
        let mut result = QuorumResult::new("what is 2+2?");
        result.add_response("agent-1", "4");
        result.add_response("agent-2", "4");
        result.add_response("agent-3", "5");

        result.evaluate(2);
        assert!(result.quorum_met);
        assert_eq!(result.agreement_count, 2);
        assert_eq!(result.consensus_answer.as_deref(), Some("4"));
    }

    #[test]
    fn test_quorum_result_not_met() {
        let mut result = QuorumResult::new("what is the meaning?");
        result.add_response("agent-1", "42");
        result.add_response("agent-2", "love");
        result.add_response("agent-3", "nothing");

        result.evaluate(2);
        assert!(!result.quorum_met);
        assert_eq!(result.agreement_count, 1);
        assert!(result.consensus_answer.is_none());
    }

    #[test]
    fn test_quorum_result_empty() {
        let mut result = QuorumResult::new("test");
        result.evaluate(1);
        assert!(!result.quorum_met);
    }

    #[test]
    fn test_quorum_result_all_agree() {
        let mut result = QuorumResult::new("test");
        result.add_response("a", "yes");
        result.add_response("b", "yes");
        result.add_response("c", "yes");
        result.evaluate(3);
        assert!(result.quorum_met);
        assert_eq!(result.agreement_count, 3);
    }

    #[test]
    fn test_quorum_case_insensitive() {
        let mut result = QuorumResult::new("test");
        result.add_response("a", "Yes");
        result.add_response("b", "yes");
        result.add_response("c", "NO");
        result.evaluate(2);
        assert!(result.quorum_met);
        assert_eq!(result.agreement_count, 2);
    }

