    // ── Metric Alert Tests ───────────────────────────────────────────

    #[test]
    fn test_metric_alert_should_fire_gt() {
        let alert = MetricAlert::new("high-latency", "latency", AlertComparison::GreaterThan, 1000.0, AlertSeverity::Warning);
        assert!(alert.should_fire(1500.0));
        assert!(!alert.should_fire(500.0));
        assert!(!alert.should_fire(1000.0)); // not strictly greater
    }

    #[test]
    fn test_metric_alert_should_fire_lt() {
        let alert = MetricAlert::new("low-throughput", "throughput", AlertComparison::LessThan, 10.0, AlertSeverity::Critical);
        assert!(alert.should_fire(5.0));
        assert!(!alert.should_fire(15.0));
    }

    #[test]
    fn test_metric_alert_disabled() {
        let mut alert = MetricAlert::new("test", "metric", AlertComparison::GreaterThan, 0.0, AlertSeverity::Warning);
        alert.enabled = false;
        assert!(!alert.should_fire(100.0));
    }

    #[test]
    fn test_metric_alert_cooldown() {
        let mut alert = MetricAlert::new("test", "metric", AlertComparison::GreaterThan, 0.0, AlertSeverity::Warning);
        alert.cooldown_secs = 3600; // 1 hour
        assert!(alert.should_fire(100.0));
        alert.fire();
        assert!(!alert.should_fire(100.0)); // in cooldown
    }

    #[test]
    fn test_metric_alert_acknowledge() {
        let mut alert = MetricAlert::new("test", "metric", AlertComparison::GreaterThan, 0.0, AlertSeverity::Warning);
        alert.fire();
        assert!(!alert.acknowledged);
        alert.acknowledge();
        assert!(alert.acknowledged);
    }

    #[test]
    fn test_metric_alert_registry_check() {
        let mut reg = MetricAlertRegistry::new();
        reg.add(MetricAlert::new("lat", "latency", AlertComparison::GreaterThan, 100.0, AlertSeverity::Warning));
        reg.add(MetricAlert::new("err", "errors", AlertComparison::GreaterThan, 5.0, AlertSeverity::Critical));

        let fired = reg.check("latency", 200.0);
        assert_eq!(fired.len(), 1);
        assert_eq!(fired[0], 0);

        let fired2 = reg.check("errors", 2.0);
        assert!(fired2.is_empty());
    }

    #[test]
    fn test_metric_alert_history() {
        let mut reg = MetricAlertRegistry::new();
        reg.add(MetricAlert::new("test", "m", AlertComparison::GreaterThan, 0.0, AlertSeverity::Warning));
        reg.check("m", 1.0);
        assert_eq!(reg.history().len(), 1);
    }

