    // ── Delegation Chain Tests ───────────────────────────────────────

    #[test]
    fn test_delegation_create() {
        let mut dm = DelegationManager::new(3);
        let id = dm.delegate("boss", "worker", "build feature", None).unwrap();
        assert_eq!(id, 1);
        assert_eq!(dm.list().len(), 1);
        assert_eq!(dm.list()[0].depth, 0);
    }

    #[test]
    fn test_delegation_chain_depth() {
        let mut dm = DelegationManager::new(3);
        let id1 = dm.delegate("a", "b", "task1", None).unwrap();
        let id2 = dm.delegate("b", "c", "task2", Some(id1)).unwrap();
        let id3 = dm.delegate("c", "d", "task3", Some(id2)).unwrap();
        assert_eq!(dm.list()[2].depth, 2);

        // Exceeds max depth
        assert!(dm.delegate("d", "e", "task4", Some(id3)).is_err());
    }

    #[test]
    fn test_delegation_approve_reject() {
        let mut dm = DelegationManager::new(5);
        let id1 = dm.delegate("a", "b", "task1", None).unwrap();
        let id2 = dm.delegate("a", "c", "task2", None).unwrap();

        dm.approve(id1).unwrap();
        assert_eq!(dm.list()[0].status, DelegationStatus::Approved);

        dm.reject(id2).unwrap();
        assert_eq!(dm.list()[1].status, DelegationStatus::Rejected);
    }

    #[test]
    fn test_delegation_approve_non_pending() {
        let mut dm = DelegationManager::new(5);
        let id = dm.delegate("a", "b", "task", None).unwrap();
        dm.approve(id).unwrap();
        assert!(dm.approve(id).is_err()); // already approved
    }

    #[test]
    fn test_delegation_complete() {
        let mut dm = DelegationManager::new(5);
        let id = dm.delegate("a", "b", "task", None).unwrap();
        dm.complete(id, "done successfully").unwrap();
        assert!(matches!(dm.list()[0].status, DelegationStatus::Completed(_)));
    }

    #[test]
    fn test_delegation_chain_traversal() {
        let mut dm = DelegationManager::new(5);
        let id1 = dm.delegate("a", "b", "t1", None).unwrap();
        let id2 = dm.delegate("b", "c", "t2", Some(id1)).unwrap();
        let id3 = dm.delegate("c", "d", "t3", Some(id2)).unwrap();

        let chain = dm.chain(id3);
        assert_eq!(chain.len(), 3);
        assert_eq!(chain[0].from, "a");
        assert_eq!(chain[1].from, "b");
        assert_eq!(chain[2].from, "c");
    }

    #[test]
    fn test_delegation_pending() {
        let mut dm = DelegationManager::new(5);
        dm.delegate("a", "b", "t1", None).unwrap();
        let id2 = dm.delegate("a", "c", "t2", None).unwrap();
        dm.approve(id2).unwrap();

        assert_eq!(dm.pending().len(), 1); // only first is pending
    }

    #[test]
    fn test_delegation_by_agent() {
        let mut dm = DelegationManager::new(5);
        dm.delegate("a", "b", "t1", None).unwrap();
        dm.delegate("b", "c", "t2", None).unwrap();
        dm.delegate("a", "c", "t3", None).unwrap();

        let a_dels = dm.by_agent("a");
        assert_eq!(a_dels.len(), 2);

        let b_dels = dm.by_agent("b");
        assert_eq!(b_dels.len(), 2); // both as from and to
    }

    #[test]
    fn test_delegation_status_display() {
        assert_eq!(format!("{}", DelegationStatus::Pending), "PENDING");
        assert_eq!(format!("{}", DelegationStatus::Approved), "APPROVED");
        assert_eq!(format!("{}", DelegationStatus::Rejected), "REJECTED");
        let completed = DelegationStatus::Completed("result".to_string());
        assert!(format!("{}", completed).contains("COMPLETED"));
    }

    // ── Semantic Event Routing Tests ─────────────────────────────────

    #[test]
    fn test_semantic_route_score() {
        let route = SemanticRoute::new("code-route", "coder", vec!["code".to_string(), "rust".to_string(), "bug".to_string()], 0.5);
        assert!((route.score("I found a bug in the code") - 0.666).abs() < 0.01); // 2/3
        assert!((route.score("hello world") - 0.0).abs() < 0.01); // 0/3
        assert!((route.score("rust code bug fix") - 1.0).abs() < 0.01); // 3/3
    }

    #[test]
    fn test_semantic_route_matches() {
        let route = SemanticRoute::new("test", "agent", vec!["error".to_string(), "crash".to_string()], 0.5);
        assert!(route.matches("there was an error")); // 1/2 = 0.5 >= 0.5
        assert!(!route.matches("everything is fine")); // 0/2
    }

    #[test]
    fn test_semantic_route_disabled() {
        let mut route = SemanticRoute::new("test", "agent", vec!["error".to_string()], 0.5);
        route.enabled = false;
        assert!(!route.matches("error occurred")); // disabled
    }

    #[test]
    fn test_semantic_router_routing() {
        let mut router = SemanticRouter::new();
        router.add(SemanticRoute::new("code", "coder", vec!["code".to_string(), "rust".to_string()], 0.5));
        router.add(SemanticRoute::new("review", "reviewer", vec!["review".to_string(), "quality".to_string()], 0.5));

        let matches = router.route("please review this code");
        assert_eq!(matches.len(), 2); // both match

        let matches2 = router.route("deploy to production");
        assert!(matches2.is_empty());
    }

    #[test]
    fn test_semantic_router_sorted_by_score() {
        let mut router = SemanticRouter::new();
        router.add(SemanticRoute::new("partial", "a", vec!["code".to_string(), "test".to_string(), "deploy".to_string()], 0.3));
        router.add(SemanticRoute::new("full", "b", vec!["code".to_string()], 0.5));

        let matches = router.route("code is here");
        // "full" should rank higher (1.0 vs 0.33)
        assert!(matches.len() >= 2);
        assert!(matches[0].2 >= matches[1].2);
    }

    #[test]
    fn test_semantic_router_enable_disable() {
        let mut router = SemanticRouter::new();
        router.add(SemanticRoute::new("test", "agent", vec!["error".to_string()], 0.5));

        assert_eq!(router.route("error occurred").len(), 1);
        router.disable(0);
        assert_eq!(router.route("error occurred").len(), 0);
        router.enable(0);
        assert_eq!(router.route("error occurred").len(), 1);
    }

    #[test]
    fn test_semantic_router_remove() {
        let mut router = SemanticRouter::new();
        router.add(SemanticRoute::new("a", "a", vec!["x".to_string()], 0.5));
        router.add(SemanticRoute::new("b", "b", vec!["y".to_string()], 0.5));
        assert_eq!(router.list().len(), 2);

        let removed = router.remove(0).unwrap();
        assert_eq!(removed.name, "a");
        assert_eq!(router.list().len(), 1);
    }

    #[test]
    fn test_semantic_route_case_insensitive() {
        let route = SemanticRoute::new("test", "agent", vec!["Error".to_string(), "CRASH".to_string()], 0.5);
        assert!(route.matches("an error occurred")); // case insensitive
        assert!(route.matches("SYSTEM ERROR AND CRASH")); // all caps
    }

