    #[test]
    fn test_hook_fire() {
        let mut hr = HookRegistry::new();
        hr.add("h1", HookEvent::BeforeChat, "action1");
        hr.add("h2", HookEvent::AfterChat, "action2");
        hr.add("h3", HookEvent::BeforeChat, "action3");

        let fired = hr.fire(&HookEvent::BeforeChat);
        assert_eq!(fired.len(), 2); // h1 and h3

        let fired2 = hr.fire(&HookEvent::AfterChat);
        assert_eq!(fired2.len(), 1); // h2
    }

    #[test]
    fn test_hook_fire_disabled() {
        let mut hr = HookRegistry::new();
        let id = hr.add("h1", HookEvent::OnError, "action");
        hr.disable(id);

        let fired = hr.fire(&HookEvent::OnError);
        assert!(fired.is_empty());

        hr.enable(id);
        let fired2 = hr.fire(&HookEvent::OnError);
        assert_eq!(fired2.len(), 1);
    }

