    // ── Consensus Protocol Tests ─────────────────────────────────────

    #[test]
    fn test_consensus_proposal_creation() {
        let p = ConsensusProposal::new(1, "proposer", "deploy", "v2.0", 3, 1);
        assert_eq!(p.phase, ConsensusPhase::Propose);
        assert_eq!(p.required_acks, 2); // 3 - 1
        assert_eq!(p.total_participants, 3);
    }

    #[test]
    fn test_consensus_voting() {
        let mut p = ConsensusProposal::new(1, "user", "choice", "A", 3, 1);
        assert!(p.vote("agent-1", ConsensusVote::Ack));
        assert!(!p.vote("agent-1", ConsensusVote::Nack)); // duplicate
        assert!(p.vote("agent-2", ConsensusVote::Ack));

        assert_eq!(p.ack_count(), 2);
        assert_eq!(p.nack_count(), 0);
    }

    #[test]
    fn test_consensus_reaches_commit() {
        let mut p = ConsensusProposal::new(1, "user", "deploy", "yes", 3, 1);
        p.vote("a", ConsensusVote::Ack);
        p.vote("b", ConsensusVote::Ack);
        p.evaluate();
        assert_eq!(p.phase, ConsensusPhase::Commit);

        p.evaluate(); // commit → decided
        assert_eq!(p.phase, ConsensusPhase::Decided);
        assert!(p.is_decided());
        assert_eq!(p.decided_value.as_deref(), Some("yes"));
    }

    #[test]
    fn test_consensus_fails() {
        let mut p = ConsensusProposal::new(1, "user", "deploy", "yes", 3, 1);
        // Required acks = 2, so if 2 nack, proposal fails
        p.vote("a", ConsensusVote::Nack);
        p.vote("b", ConsensusVote::Nack);
        p.evaluate();
        assert_eq!(p.phase, ConsensusPhase::Failed);
    }

    #[test]
    fn test_consensus_manager_propose_and_vote() {
        let mut cm = ConsensusManager::new(1);
        let id = cm.propose("user", "deploy", "v2", 4); // 4 participants, f=1, need 3 acks
        assert_eq!(id, 1);

        cm.vote(id, "agent-1", ConsensusVote::Ack).unwrap();
        cm.vote(id, "agent-2", ConsensusVote::Ack).unwrap();
        cm.vote(id, "agent-3", ConsensusVote::Ack).unwrap();

        let p = cm.get(id).unwrap();
        assert_eq!(p.phase, ConsensusPhase::Commit);
    }

    #[test]
    fn test_consensus_manager_duplicate_vote() {
        let mut cm = ConsensusManager::new(1);
        let id = cm.propose("user", "test", "val", 3);
        cm.vote(id, "agent-1", ConsensusVote::Ack).unwrap();
        assert!(cm.vote(id, "agent-1", ConsensusVote::Nack).is_err());
    }

    #[test]
    fn test_consensus_manager_active() {
        let mut cm = ConsensusManager::new(0);
        cm.propose("user", "t1", "v1", 3);
        cm.propose("user", "t2", "v2", 3);

        let id = 1;
        cm.vote(id, "a", ConsensusVote::Ack).unwrap();
        cm.vote(id, "b", ConsensusVote::Ack).unwrap();
        cm.vote(id, "c", ConsensusVote::Ack).unwrap();
        // After evaluate in vote, proposal 1 should be committed
        // Need one more evaluate to go to Decided
        {
            let p = cm.proposals.iter_mut().find(|p| p.id == 1).unwrap();
            p.evaluate(); // commit -> decided
        }

        assert_eq!(cm.active().len(), 1); // only proposal 2
    }

    #[test]
    fn test_consensus_phase_display() {
        assert_eq!(format!("{}", ConsensusPhase::Propose), "PROPOSE");
        assert_eq!(format!("{}", ConsensusPhase::Prepare), "PREPARE");
        assert_eq!(format!("{}", ConsensusPhase::Commit), "COMMIT");
        assert_eq!(format!("{}", ConsensusPhase::Decided), "DECIDED");
        assert_eq!(format!("{}", ConsensusPhase::Failed), "FAILED");
    }

    #[test]
    fn test_consensus_vote_on_decided() {
        let mut cm = ConsensusManager::new(0);
        let id = cm.propose("user", "test", "val", 1);
        cm.vote(id, "a", ConsensusVote::Ack).unwrap();
        // After commit, evaluate to decided
        cm.proposals.iter_mut().find(|p| p.id == id).unwrap().evaluate();

        assert!(cm.vote(id, "b", ConsensusVote::Ack).is_err()); // already decided
    }

