    #[test]
    fn test_circuit_snapshot_lifecycle() {
        let mut cb = CircuitBreakerSnapshot::new("ollama");
        assert_eq!(cb.state, "closed");

        cb.record_success();
        cb.record_success();
        assert_eq!(cb.success_count, 2);

        cb.record_failure();
        cb.record_failure();
        assert_eq!(cb.failure_count, 2);

        cb.trip();
        assert_eq!(cb.state, "open");
        assert_eq!(cb.trip_count, 1);
        assert!(cb.last_trip.is_some());

        cb.half_open();
        assert_eq!(cb.state, "half-open");

        cb.reset();
        assert_eq!(cb.state, "closed");
        assert_eq!(cb.failure_count, 0);
    }

