    // ── Agent Communication Protocol Tests ───────────────────────────

    #[test]
    fn test_message_bus_send() {
        let mut bus = MessageBus::new();
        let id = bus.send("coder", MessageTarget::Direct("reviewer".to_string()),
            "please review", MessagePriority::Normal, MessagePattern::FireAndForget);
        assert_eq!(id, 1);
        assert_eq!(bus.len(), 1);
    }

    #[test]
    fn test_message_bus_inbox() {
        let mut bus = MessageBus::new();
        bus.send("a", MessageTarget::Direct("b".to_string()), "msg1",
            MessagePriority::Normal, MessagePattern::FireAndForget);
        bus.send("a", MessageTarget::Direct("c".to_string()), "msg2",
            MessagePriority::Normal, MessagePattern::FireAndForget);
        bus.send("a", MessageTarget::Broadcast, "announcement",
            MessagePriority::High, MessagePattern::PubSub);

        let b_inbox = bus.inbox("b");
        assert_eq!(b_inbox.len(), 2); // direct + broadcast

        let c_inbox = bus.inbox("c");
        assert_eq!(c_inbox.len(), 2); // direct + broadcast
    }

    #[test]
    fn test_message_bus_reply() {
        let mut bus = MessageBus::new();
        let id = bus.send("a", MessageTarget::Direct("b".to_string()), "question?",
            MessagePriority::Normal, MessagePattern::RequestReply);

        let reply_id = bus.reply(id, "b", "answer!").unwrap();
        assert_eq!(reply_id, 2);

        let chain = bus.by_correlation(id);
        assert_eq!(chain.len(), 2); // original + reply
    }

    #[test]
    fn test_message_bus_reply_nonexistent() {
        let mut bus = MessageBus::new();
        assert!(bus.reply(999, "a", "reply").is_none());
    }

    #[test]
    fn test_message_target_display() {
        assert_eq!(format!("{}", MessageTarget::Direct("agent".to_string())), "@agent");
        assert_eq!(format!("{}", MessageTarget::Broadcast), "*broadcast*");
        assert_eq!(format!("{}", MessageTarget::Topic("chat".to_string())), "#chat");
    }

    #[test]
    fn test_message_priority_display() {
        assert_eq!(format!("{}", MessagePriority::Low), "low");
        assert_eq!(format!("{}", MessagePriority::Urgent), "urgent");
    }

    #[test]
    fn test_message_pattern_display() {
        assert_eq!(format!("{}", MessagePattern::FireAndForget), "fire-and-forget");
        assert_eq!(format!("{}", MessagePattern::RequestReply), "request-reply");
        assert_eq!(format!("{}", MessagePattern::PubSub), "pub-sub");
    }

    #[test]
    fn test_message_bus_recent() {
        let mut bus = MessageBus::new();
        for i in 0..10 {
            bus.send("a", MessageTarget::Broadcast, &format!("msg{}", i),
                MessagePriority::Normal, MessagePattern::PubSub);
        }
        let recent = bus.recent(3);
        assert_eq!(recent.len(), 3);
        assert!(recent[0].content.contains("msg9")); // most recent first
    }

    // ── Adaptive Rate Control Tests ──────────────────────────────────

    #[test]
    fn test_adaptive_rate_initial() {
        let arc = AdaptiveRateController::new("test", 50.0);
        assert_eq!(arc.current_rate(), 50.0);
        assert!(arc.history().is_empty());
    }

    #[test]
    fn test_adaptive_rate_registry() {
        let mut reg = AdaptiveRateRegistry::new();
        reg.add("agent-a", 100.0);
        reg.add("agent-b", 50.0);

        assert_eq!(reg.list().len(), 2);
        assert_eq!(reg.get("agent-a").unwrap().current_rate(), 100.0);
    }

    #[test]
    fn test_adaptive_rate_tune() {
        let mut reg = AdaptiveRateRegistry::new();
        reg.add("test", 50.0);
        reg.tune("test", 5.0, 0.3);

        let c = reg.get("test").unwrap();
        assert_eq!(c.additive_increase, 5.0);
        assert_eq!(c.multiplicative_decrease, 0.3);
    }

    #[test]
    fn test_adaptive_rate_clamp() {
        let mut arc = AdaptiveRateController::new("test", 999.0);
        arc.max_rate = 1000.0;
        arc.additive_increase = 100.0;
        arc.window_secs = 0; // immediate adjustment
        arc.record_success();
        assert!(arc.current_rate() <= 1000.0);
    }

    #[test]
    fn test_adaptive_rate_decrease_on_errors() {
        let mut arc = AdaptiveRateController::new("test", 100.0);
        arc.window_secs = 0; // immediate adjustment
        arc.multiplicative_decrease = 0.5;
        // All errors in window
        for _ in 0..5 {
            arc.record_error();
        }
        // After window adjustment, rate should decrease
        assert!(arc.current_rate() <= 100.0);
    }

