    // ─── Round 8: Replay Engine Tests ───────────────────────────

    #[test]
    fn test_replay_session_navigation() {
        let entries = vec![
            AuditEntry::new("t1", serde_json::json!({"a": 1})),
            AuditEntry::new("t2", serde_json::json!({"a": 2})),
            AuditEntry::new("t3", serde_json::json!({"a": 3})),
        ];
        let mut s = ReplaySession::new(entries);
        assert_eq!(s.len(), 3);
        assert_eq!(s.position(), 0);
        assert_eq!(s.current().unwrap().topic, "t1");
        s.step_forward();
        assert_eq!(s.position(), 1);
        assert_eq!(s.current().unwrap().topic, "t2");
        s.step_forward();
        assert_eq!(s.position(), 2);
        assert_eq!(s.current().unwrap().topic, "t3");
    }

    #[test]
    fn test_replay_session_step_backward() {
        let entries = vec![
            AuditEntry::new("a", serde_json::json!({})),
            AuditEntry::new("b", serde_json::json!({})),
        ];
        let mut s = ReplaySession::new(entries);
        s.step_forward();
        assert_eq!(s.position(), 1);
        s.step_backward();
        assert_eq!(s.position(), 0);
        s.step_backward(); // already at 0
        assert_eq!(s.position(), 0);
    }

    #[test]
    fn test_replay_session_goto() {
        let entries = vec![
            AuditEntry::new("a", serde_json::json!({})),
            AuditEntry::new("b", serde_json::json!({})),
            AuditEntry::new("c", serde_json::json!({})),
        ];
        let mut s = ReplaySession::new(entries);
        s.goto(2);
        assert_eq!(s.position(), 2);
        assert_eq!(s.current().unwrap().topic, "c");
        s.goto(100); // out of bounds — stays at 2
        assert_eq!(s.position(), 2);
    }

    #[test]
    fn test_replay_session_remaining() {
        let entries = vec![
            AuditEntry::new("a", serde_json::json!({})),
            AuditEntry::new("b", serde_json::json!({})),
            AuditEntry::new("c", serde_json::json!({})),
        ];
        let mut s = ReplaySession::new(entries);
        assert_eq!(s.remaining(), 2);
        s.step_forward();
        assert_eq!(s.remaining(), 1);
        s.step_forward();
        assert_eq!(s.remaining(), 0);
    }

    // ─── Round 8: Trust Scoring Tests ───────────────────────────

    #[test]
    fn test_trust_factor_ema_update() {
        let mut f = TrustFactor::new("accuracy", 0.3);
        assert_eq!(f.score, 0.5); // default
        f.update(1.0);
        assert!(f.score > 0.5); // moved toward 1.0
        f.update(1.0);
        assert!(f.score > 0.5);
        assert_eq!(f.samples, 2);
    }

    #[test]
    fn test_trust_factor_clamps_value() {
        let mut f = TrustFactor::new("x", 1.0);
        f.update(5.0); // should be clamped to 1.0
        assert!(f.score <= 1.0);
        f.update(-3.0); // should be clamped to 0.0
        assert!(f.score >= 0.0);
    }

    #[test]
    fn test_agent_trust_score_composite() {
        let mut ts = AgentTrustScore::new("agent-1");
        // Default factors: accuracy(0.3), reliability(0.25), peer_review(0.2), task_completion(0.25)
        assert_eq!(ts.factors.len(), 4);
        let initial = ts.composite_score();
        assert!((initial - 0.5).abs() < 0.01); // all start at 0.5

        ts.update_factor("accuracy", 1.0);
        assert!(ts.composite_score() > initial);
    }

    #[test]
    fn test_trust_registry_update_and_get() {
        let mut reg = TrustRegistry::new();
        reg.update("a1", "accuracy", 0.9);
        reg.update("a1", "reliability", 0.8);
        let score = reg.get("a1").unwrap();
        assert!(score.composite_score() > 0.5);
        assert!(score.history.len() >= 2);
    }

    #[test]
    fn test_trust_registry_multiple_agents() {
        let mut reg = TrustRegistry::new();
        reg.update("a1", "accuracy", 0.9);
        reg.update("a2", "accuracy", 0.1);
        let s1 = reg.get("a1").unwrap().composite_score();
        let s2 = reg.get("a2").unwrap().composite_score();
        assert!(s1 > s2); // a1 more trusted
    }

    // ─── Round 8: Pipeline Orchestration Tests ──────────────────

    #[test]
    fn test_pipeline_create_and_add_stages() {
        let mut p = Pipeline::new(1, "deploy");
        p.add_stage("build", "cargo build", PipelineErrorAction::Abort);
        p.add_stage("test", "cargo test", PipelineErrorAction::Skip);
        p.add_stage("deploy", "deploy.sh", PipelineErrorAction::Retry(3));
        assert_eq!(p.stages.len(), 3);
        assert_eq!(p.status, PipelineStatus::Created);
    }

    #[test]
    fn test_pipeline_advance_through_stages() {
        let mut p = Pipeline::new(1, "build-pipe");
        p.add_stage("s1", "a1", PipelineErrorAction::Abort);
        p.add_stage("s2", "a2", PipelineErrorAction::Abort);
        p.add_stage("s3", "a3", PipelineErrorAction::Abort);
        p.status = PipelineStatus::Running;
        p.stages[0].status = PipelineStageStatus::Running;

        let next = p.advance();
        assert!(next.is_some());
        assert_eq!(next.unwrap().name, "s2");
        assert_eq!(p.stages[0].status, PipelineStageStatus::Completed);

        let next = p.advance();
        assert!(next.is_some());
        assert_eq!(next.unwrap().name, "s3");

        let next = p.advance();
        assert!(next.is_none()); // done
        assert_eq!(p.status, PipelineStatus::Completed);
    }

    #[test]
    fn test_pipeline_fail_with_abort() {
        let mut p = Pipeline::new(1, "p");
        p.add_stage("s1", "a1", PipelineErrorAction::Abort);
        p.status = PipelineStatus::Running;
        p.stages[0].status = PipelineStageStatus::Running;

        let action = p.fail_current("boom");
        assert_eq!(action, PipelineErrorAction::Abort);
        assert!(matches!(p.status, PipelineStatus::Aborted(_)));
    }

    #[test]
    fn test_pipeline_fail_with_skip() {
        let mut p = Pipeline::new(1, "p");
        p.add_stage("s1", "a1", PipelineErrorAction::Skip);
        p.add_stage("s2", "a2", PipelineErrorAction::Abort);
        p.status = PipelineStatus::Running;
        p.stages[0].status = PipelineStageStatus::Running;

        let action = p.fail_current("err");
        assert_eq!(action, PipelineErrorAction::Skip);
        assert_eq!(p.stages[0].status, PipelineStageStatus::Skipped);
        assert_eq!(p.status, PipelineStatus::Running); // not aborted
    }

    #[test]
    fn test_pipeline_manager_create_and_list() {
        let mut mgr = PipelineManager::new();
        let id1 = mgr.create("pipe-a");
        let id2 = mgr.create("pipe-b");
        assert_ne!(id1, id2);
        assert!(mgr.get(id1).is_some());
        assert!(mgr.get(id2).is_some());
    }

    #[test]
    fn test_pipeline_progress() {
        let mut p = Pipeline::new(1, "p");
        p.add_stage("s1", "a", PipelineErrorAction::Abort);
        p.add_stage("s2", "b", PipelineErrorAction::Abort);
        p.add_stage("s3", "c", PipelineErrorAction::Abort);
        assert_eq!(p.progress(), (0, 3));
        p.status = PipelineStatus::Running;
        p.stages[0].status = PipelineStageStatus::Running;
        p.advance();
        assert_eq!(p.progress(), (1, 3));
    }

    #[test]
    fn test_pipeline_abort_skips_pending() {
        let mut p = Pipeline::new(1, "p");
        p.add_stage("s1", "a", PipelineErrorAction::Abort);
        p.add_stage("s2", "b", PipelineErrorAction::Abort);
        p.stages[0].status = PipelineStageStatus::Completed;
        p.abort("manual abort");
        assert!(matches!(p.status, PipelineStatus::Aborted(_)));
        assert_eq!(p.stages[1].status, PipelineStageStatus::Skipped);
    }

    // ─── Round 8: Metric Aggregation Window Tests ───────────────

    #[test]
    fn test_metric_window_push_and_stats() {
        let mut w = MetricWindow::new("latency", 300);
        w.push(10.0);
        w.push(20.0);
        w.push(30.0);
        assert_eq!(w.count(), 3);
        assert_eq!(w.min(), Some(10.0));
        assert_eq!(w.max(), Some(30.0));
        assert!((w.avg().unwrap() - 20.0).abs() < 0.01);
        assert_eq!(w.sum(), 60.0);
    }

    #[test]
    fn test_metric_window_percentile() {
        let mut w = MetricWindow::new("p", 300);
        for i in 1..=100 {
            w.push(i as f64);
        }
        let p50 = w.percentile(50.0).unwrap();
        assert!(p50 >= 49.0 && p50 <= 51.0);
        let p99 = w.percentile(99.0).unwrap();
        assert!(p99 >= 98.0 && p99 <= 100.0);
    }

    #[test]
    fn test_metric_window_empty() {
        let mut w = MetricWindow::new("empty", 300);
        assert_eq!(w.count(), 0);
        assert_eq!(w.min(), None);
        assert_eq!(w.max(), None);
        assert_eq!(w.avg(), None);
        assert_eq!(w.sum(), 0.0);
        assert_eq!(w.percentile(50.0), None);
    }

    #[test]
    fn test_metric_window_registry() {
        let mut reg = MetricWindowRegistry::new();
        reg.create("latency", 60);
        reg.create("throughput", 120);
        reg.push("latency", 5.0);
        reg.push("latency", 10.0);
        reg.push("throughput", 100.0);
        let w = reg.get_mut("latency").unwrap();
        assert_eq!(w.count(), 2);
        assert_eq!(reg.list().len(), 2);
    }

    #[test]
    fn test_metric_window_single_value() {
        let mut w = MetricWindow::new("single", 300);
        w.push(42.0);
        assert_eq!(w.min(), Some(42.0));
        assert_eq!(w.max(), Some(42.0));
        assert_eq!(w.avg(), Some(42.0));
        assert_eq!(w.percentile(99.0), Some(42.0));
    }

