        assert!(sid.is_some());
        assert_eq!(sid.unwrap(), "span-1");
        let sid2 = reg.start_span("t1", "a2", "test", Some("span-1"));
        assert_eq!(sid2.unwrap(), "span-2");
        reg.finish_span("t1", "span-1", TraceSpanStatus::Completed);
