    fn test_trace_duration() {
        let mut t = DistributedTrace::new("t1");
        t.start_span("s1", "a1", "op", None);
        t.finish_span("s1", TraceSpanStatus::Completed);
        let dur = t.duration_ms();
        assert!(dur.is_some());
        assert!(dur.unwrap() >= 0);
    }

    // ─── Round 9: Conflict Resolution Tests ─────────────────────

    #[test]
    fn test_conflict_priority_resolution() {
        let mut c = Conflict::new(1, "code-style", ConflictStrategy::Priority);
        c.add_entry("coder", "use tabs", 1);
        c.add_entry("reviewer", "use spaces", 5);
        c.add_entry("tester", "use tabs", 2);
        let result = c.resolve();
        assert_eq!(result, "use spaces"); // highest priority
        assert!(c.is_resolved());
    }

    #[test]
    fn test_conflict_voting_resolution() {
        let mut c = Conflict::new(1, "naming", ConflictStrategy::Voting);
        c.add_entry("a1", "camelCase", 1);
        c.add_entry("a2", "snake_case", 1);
        c.add_entry("a3", "snake_case", 1);
        let result = c.resolve();
        assert_eq!(result, "snake_case"); // majority wins
    }

    #[test]
    fn test_conflict_first_wins_resolution() {
        let mut c = Conflict::new(1, "x", ConflictStrategy::FirstWins);
        c.add_entry("a1", "first", 1);
        c.add_entry("a2", "second", 1);
        let result = c.resolve();
        assert_eq!(result, "first");
    }

    #[test]
    fn test_conflict_merge_resolution() {
        let mut c = Conflict::new(1, "x", ConflictStrategy::Merge);
        c.add_entry("a1", "hello", 1);
        c.add_entry("a2", "world", 1);
        let result = c.resolve();
        assert!(result.contains("[a1] hello"));
        assert!(result.contains("[a2] world"));
    }

    #[test]
    fn test_conflict_manager() {
        let mut mgr = ConflictManager::new();
        let id = mgr.create("topic1", Some(ConflictStrategy::Voting));
        assert_eq!(mgr.unresolved().len(), 1);
        mgr.get_mut(id).unwrap().add_entry("a1", "yes", 1);
        mgr.get_mut(id).unwrap().resolve();
        assert_eq!(mgr.unresolved().len(), 0);
    }

    #[test]
    fn test_conflict_default_strategy() {
        let mut mgr = ConflictManager::new();
        mgr.set_default_strategy(ConflictStrategy::Merge);
        let id = mgr.create("t", None);
        assert_eq!(mgr.get(id).unwrap().strategy, ConflictStrategy::Merge);
    }

