    #[test]
    fn test_dep_graph_add_and_query() {
        let mut g = DependencyGraph::new();
        g.add("coder", "reviewer", "review");
        g.add("tester", "coder", "test-input");
        assert_eq!(g.dependencies_of("coder"), vec!["reviewer"]);
        assert_eq!(g.dependents_of("coder"), vec!["tester"]);
    }

    #[test]
    fn test_dep_graph_no_duplicates() {
        let mut g = DependencyGraph::new();
        g.add("a", "b", "x");
        g.add("a", "b", "y"); // duplicate edge not added
        assert_eq!(g.edges.len(), 1);
    }

    #[test]
    fn test_dep_graph_remove() {
        let mut g = DependencyGraph::new();
        g.add("a", "b", "x");
        g.add("a", "c", "y");
        g.remove("a", "b");
        assert_eq!(g.dependencies_of("a"), vec!["c"]);
    }

    #[test]
    fn test_dep_graph_cycle_detection() {
        let mut g = DependencyGraph::new();
        g.add("a", "b", "x");
        g.add("b", "c", "x");
        g.add("c", "a", "x"); // cycle: a→b→c→a
        let cycle = g.has_cycle();
        assert!(cycle.is_some());
        let path = cycle.unwrap();
        assert!(path.len() >= 3);
    }

    #[test]
    fn test_dep_graph_no_cycle() {
        let mut g = DependencyGraph::new();
        g.add("a", "b", "x");
        g.add("b", "c", "x");
        assert!(g.has_cycle().is_none());
    }

    #[test]
    fn test_dep_graph_critical_path() {
        let mut g = DependencyGraph::new();
        g.add("a", "b", "x");
        g.add("b", "c", "x");
        g.add("c", "d", "x");
        let path = g.critical_path();
        assert_eq!(path.len(), 4); // a→b→c→d
    }

    // ─── Round 9: Scheduled Task Engine Tests ───────────────────

    #[test]
    fn test_scheduler_add_and_list() {
        let mut sched = TaskScheduler::new();
        let id1 = sched.add("health-check", "/health", 60);
        let id2 = sched.add("backup", "/save", 3600);
        assert_ne!(id1, id2);
        assert_eq!(sched.list().len(), 2);
        assert_eq!(sched.get(id1).unwrap().name, "health-check");
    }

    #[test]
    fn test_scheduler_remove() {
        let mut sched = TaskScheduler::new();
        let id = sched.add("test", "/test", 60);
        assert!(sched.remove(id));
        assert!(sched.list().is_empty());
        assert!(!sched.remove(999)); // not found
    }

    #[test]
    fn test_scheduler_enable_disable() {
        let mut sched = TaskScheduler::new();
        let id = sched.add("test", "/test", 60);
        assert!(sched.get(id).unwrap().enabled);
        sched.disable(id);
        assert!(!sched.get(id).unwrap().enabled);
        sched.enable(id);
        assert!(sched.get(id).unwrap().enabled);
    }

    #[test]
    fn test_scheduler_tick_fires_due() {
        let mut sched = TaskScheduler::new();
        // Create task with 0-second interval — immediately due
        let id = sched.add("immediate", "/now", 0);
        // Manually set next_run to now
        sched.tasks[0].next_run = std::time::Instant::now();
        let fired = sched.tick();
        assert_eq!(fired.len(), 1);
        assert_eq!(fired[0].0, id);
        assert_eq!(fired[0].1, "/now");
        assert_eq!(sched.get(id).unwrap().run_count, 1);
    }

    #[test]
    fn test_scheduler_disabled_task_not_fired() {
        let mut sched = TaskScheduler::new();
        sched.add("test", "/test", 0);
        sched.tasks[0].next_run = std::time::Instant::now();
        sched.disable(1);
        let fired = sched.tick();
        assert!(fired.is_empty());
    }

    #[test]
    fn test_scheduler_due_tasks_query() {
        let mut sched = TaskScheduler::new();
        sched.add("a", "/a", 0);
        sched.add("b", "/b", 99999);
        sched.tasks[0].next_run = std::time::Instant::now();
        let due = sched.due_tasks();
        assert_eq!(due.len(), 1);
        assert_eq!(due[0].name, "a");
    }

