    #[test]
    fn test_namespace_create_and_put_get() {
        let mut ns = MemoryNamespace::new("shared", "coder");
        ns.put("key1", "value1");
        ns.put("key2", "value2");
        assert_eq!(ns.get("key1"), Some("value1"));
        assert_eq!(ns.get("key2"), Some("value2"));
        assert_eq!(ns.get("key3"), None);
        assert_eq!(ns.len(), 2);
    }

    #[test]
    fn test_namespace_put_updates() {
        let mut ns = MemoryNamespace::new("ns", "owner");
        ns.put("k", "v1");
        ns.put("k", "v2");
        assert_eq!(ns.get("k"), Some("v2"));
        assert_eq!(ns.len(), 1); // no duplicate
    }

    #[test]
    fn test_namespace_access_control() {
        let mut ns = MemoryNamespace::new("secret", "admin");
        assert!(ns.can_access("admin"));
        assert!(!ns.can_access("viewer"));
        ns.grant("viewer");
        assert!(ns.can_access("viewer"));
        ns.revoke("viewer");
        assert!(!ns.can_access("viewer"));
    }

    #[test]
    fn test_namespace_grant_no_duplicates() {
        let mut ns = MemoryNamespace::new("ns", "o");
        ns.grant("a");
        ns.grant("a");
        assert_eq!(ns.granted.len(), 1);
    }

    #[test]
    fn test_namespace_registry_isolation() {
        let mut reg = NamespaceRegistry::new();
        reg.create("ns1", "a1");
        reg.create("ns2", "a2");
        reg.get_mut("ns1").unwrap().grant("a2");

        // a2 can access ns1 (granted) and ns2 (owner)
        let accessible = reg.accessible_by("a2");
        assert_eq!(accessible.len(), 2);

        // Isolate a2 — now only sees own namespaces
        reg.isolate_agent("a2");
        let accessible = reg.accessible_by("a2");
        assert_eq!(accessible.len(), 1);
        assert!(accessible.contains(&"ns2"));

        reg.unisolate_agent("a2");
        assert_eq!(reg.accessible_by("a2").len(), 2);
    }

    #[test]
    fn test_namespace_keys() {
        let mut ns = MemoryNamespace::new("ns", "o");
        ns.put("a", "1");
        ns.put("b", "2");
        let keys = ns.keys();
        assert_eq!(keys.len(), 2);
        assert!(keys.contains(&"a"));
        assert!(keys.contains(&"b"));
    }

