    // ─── Round 11: Backpressure Tests ───────────────────────────

    #[test]
    fn test_token_bucket_acquire_and_deplete() {
        let mut tb = TokenBucket::new("test", 3, 0);
        assert!(tb.acquire());
        assert!(tb.acquire());
        assert!(tb.acquire());
        assert!(!tb.acquire()); // depleted
        assert_eq!(tb.total_acquired, 3);
        assert_eq!(tb.total_rejected, 1);
    }

    #[test]
    fn test_token_bucket_release() {
        let mut tb = TokenBucket::new("test", 2, 0);
        tb.acquire();
        tb.acquire();
        assert!(!tb.acquire()); // depleted
        tb.release();
        assert!(tb.acquire()); // one token returned
    }

    #[test]
    fn test_token_bucket_acquire_n() {
        let mut tb = TokenBucket::new("test", 10, 0);
        assert!(tb.acquire_n(5));
        assert_eq!(tb.tokens, 5);
        assert!(!tb.acquire_n(6)); // not enough
        assert!(tb.acquire_n(5)); // exact fit
    }

    #[test]
    fn test_token_bucket_utilization() {
        let mut tb = TokenBucket::new("test", 10, 0);
        assert_eq!(tb.utilization(), 0.0);
        tb.acquire_n(5);
        assert!((tb.utilization() - 0.5).abs() < 0.01);
        tb.acquire_n(5);
        assert!((tb.utilization() - 1.0).abs() < 0.01);
    }

    #[test]
    fn test_token_bucket_release_capped() {
        let mut tb = TokenBucket::new("test", 5, 0);
        tb.release(); // already at capacity
        assert_eq!(tb.tokens, 5); // can't exceed capacity
    }

    #[test]
    fn test_token_bucket_registry() {
        let mut reg = TokenBucketRegistry::new();
        reg.create("api", 100, 10);
        reg.create("db", 50, 5);
        assert_eq!(reg.list().len(), 2);
        assert!(reg.get_mut("api").unwrap().acquire());
    }

