    #[test]
    fn test_dedup_first_is_new() {
        let mut w = DedupWindow::new("events", 60);
        assert!(!w.check("hash1")); // first time = not duplicate
        assert_eq!(w.total_checked, 1);
        assert_eq!(w.total_deduped, 0);
    }

    #[test]
    fn test_dedup_second_is_duplicate() {
        let mut w = DedupWindow::new("events", 60);
        w.check("hash1");
        assert!(w.check("hash1")); // duplicate
        assert_eq!(w.total_deduped, 1);
    }

    #[test]
    fn test_dedup_different_hashes() {
        let mut w = DedupWindow::new("events", 60);
        assert!(!w.check("a"));
        assert!(!w.check("b"));
        assert!(!w.check("c"));
        assert_eq!(w.unique_count(), 3);
    }

    #[test]
    fn test_dedup_registry() {
        let mut reg = DedupRegistry::new();
        reg.create("t1", 60);
        reg.create("t2", 120);
        assert_eq!(reg.list().len(), 2);
        assert_eq!(reg.check("t1", "h1"), Some(false)); // new
        assert_eq!(reg.check("t1", "h1"), Some(true));  // dup
        assert_eq!(reg.check("nonexistent", "h"), None);
    }

    // ─── Round 12: Retry Policy Tests ───────────────────────────

    #[test]
    fn test_retry_fixed_delay() {
        let p = RetryPolicy::new("test", RetryStrategy::Fixed(1000), 3);
        assert_eq!(p.delay_for_attempt(1), 1000);
        assert_eq!(p.delay_for_attempt(2), 1000);
        assert_eq!(p.delay_for_attempt(3), 1000);
    }

    #[test]
    fn test_retry_exponential_delay() {
        let p = RetryPolicy::new("test", RetryStrategy::Exponential(500), 5);
        assert_eq!(p.delay_for_attempt(1), 500);
        assert_eq!(p.delay_for_attempt(2), 1000);
        assert_eq!(p.delay_for_attempt(3), 2000);
    }

    #[test]
    fn test_retry_jitter_delay() {
        let p = RetryPolicy::new("test", RetryStrategy::ExponentialJitter(500), 3);
        let d1 = p.delay_for_attempt(1);
        let d2 = p.delay_for_attempt(2);
        assert!(d1 > 0);
        assert!(d2 > d1); // increases with attempt
    }

    #[test]
    fn test_retry_success_rate() {
        let mut p = RetryPolicy::new("test", RetryStrategy::Fixed(100), 3);
        p.record_success();
        p.record_success();
        p.record_failure();
        assert!((p.success_rate() - 0.6667).abs() < 0.01);
    }

    #[test]
    fn test_retry_manager() {
        let mut rm = RetryManager::new();
        rm.create("api", RetryStrategy::Exponential(500), 5);
        rm.create("db", RetryStrategy::Fixed(2000), 3);
        assert_eq!(rm.list().len(), 2);
        assert!(rm.get("api").is_some());
    }

