    // ─── Round 13: Priority Queue Tests ─────────────────────────

    #[test]
    fn test_pqueue_push_ordered() {
        let mut pq = TaskPriorityQueue::new();
        pq.push(1, "low");
        pq.push(10, "high");
        pq.push(5, "medium");
        let top = pq.peek().unwrap();
        assert_eq!(top.priority, 10);
        assert_eq!(top.description, "high");
    }

    #[test]
    fn test_pqueue_pop() {
        let mut pq = TaskPriorityQueue::new();
        pq.push(1, "low");
        pq.push(10, "high");
        let t = pq.pop().unwrap();
        assert_eq!(t.priority, 10);
        assert_eq!(pq.len(), 1);
        let t2 = pq.pop().unwrap();
        assert_eq!(t2.priority, 1);
        assert!(pq.is_empty());
    }

    #[test]
    fn test_pqueue_pop_empty() {
        let mut pq = TaskPriorityQueue::new();
        assert!(pq.pop().is_none());
    }

    #[test]
    fn test_pqueue_remove() {
        let mut pq = TaskPriorityQueue::new();
        let id = pq.push(5, "task");
        assert!(pq.remove(id));
        assert!(pq.is_empty());
        assert!(!pq.remove(999));
    }

    #[test]
    fn test_pqueue_age() {
        let mut pq = TaskPriorityQueue::new();
        pq.age_threshold_secs = 0; // immediate aging
        pq.push(1, "old task");
        let promoted = pq.age();
        assert_eq!(promoted, 1);
        assert_eq!(pq.peek().unwrap().priority, 2); // promoted by 1
        assert_eq!(pq.peek().unwrap().age_promotions, 1);
    }

    #[test]
    fn test_pqueue_age_reorders() {
        let mut pq = TaskPriorityQueue::new();
        pq.age_threshold_secs = 0;
        pq.age_increment = 5;
        pq.push(1, "will age");
        pq.push(3, "was higher");
        pq.age();
        // After aging: "will age" is now 6, "was higher" is now 8
        assert_eq!(pq.peek().unwrap().description, "was higher");
    }

