    // ─── Round 14: Gossip Protocol ──────────────────────────────────

    #[test]
    fn test_gossip_seed_and_get_state() {
        let mut g = GossipProtocol::new();
        g.seed("node-a", "status", "alive");
        let state = g.get_state("node-a").unwrap();
        assert_eq!(state.data.get("status").unwrap(), "alive");
        assert_eq!(state.version, 1);
    }

    #[test]
    fn test_gossip_spread_converges() {
        let mut g = GossipProtocol::new();
        g.seed("node-a", "key1", "val1");
        g.seed("node-b", "key2", "val2");
        assert!(!g.converged());
        g.spread();
        assert!(g.converged());
    }

