    // ─── Round 15: Distributed Lock Manager ─────────────────────────

    #[test]
    fn test_dist_lock_acquire_release() {
        let mut mgr = DistLockManager::new();
        mgr.create("db-write", 60);
        assert_eq!(mgr.acquire("db-write", "agent-a").unwrap(), true);
        assert_eq!(mgr.acquire("db-write", "agent-b").unwrap(), false); // queued
        assert_eq!(mgr.release("db-write", "agent-a").unwrap(), true);
        // agent-b should now own it (promoted from wait queue)
        let lock = mgr.locks.get("db-write").unwrap();
        assert_eq!(lock.owner.as_deref(), Some("agent-b"));
    }

    #[test]
    fn test_dist_lock_reentrant() {
        let mut mgr = DistLockManager::new();
        mgr.create("x", 60);
        mgr.acquire("x", "a").unwrap();
        assert_eq!(mgr.acquire("x", "a").unwrap(), true); // re-entrant
    }

    #[test]
    fn test_dist_lock_deadlock_detection() {
        let mut mgr = DistLockManager::new();
        mgr.create("lock1", 60);
        mgr.create("lock2", 60);
        // a holds lock1, wants lock2
        mgr.acquire("lock1", "a").unwrap();
        // b holds lock2, wants lock1
        mgr.acquire("lock2", "b").unwrap();
        mgr.acquire("lock2", "a").unwrap(); // a waits for b
        mgr.acquire("lock1", "b").unwrap(); // b waits for a → cycle
        let cycles = mgr.detect_deadlock();
        assert!(!cycles.is_empty());
    }

    #[test]
    fn test_dist_lock_not_found() {
        let mut mgr = DistLockManager::new();
        assert!(mgr.acquire("missing", "a").is_err());
    }

    #[test]
    fn test_dist_lock_wrong_owner_release() {
        let mut mgr = DistLockManager::new();
        mgr.create("l", 60);
        mgr.acquire("l", "a").unwrap();
        assert_eq!(mgr.release("l", "b").unwrap(), false); // b doesn't own it
    }

