    fn test_rate_limiter_stats() {
        let mut rl = RateLimiterSuite::new();
        rl.add_rule("a", "op", RateLimitAlgo::SlidingWindow, 1, 60, 0);
        rl.check("a", "op"); // allowed
        rl.check("a", "op"); // denied
        let stats = rl.stats();
        assert_eq!(stats.len(), 1);
        assert_eq!(stats[0].3, 1); // allowed
        assert_eq!(stats[0].4, 1); // denied
    }

    #[test]
    fn test_rate_limiter_burst() {
        let mut rl = RateLimiterSuite::new();
        rl.add_rule("a", "op", RateLimitAlgo::SlidingWindow, 2, 60, 3); // 2 + 3 burst = 5
        for _ in 0..5 { assert!(rl.check("a", "op")); }
        assert!(!rl.check("a", "op")); // 6th denied
    }

