    #[test]
    fn test_workflow_advance_to_completion() {
        let mut wf = OrchestratedWf::new("test");
        wf.add_step(WfStep::new("s1", WfStepKind::Action));
        wf.add_step(WfStep::new("s2", WfStepKind::Action));
        wf.start();
        let next = wf.complete_current();
        assert_eq!(next, Some("s2"));
        wf.complete_current();
        assert_eq!(wf.status, WfStatus::Completed);
        assert!((wf.progress() - 1.0).abs() < 0.01);
    }

    #[test]
    fn test_workflow_fail_and_retry() {
        let mut wf = OrchestratedWf::new("test");
        wf.add_step(WfStep::new("s1", WfStepKind::Action));
        wf.start();
        assert!(wf.fail_current()); // retry 1
        assert!(wf.fail_current()); // retry 2
        assert!(wf.fail_current()); // retry 3
        assert!(!wf.fail_current()); // exhausted → FAILED
        assert_eq!(wf.status, WfStatus::Failed);
    }

    #[test]
    fn test_workflow_compensation() {
        let mut wf = OrchestratedWf::new("test");
        wf.add_step(WfStep::new("create-db", WfStepKind::Action).with_compensation("drop-db"));
        wf.add_step(WfStep::new("migrate", WfStepKind::Action).with_compensation("rollback-migrate"));
        wf.add_step(WfStep::new("deploy", WfStepKind::Action));
        wf.start();
        wf.complete_current(); // create-db done
        wf.complete_current(); // migrate done
        // deploy fails
        let comps = wf.compensate();
        assert_eq!(comps, vec!["rollback-migrate", "drop-db"]);
    }

    #[test]
    fn test_workflow_orchestrator_list() {
        let mut wo = WorkflowOrchestrator::new();
        wo.create("wf1");
        wo.create("wf2");
        assert_eq!(wo.list().len(), 2);
        assert!(!wo.create("wf1")); // duplicate
    }

