    #[test]
    fn test_adaptive_register_and_complete() {
        let mut as_ = AdaptiveScheduler::new();
        as_.register("fast");
        as_.record_completion("fast", 50);
        as_.record_completion("fast", 60);
        let agents = as_.list();
        assert_eq!(agents.len(), 1);
        let (_, _, avg, tasks, _) = agents[0];
        assert_eq!(tasks, 2);
        assert!((avg - 55.0).abs() < 0.01);
    }

    #[test]
    fn test_adaptive_select_best() {
        let mut as_ = AdaptiveScheduler::new();
        as_.register("slow");
        as_.register("fast");
        as_.record_completion("slow", 5000);
        as_.record_completion("fast", 100);
        let best = as_.select_best(&["slow", "fast"]).unwrap();
        assert_eq!(best, "fast");
    }

    #[test]
    fn test_adaptive_error_lowers_weight() {
        let mut as_ = AdaptiveScheduler::new();
        as_.register("err");
        as_.record_completion("err", 100);
        let w1 = as_.agents.get("err").unwrap().weight;
        as_.record_error("err");
        let w2 = as_.agents.get("err").unwrap().weight;
        assert!(w2 < w1);
    }

    #[test]
    fn test_adaptive_ranked() {
        let mut as_ = AdaptiveScheduler::new();
        as_.register("a");
        as_.register("b");
        as_.record_completion("a", 500);   // speed_factor = 1000/500 = 2.0 → clamped 1.0
        as_.record_completion("b", 5000);  // speed_factor = 1000/5000 = 0.2
        let ranked = as_.ranked();
        assert_eq!(ranked[0].0, "a"); // faster = ranked higher
    }

    #[test]
    fn test_adaptive_rebalance() {
        let mut as_ = AdaptiveScheduler::new();
        as_.register("a");
        as_.register("b");
        as_.record_completion("a", 100);
        as_.record_completion("b", 100);
        as_.rebalance();
        let total: f64 = as_.agents.values().map(|p| p.weight).sum();
        assert!((total - 1.0).abs() < 0.01);
    }

