    #[test]
    fn test_cb_closed_allows() {
        let mut cbr = CbRegistry::new();
        cbr.create("api", 3, 2, 30);
        assert_eq!(cbr.allow("api"), Some(true));
    }

    #[test]
    fn test_cb_trips_after_failures() {
        let mut cbr = CbRegistry::new();
        cbr.create("db", 3, 2, 30);
        cbr.failure("db");
        cbr.failure("db");
        cbr.failure("db"); // trips
        assert_eq!(cbr.state("db"), Some(&CbState::Open));
        assert_eq!(cbr.allow("db"), Some(false)); // blocked
    }

    #[test]
    fn test_cb_success_resets_failures() {
        let mut cbr = CbRegistry::new();
        cbr.create("x", 3, 1, 30);
        cbr.failure("x");
        cbr.failure("x");
        cbr.success("x"); // resets count
        cbr.failure("x");
        // Only 1 failure after reset, not tripped
        assert_eq!(cbr.state("x"), Some(&CbState::Closed));
    }

    #[test]
    fn test_cb_open_breakers() {
        let mut cbr = CbRegistry::new();
        cbr.create("a", 1, 1, 30);
        cbr.create("b", 1, 1, 30);
        cbr.failure("a"); // trips
        assert_eq!(cbr.open_breakers().len(), 1);
    }

    #[test]
    fn test_cb_total_trips() {
        let mut cbr = CbRegistry::new();
        cbr.create("x", 1, 1, 0); // 0 cooldown for immediate half-open
        cbr.failure("x"); // trip 1
        cbr.allow("x"); // → half-open (cooldown=0)
        cbr.failure("x"); // trip 2
        let entry = cbr.breakers.get("x").unwrap();
        assert_eq!(entry.total_trips, 2);
    }

