    // NegotiationManager tests

    #[test]
    fn test_negotiation_propose() {
        let mut nm = NegotiationManager::new();
        let id = nm.propose("price", "alice", "bob", 100.0, 5.0, 300);
        assert_eq!(id, 1);
        let n = nm.get(id).unwrap();
        assert_eq!(n.topic, "price");
        assert_eq!(n.initiator, "alice");
        assert_eq!(n.responder, "bob");
        assert_eq!(n.status, NegotiationStatus::Proposed);
        assert_eq!(n.offers.len(), 1);
        assert_eq!(n.offers[0].value, 100.0);
    }

    #[test]
    fn test_negotiation_counter() {
        let mut nm = NegotiationManager::new();
        let id = nm.propose("price", "alice", "bob", 100.0, 5.0, 300);
        assert!(nm.counter(id, "bob", 90.0));
        let n = nm.get(id).unwrap();
        assert_eq!(n.offers.len(), 2);
        assert_eq!(n.status, NegotiationStatus::CounterOffered);
    }

    #[test]
    fn test_negotiation_auto_accept() {
        let mut nm = NegotiationManager::new();
        let id = nm.propose("price", "alice", "bob", 100.0, 5.0, 300);
        // Counter within threshold (|100-97| = 3 <= 5)
        nm.counter(id, "bob", 97.0);
        let n = nm.get(id).unwrap();
        assert_eq!(n.status, NegotiationStatus::Accepted);
    }

    #[test]
    fn test_negotiation_accept_reject() {
        let mut nm = NegotiationManager::new();
        let id1 = nm.propose("a", "x", "y", 50.0, 1.0, 300);
        let id2 = nm.propose("b", "x", "y", 50.0, 1.0, 300);
        assert!(nm.accept(id1));
        assert!(nm.reject(id2));
        assert_eq!(nm.get(id1).unwrap().status, NegotiationStatus::Accepted);
        assert_eq!(nm.get(id2).unwrap().status, NegotiationStatus::Rejected);
    }

    #[test]
    fn test_negotiation_best_offer() {
        let mut nm = NegotiationManager::new();
        let id = nm.propose("price", "alice", "bob", 100.0, 0.1, 300);
        nm.counter(id, "bob", 80.0);
        let best = nm.best_offer(id).unwrap();
        assert_eq!(best.value, 80.0);
        assert_eq!(best.by, "bob");
    }

    #[test]
    fn test_negotiation_active() {
        let mut nm = NegotiationManager::new();
        nm.propose("a", "x", "y", 10.0, 1.0, 300);
        nm.propose("b", "x", "y", 20.0, 1.0, 300);
        let id3 = nm.propose("c", "x", "y", 30.0, 1.0, 300);
        nm.accept(id3);
        assert_eq!(nm.active().len(), 2);
        assert_eq!(nm.list().len(), 3);
    }

    // SequenceCorrelator tests

    #[test]
    fn test_seq_correlator_add_rule() {
        let mut sc = SequenceCorrelator::new(1000);
        sc.add_rule("test", vec!["a".into(), "b".into()], 60, "alert", 0);
        assert_eq!(sc.list_rules().len(), 1);
        assert_eq!(sc.list_rules()[0].name, "test");
    }

    #[test]
    fn test_seq_correlator_ingest_triggers() {
        let mut sc = SequenceCorrelator::new(1000);
        sc.add_rule("ab", vec!["a".into(), "b".into()], 60, "fire", 0);
        let t1 = sc.ingest("a");
        assert!(t1.is_empty());
        let t2 = sc.ingest("b");
        assert_eq!(t2.len(), 1);
        assert_eq!(t2[0].0, "ab");
        assert_eq!(t2[0].1, "fire");
    }

    #[test]
    fn test_seq_correlator_no_match() {
        let mut sc = SequenceCorrelator::new(1000);
        sc.add_rule("ab", vec!["a".into(), "b".into()], 60, "fire", 0);
        let t = sc.ingest("b");
        assert!(t.is_empty());
    }

    #[test]
    fn test_seq_correlator_suppression() {
        let mut sc = SequenceCorrelator::new(1000);
        sc.add_rule("ab", vec!["a".into(), "b".into()], 60, "fire", 9999);
        sc.ingest("a");
        let t1 = sc.ingest("b");
        assert_eq!(t1.len(), 1); // first match
        // After first match, buffer=[a,b]. ingest("a") → buffer=[a,b,a], sequence a,b still matches → suppressed
        sc.ingest("a");
        let t2 = sc.ingest("b");
        assert!(t2.is_empty()); // suppressed
        assert_eq!(sc.list_rules()[0].suppressed, 2); // both ingest("a") and ingest("b") re-matched and got suppressed
    }

    #[test]
    fn test_seq_correlator_event_count() {
        let mut sc = SequenceCorrelator::new(5);
        for i in 0..7 {
            sc.ingest(&format!("e{}", i));
        }
        assert_eq!(sc.event_count(), 5); // capped at max_events
    }

