    #[test]
    fn test_skill_tree_create_add() {
        let mut reg = SkillTreeRegistry::new();
        reg.create("agent1");
        let tree = reg.get_mut("agent1").unwrap();
        tree.add_skill(SkillNode::new("coding", "Code ability", 5, 100, 0.0));
        assert_eq!(tree.list().len(), 1);
        let (name, level, max_l, unlocked, _) = &tree.list()[0];
        assert_eq!(*name, "coding");
        assert_eq!(*level, 0);
        assert_eq!(*max_l, 5);
        assert!(*unlocked); // no prereqs = auto-unlock
    }

    #[test]
    fn test_skill_tree_grant_xp_levelup() {
        let mut reg = SkillTreeRegistry::new();
        reg.create("agent1");
        let tree = reg.get_mut("agent1").unwrap();
        tree.add_skill(SkillNode::new("coding", "Code", 5, 100, 0.0));
        assert_eq!(tree.grant_xp("coding", 50), Some(false)); // no level up
        assert_eq!(tree.grant_xp("coding", 60), Some(true));  // level up at 110 xp (level 1)
        let s = tree.get("coding").unwrap();
        assert_eq!(s.level, 1);
        assert_eq!(s.xp, 110);
    }

    #[test]
    fn test_skill_tree_prerequisites() {
        let mut reg = SkillTreeRegistry::new();
        reg.create("agent1");
        let tree = reg.get_mut("agent1").unwrap();
        tree.add_skill(SkillNode::new("basic", "Base skill", 3, 100, 0.0));
        tree.add_skill(SkillNode::new("advanced", "Adv skill", 5, 200, 0.0).with_prereqs(vec!["basic".into()]));
        // advanced should be locked
        assert!(!tree.get("advanced").unwrap().unlocked);
        assert_eq!(tree.grant_xp("advanced", 50), Some(false)); // returns false — skill locked, no xp added
        // level up basic
        tree.grant_xp("basic", 100); // level 1
        let unlocked = tree.check_unlocks();
        assert_eq!(unlocked, vec!["advanced"]);
        assert!(tree.get("advanced").unwrap().unlocked);
    }

    #[test]
    fn test_skill_tree_progress() {
        let mut reg = SkillTreeRegistry::new();
        reg.create("a");
        let tree = reg.get_mut("a").unwrap();
        tree.add_skill(SkillNode::new("s", "S", 4, 100, 0.0));
        tree.grant_xp("s", 200); // level 2 of 4
        let s = tree.get("s").unwrap();
        assert_eq!(s.progress_pct(), 50.0);
    }

