    // ServiceMesh tests

    #[test]
    fn test_mesh_register_resolve() {
        let mut mesh = ServiceMesh::new();
        mesh.register("llm", "agent1", 1.0, 3, 5);
        let route = mesh.resolve("llm").unwrap();
        assert_eq!(route.target_agent, "agent1");
        assert_eq!(route.weight, 1.0);
    }

    #[test]
    fn test_mesh_weighted_resolution() {
        let mut mesh = ServiceMesh::new();
        mesh.register("llm", "slow", 0.3, 3, 5);
        mesh.register("llm", "fast", 0.9, 3, 5);
        let route = mesh.resolve("llm").unwrap();
        assert_eq!(route.target_agent, "fast"); // highest weight
    }

    #[test]
    fn test_mesh_circuit_breaker() {
        let mut mesh = ServiceMesh::new();
        mesh.register("svc", "target", 1.0, 3, 3); // threshold=3
        mesh.record_failure("svc", "target");
        mesh.record_failure("svc", "target");
        assert!(mesh.resolve("svc").is_some()); // still available
        mesh.record_failure("svc", "target"); // 3rd failure trips circuit
        assert!(mesh.resolve("svc").is_none()); // circuit open
    }

    #[test]
    fn test_mesh_reset_circuit() {
        let mut mesh = ServiceMesh::new();
        mesh.register("svc", "target", 1.0, 3, 2);
        mesh.record_failure("svc", "target");
        mesh.record_failure("svc", "target");
        assert!(mesh.resolve("svc").is_none());
        mesh.reset_circuit("svc", "target");
        assert!(mesh.resolve("svc").is_some());
    }

    #[test]
    fn test_mesh_success_rate() {
        let mut mesh = ServiceMesh::new();
        mesh.register("svc", "t", 1.0, 3, 10);
        mesh.record_success("svc", "t");
        mesh.record_success("svc", "t");
        mesh.record_failure("svc", "t");
        let r = mesh.routes_for("svc");
        let rate = r[0].success_rate();
        assert!((rate - 2.0/3.0).abs() < 0.01);
    }

    // OtelTracer tests

    #[test]
    fn test_otel_start_end_span() {
        let mut tracer = OtelTracer::new();
        let id = tracer.start_span("trace1", None, "process", "agent-svc");
        assert_eq!(id, 1);
        assert_eq!(tracer.active_spans().len(), 1);
        tracer.end_span(id, SpanStatus::Ok);
        assert_eq!(tracer.active_spans().len(), 0);
    }

    #[test]
    fn test_otel_parent_child() {
        let mut tracer = OtelTracer::new();
        let parent = tracer.start_span("t", None, "root", "svc");
        let child = tracer.start_span("t", Some(parent), "child-op", "svc");
        let children = tracer.children(parent);
        assert_eq!(children.len(), 1);
        assert_eq!(children[0].span_id, child);
    }

    #[test]
    fn test_otel_trace_lookup() {
        let mut tracer = OtelTracer::new();
        tracer.start_span("t1", None, "a", "svc");
        tracer.start_span("t1", None, "b", "svc");
        tracer.start_span("t2", None, "c", "svc");
        assert_eq!(tracer.trace("t1").len(), 2);
        assert_eq!(tracer.trace("t2").len(), 1);
    }

    #[test]
    fn test_otel_waterfall() {
        let mut tracer = OtelTracer::new();
        let root = tracer.start_span("t", None, "root", "api");
        let _child = tracer.start_span("t", Some(root), "db-query", "db");
        tracer.end_span(root, SpanStatus::Ok);
        let wf = tracer.waterfall("t");
        assert_eq!(wf.len(), 2);
        assert_eq!(wf[0].0, 0); // root at depth 0
        assert_eq!(wf[1].0, 1); // child at depth 1
    }

    #[test]
    fn test_otel_tag_span() {
        let mut tracer = OtelTracer::new();
        let id = tracer.start_span("t", None, "op", "svc");
        tracer.tag_span(id, "http.method", "GET");
        let spans = tracer.trace("t");
        assert_eq!(spans[0].tags.get("http.method").unwrap(), "GET");
    }

