    #[test]
    fn test_rbac_create_role_grant_check() {
        let mut rbac = RbacSystem::new();
        rbac.create_role("admin", vec![]);
        rbac.grant_permission("admin", "*", Permission::Admin);
        rbac.assign_role("agent1", "admin");
        assert!(rbac.check("agent1", "llm", &Permission::Execute));
    }

    #[test]
    fn test_rbac_deny_without_role() {
        let mut rbac = RbacSystem::new();
        rbac.create_role("viewer", vec![]);
        rbac.grant_permission("viewer", "logs", Permission::Read);
        // agent2 has no role
        assert!(!rbac.check("agent2", "logs", &Permission::Read));
    }

    #[test]
    fn test_rbac_inheritance() {
        let mut rbac = RbacSystem::new();
        rbac.create_role("viewer", vec![]);
        rbac.grant_permission("viewer", "logs", Permission::Read);
        rbac.create_role("operator", vec!["viewer".to_string()]);
        rbac.grant_permission("operator", "tasks", Permission::Execute);
        rbac.assign_role("agent1", "operator");
        assert!(rbac.check("agent1", "logs", &Permission::Read)); // inherited
        assert!(rbac.check("agent1", "tasks", &Permission::Execute)); // direct
    }

    #[test]
    fn test_rbac_audit_log() {
        let mut rbac = RbacSystem::new();
        rbac.create_role("viewer", vec![]);
        rbac.grant_permission("viewer", "data", Permission::Read);
        rbac.assign_role("a", "viewer");
        rbac.check("a", "data", &Permission::Read);
        rbac.check("a", "data", &Permission::Write);
        let log = rbac.audit_log(10);
        assert_eq!(log.len(), 2);
        assert!(log[0].granted);
        assert!(!log[1].granted);
    }

    #[test]
    fn test_rbac_revoke() {
        let mut rbac = RbacSystem::new();
        rbac.create_role("admin", vec![]);
        rbac.grant_permission("admin", "*", Permission::Admin);
        rbac.assign_role("a", "admin");
        assert!(rbac.check("a", "x", &Permission::Write));
        rbac.revoke_role("a", "admin");
        assert!(!rbac.check("a", "x", &Permission::Write));
    }

