    // SagaCoordinator tests

    #[test]
    fn test_saga_create_advance_complete() {
        let mut sc = SagaCoordinator::new();
        let id = sc.create("order", vec![
            ("reserve".into(), "unreserve".into(), 60),
            ("charge".into(), "refund".into(), 60),
        ]);
        assert_eq!(id, 1);
        let step = sc.advance(id).unwrap();
        assert_eq!(step, "reserve");
        assert!(sc.complete_step(id));
        let saga = sc.get(id).unwrap();
        assert_eq!(saga.current_step, 1);
        assert_eq!(saga.status, SagaStatus::Running);
    }

    #[test]
    fn test_saga_complete_all() {
        let mut sc = SagaCoordinator::new();
        let id = sc.create("simple", vec![("s1".into(), "c1".into(), 60)]);
        sc.advance(id);
        sc.complete_step(id);
        assert_eq!(sc.get(id).unwrap().status, SagaStatus::Completed);
    }

    #[test]
    fn test_saga_fail_and_compensate() {
        let mut sc = SagaCoordinator::new();
        let id = sc.create("order", vec![
            ("reserve".into(), "unreserve".into(), 60),
            ("charge".into(), "refund".into(), 60),
            ("ship".into(), "cancel-ship".into(), 60),
        ]);
        sc.advance(id); sc.complete_step(id); // reserve done
        sc.advance(id); sc.complete_step(id); // charge done
        sc.advance(id); // ship running
        let comps = sc.fail_step(id); // ship fails
        assert_eq!(comps, vec!["refund", "unreserve"]); // reverse order
        assert_eq!(sc.get(id).unwrap().status, SagaStatus::Compensating);
        sc.complete_compensation(id);
        assert_eq!(sc.get(id).unwrap().status, SagaStatus::Failed);
    }

