    // CommProtocol tests

    #[test]
    fn test_comm_send_inbox() {
        let mut cp = CommProtocol::new();
        let id = cp.send(MsgKind::Request, "a", vec!["b".into()], "hello", MsgPriority::Normal, None);
        assert_eq!(id, 1);
        let inbox = cp.inbox("b");
        assert_eq!(inbox.len(), 1);
        assert_eq!(inbox[0].payload, "hello");
    }

    #[test]
    fn test_comm_broadcast() {
        let mut cp = CommProtocol::new();
        cp.send(MsgKind::Broadcast, "a", vec![], "news", MsgPriority::Normal, None);
        // Empty `to` means broadcast — visible to all
        assert_eq!(cp.inbox("anyone").len(), 1);
    }

    #[test]
    fn test_comm_priority_ordering() {
        let mut cp = CommProtocol::new();
        cp.send(MsgKind::Request, "a", vec!["b".into()], "low", MsgPriority::Low, None);
        cp.send(MsgKind::Request, "a", vec!["b".into()], "crit", MsgPriority::Critical, None);
        cp.send(MsgKind::Request, "a", vec!["b".into()], "norm", MsgPriority::Normal, None);
        let inbox = cp.inbox("b");
        assert_eq!(inbox[0].payload, "crit");   // highest priority first
        assert_eq!(inbox[1].payload, "norm");
        assert_eq!(inbox[2].payload, "low");
    }

    #[test]
    fn test_comm_deliver_removes_from_inbox() {
        let mut cp = CommProtocol::new();
        let id = cp.send(MsgKind::Request, "a", vec!["b".into()], "msg", MsgPriority::Normal, None);
        assert!(cp.deliver(id));
        assert_eq!(cp.inbox("b").len(), 0); // delivered = no longer in inbox
    }

    #[test]
    fn test_comm_dead_letter() {
        let mut cp = CommProtocol::new();
        let id = cp.send(MsgKind::Request, "a", vec!["b".into()], "fail", MsgPriority::Normal, None);
        cp.move_to_dead_letter(id);
        assert_eq!(cp.dead_letter_count(), 1);
        assert_eq!(cp.inbox("b").len(), 0);
    }

