    fn test_semver_breaking() {
        let mut sr = SemverRegistry::new();
        sr.register("api", 2, 0, 0);
        sr.add_breaking("api", "removed legacy endpoint");
        let e = sr.latest("api").unwrap();
        assert_eq!(e.breaking_changes.len(), 1);
    }

    // SessionManager tests

    #[test]
    fn test_session_create_suspend_resume() {
        let mut sm = SessionManager::new();
        let id = sm.create("agent1", 3600);
        assert_eq!(sm.get(id).unwrap().status, SessionStatus::Active);
        sm.suspend(id);
        assert_eq!(sm.get(id).unwrap().status, SessionStatus::Suspended);
        sm.resume(id);
        assert_eq!(sm.get(id).unwrap().status, SessionStatus::Active);
    }

    #[test]
    fn test_session_terminate() {
        let mut sm = SessionManager::new();
        let id = sm.create("a", 3600);
        sm.terminate(id);
        assert_eq!(sm.get(id).unwrap().status, SessionStatus::Terminated);
        assert!(!sm.resume(id)); // can't resume terminated
    }

    #[test]
    fn test_session_state() {
        let mut sm = SessionManager::new();
        let id = sm.create("a", 3600);
        sm.set_state(id, "mode", "turbo");
        assert_eq!(sm.get_state(id, "mode"), Some("turbo"));
        assert_eq!(sm.get_state(id, "missing"), None);
    }

    #[test]
    fn test_session_migrate() {
        let mut sm = SessionManager::new();
        let id = sm.create("a", 3600);
        sm.set_state(id, "data", "important");
        assert!(sm.migrate(id, "b"));
        assert_eq!(sm.get(id).unwrap().agent, "b");
        assert_eq!(sm.get_state(id, "data"), Some("important")); // state preserved
    }

    #[test]
    fn test_session_expire() {
        let mut sm = SessionManager::new();
        let id = sm.create("a", 0); // TTL=0 means instant expire
        let expired = sm.expire_stale();
        assert!(expired.contains(&id));
        assert_eq!(sm.get(id).unwrap().status, SessionStatus::Expired);
    }

