    // ─── Round 24 Tests: Canary Analysis ─────────────────────────────

    #[test]
    fn test_canary_create_and_record() {
        let mut ca = CanaryAnalyzer::new();
        ca.create("deploy-v2", 0.05, 1.5);
        ca.record_baseline("deploy-v2", true, 50);
        ca.record_baseline("deploy-v2", true, 60);
        ca.record_canary("deploy-v2", true, 55);
        let (b_err, c_err, b_lat, c_lat, _) = ca.summary("deploy-v2").unwrap();
        assert_eq!(b_err, 0.0);
        assert_eq!(c_err, 0.0);
        assert!((b_lat - 55.0).abs() < 0.1); // (50+60)/2 = 55.0
        assert!((c_lat - 55.0).abs() < 0.1);
    }

    #[test]
    fn test_canary_promote() {
        let mut ca = CanaryAnalyzer::new();
        ca.create("test", 0.05, 1.5);
        // Baseline: 20 requests, all success, avg 50ms
        for _ in 0..20 { ca.record_baseline("test", true, 50); }
        // Canary: 20 requests, all success, avg 52ms (within threshold)
        for _ in 0..20 { ca.record_canary("test", true, 52); }
        let verdict = ca.evaluate("test").unwrap().clone();
        assert_eq!(verdict, CanaryVerdict::Promote);
    }

    #[test]
    fn test_canary_rollback_high_error() {
        let mut ca = CanaryAnalyzer::new();
        ca.create("bad", 0.05, 1.5);
        for _ in 0..20 { ca.record_baseline("bad", true, 50); }
        // Canary: 10 success, 5 fail → error rate 33%
        for _ in 0..10 { ca.record_canary("bad", true, 50); }
        for _ in 0..5 { ca.record_canary("bad", false, 50); }
        let verdict = ca.evaluate("bad").unwrap().clone();
        assert_eq!(verdict, CanaryVerdict::Rollback);
    }

    #[test]
    fn test_canary_pending_insufficient_samples() {
        let mut ca = CanaryAnalyzer::new();
        ca.create("early", 0.05, 1.5);
        for _ in 0..5 { ca.record_canary("early", true, 50); }
        let verdict = ca.evaluate("early").unwrap().clone();
        assert_eq!(verdict, CanaryVerdict::Pending); // < 10 samples
    }

    #[test]
    fn test_canary_list() {
        let mut ca = CanaryAnalyzer::new();
        ca.create("a", 0.05, 1.5);
        ca.create("b", 0.1, 2.0);
        let list = ca.list();
        assert_eq!(list.len(), 2);
    }

