    #[test]
    fn test_mpmc_enqueue_dequeue() {
        let mut reg = MpmcQueueRegistry::new();
        reg.create("tasks", 100);
        let q = reg.get_mut("tasks").unwrap();
        assert!(q.enqueue("task-1"));
        assert!(q.enqueue("task-2"));
        assert_eq!(q.dequeue("agent-a"), Some("task-1".to_string()));
        assert_eq!(q.dequeue("agent-a"), Some("task-2".to_string()));
        assert_eq!(q.dequeue("agent-a"), None);
    }

    #[test]
    fn test_mpmc_independent_cursors() {
        let mut reg = MpmcQueueRegistry::new();
        reg.create("q", 100);
        let q = reg.get_mut("q").unwrap();
        q.enqueue("x");
        q.enqueue("y");
        // Agent A reads first item
        assert_eq!(q.dequeue("a"), Some("x".to_string()));
        // Agent B reads independently — also gets first item
        assert_eq!(q.dequeue("b"), Some("x".to_string()));
        assert_eq!(q.dequeue("b"), Some("y".to_string()));
    }

    #[test]
    fn test_mpmc_backpressure() {
        let mut reg = MpmcQueueRegistry::new();
        reg.create("small", 2);
        let q = reg.get_mut("small").unwrap();
        assert!(q.enqueue("a"));
        assert!(q.enqueue("b"));
        assert!(!q.enqueue("c")); // full
        assert!(q.is_full());
    }

    #[test]
    fn test_mpmc_batch_dequeue() {
        let mut reg = MpmcQueueRegistry::new();
        reg.create("batch", 100);
        let q = reg.get_mut("batch").unwrap();
        for i in 0..5 { q.enqueue(&format!("item-{}", i)); }
        let batch = q.batch_dequeue("reader", 3);
        assert_eq!(batch.len(), 3);
        assert_eq!(batch[0], "item-0");
        assert_eq!(q.pending_for("reader"), 2);
    }

    #[test]
    fn test_mpmc_registry_list() {
        let mut reg = MpmcQueueRegistry::new();
        reg.create("q1", 10);
        reg.create("q2", 20);
        assert_eq!(reg.list().len(), 2);
    }

