    // ─── Round 24 Tests: Config Tree ─────────────────────────────────

    #[test]
    fn test_config_tree_set_and_resolve() {
        let mut ct = ConfigTree::new();
        ct.create_node("global", "global", None);
        ct.set("global", "log_level", "info");
        let (source, val) = ct.resolve("global", "log_level").unwrap();
        assert_eq!(val, "info");
        assert_eq!(source, "global");
    }

    #[test]
    fn test_config_inheritance() {
        let mut ct = ConfigTree::new();
        ct.create_node("global", "global", None);
        ct.create_node("team-a", "team", Some("global".to_string()));
        ct.create_node("agent-1", "agent", Some("team-a".to_string()));
        ct.set("global", "timeout", "30");
        ct.set("team-a", "region", "us-east");
        // agent-1 inherits timeout from global and region from team-a
        let (src, val) = ct.resolve("agent-1", "timeout").unwrap();
        assert_eq!(val, "30");
        assert_eq!(src, "global");
        let (src, val) = ct.resolve("agent-1", "region").unwrap();
        assert_eq!(val, "us-east");
        assert_eq!(src, "team-a");
    }

    #[test]
    fn test_config_override() {
        let mut ct = ConfigTree::new();
        ct.create_node("global", "global", None);
        ct.create_node("agent-1", "agent", Some("global".to_string()));
        ct.set("global", "log_level", "info");
        ct.set("agent-1", "log_level", "debug");
        let (src, val) = ct.resolve("agent-1", "log_level").unwrap();
        assert_eq!(val, "debug");
        assert_eq!(src, "agent-1"); // override wins
    }

    #[test]
    fn test_config_effective() {
        let mut ct = ConfigTree::new();
        ct.create_node("global", "global", None);
        ct.create_node("child", "agent", Some("global".to_string()));
        ct.set("global", "a", "1");
        ct.set("global", "b", "2");
        ct.set("child", "b", "3");
        let eff = ct.effective_config("child");
        assert_eq!(eff.len(), 2);
        assert_eq!(eff["a"].0, "1"); // inherited
        assert_eq!(eff["b"].0, "3"); // overridden
    }

    #[test]
    fn test_config_diff() {
        let mut ct = ConfigTree::new();
        ct.create_node("global", "global", None);
        ct.create_node("a", "agent", Some("global".to_string()));
        ct.create_node("b", "agent", Some("global".to_string()));
        ct.set("global", "shared", "yes");
        ct.set("a", "mode", "fast");
        ct.set("b", "mode", "safe");
        let diffs = ct.diff("a", "b");
        assert_eq!(diffs.len(), 1); // only "mode" differs
        assert_eq!(diffs[0].0, "mode");
    }

