    // ─── Round 25 Tests: Gossip Protocol ─────────────────────────────

    #[test]
    fn test_gossip_update_and_state() {
        let mut g = EpidemicGossip::new("a1", 3);
        g.update("status", "healthy");
        g.update("load", "42");
        assert_eq!(g.key_count(), 2);
        let snap = g.state_snapshot();
        assert_eq!(snap["status"].0, "healthy");
        assert_eq!(snap["status"].1, 1); // version 1
    }

    #[test]
    fn test_gossip_receive_new() {
        let mut g = EpidemicGossip::new("a2", 3);
        let msg = GossipMessage { key: "temp".into(), value: "hot".into(), version: 1, origin: "a1".into(), hops: 0 };
        assert!(g.receive_gossip(msg));
        assert_eq!(g.state_snapshot()["temp"].0, "hot");
    }

    #[test]
    fn test_gossip_reject_old_version() {
        let mut g = EpidemicGossip::new("a2", 3);
        g.update("k", "v2"); // version 1
        g.update("k", "v3"); // version 2
        let old_msg = GossipMessage { key: "k".into(), value: "v1".into(), version: 1, origin: "a1".into(), hops: 0 };
        assert!(!g.receive_gossip(old_msg)); // rejected — older version
    }

    #[test]
    fn test_gossip_max_hops() {
        let mut g = EpidemicGossip::new("a1", 2);
        let msg = GossipMessage { key: "k".into(), value: "v".into(), version: 1, origin: "x".into(), hops: 2 };
        assert!(!g.receive_gossip(msg)); // hops >= max_hops, rejected
    }

    #[test]
    fn test_gossip_network_propagation() {
        let mut net = GossipNetwork::new();
        net.add_agent("a", 3);
        net.add_agent("b", 3);
        net.get_mut("a").unwrap().add_peer("b");
        net.get_mut("a").unwrap().update("key", "val");
        let updates = net.propagate_round();
        assert_eq!(updates, 1);
        assert_eq!(net.get("b").unwrap().state_snapshot()["key"].0, "val");
    }

