    #[test]
    fn test_raft_add_and_election() {
        let mut raft = RaftLiteConsensus::new();
        raft.add_node("n1");
        raft.add_node("n2");
        raft.add_node("n3");
        let term = raft.start_election("n1").unwrap();
        assert_eq!(term, 1);
        let node = raft.get("n1").unwrap();
        assert_eq!(node.role, RaftRole::Candidate);
    }

    #[test]
    fn test_raft_majority_wins() {
        let mut raft = RaftLiteConsensus::new();
        raft.add_node("a");
        raft.add_node("b");
        raft.add_node("c");
        raft.start_election("a");
        // a votes for itself, needs 1 more for majority (>3/2=1, need 2 votes)
        let won = raft.vote("b", "a").unwrap();
        assert!(won);
        assert_eq!(raft.leader(), Some("a"));
    }

    #[test]
    fn test_raft_log_append() {
        let mut raft = RaftLiteConsensus::new();
        raft.add_node("leader");
        raft.start_election("leader");
        // Force to leader for single-node cluster
        raft.get_mut("leader").unwrap().role = RaftRole::Leader;
        let idx = raft.get_mut("leader").unwrap().append_log("set x=1");
        assert_eq!(idx, 1);
        let idx2 = raft.get_mut("leader").unwrap().append_log("set y=2");
        assert_eq!(idx2, 2);
    }

    #[test]
    fn test_raft_step_down() {
        let mut raft = RaftLiteConsensus::new();
        raft.add_node("n1");
        raft.start_election("n1");
        let node = raft.get_mut("n1").unwrap();
        node.role = RaftRole::Leader;
        node.step_down(5); // higher term forces step down
        assert_eq!(node.role, RaftRole::Follower);
        assert_eq!(node.current_term, 5);
    }

    #[test]
    fn test_raft_heartbeat() {
        let mut raft = RaftLiteConsensus::new();
        raft.add_node("n1");
        raft.get_mut("n1").unwrap().heartbeat();
        raft.get_mut("n1").unwrap().heartbeat();
        assert_eq!(raft.get("n1").unwrap().heartbeat_count, 2);
    }

