    // ─── Round 26 Tests: Distributed Lock Manager ────────────────────

    #[test]
    fn test_lock_acquire_release() {
        let mut lm = NamedLockManager::new();
        assert!(lm.try_acquire("mutex-1", "agent-a", 60));
        assert!(!lm.try_acquire("mutex-1", "agent-b", 60)); // contention
        assert_eq!(lm.owner("mutex-1"), Some("agent-a"));
        lm.release("mutex-1", "agent-a");
        // b was in wait queue, now gets the lock
        assert_eq!(lm.owner("mutex-1"), Some("agent-b"));
    }

    #[test]
    fn test_lock_reentrant() {
        let mut lm = NamedLockManager::new();
        assert!(lm.try_acquire("l", "a", 60));
        assert!(lm.try_acquire("l", "a", 60)); // same owner, re-entrant
    }

    #[test]
    fn test_lock_deadlock_detection() {
        let mut lm = NamedLockManager::new();
        // A holds lock1, B holds lock2
        lm.try_acquire("lock1", "a", 60);
        lm.try_acquire("lock2", "b", 60);
        // A waits for lock2 (held by B)
        lm.try_acquire("lock2", "a", 60);
        // B waits for lock1 (held by A)
        lm.try_acquire("lock1", "b", 60);
        assert!(lm.has_deadlock("a", "b"));
    }

    #[test]
    fn test_lock_no_deadlock() {
        let mut lm = NamedLockManager::new();
        lm.try_acquire("l1", "a", 60);
        assert!(!lm.has_deadlock("a", "b"));
    }

    #[test]
    fn test_lock_contention_count() {
        let mut lm = NamedLockManager::new();
        lm.try_acquire("x", "a", 60);
        lm.try_acquire("x", "b", 60); // contention
        lm.try_acquire("x", "c", 60); // contention
        assert_eq!(lm.contention_total(), 2);
    }

