    #[test]
    fn test_replay_record_and_next() {
        let mut er = ChronologicalReplay::new();
        er.record("a1", "action", "did thing 1");
        er.record("a2", "query", "asked something");
        assert_eq!(er.event_count(), 2);
        let ev = er.replay_next().unwrap();
        assert_eq!(ev.seq, 0);
        assert_eq!(ev.agent_id, "a1");
        let ev2 = er.replay_next().unwrap();
        assert_eq!(ev2.seq, 1);
        assert!(er.replay_next().is_none()); // end
    }

    #[test]
    fn test_replay_rewind_ff() {
        let mut er = ChronologicalReplay::new();
        er.record("a", "t", "p1");
        er.record("a", "t", "p2");
        er.record("a", "t", "p3");
        er.replay_next(); // cursor=1
        er.replay_next(); // cursor=2
        er.rewind(1); // cursor=1
        assert_eq!(er.cursor_pos(), 1);
        er.fast_forward(2); // cursor=3
        assert_eq!(er.cursor_pos(), 3);
        assert_eq!(er.remaining(), 0);
    }

    #[test]
    fn test_replay_seek() {
        let mut er = ChronologicalReplay::new();
        er.record("a", "t", "p1");
        er.record("a", "t", "p2");
        er.record("a", "t", "p3");
        er.seek(2);
        assert_eq!(er.cursor_pos(), 2);
    }

