    #[test]
    fn test_schema_backward_compat() {
        let mut sr = MsgSchemaRegistry::new();
        // v1: required=name
        sr.register("msg", vec![("name".into(), "string".into())], vec!["name".into()]);
        // v2: adds "email" but keeps "name" → backward compatible
        sr.register("msg", vec![("name".into(), "string".into()), ("email".into(), "string".into())], vec!["name".into()]);
        assert_eq!(sr.check_compat("msg"), SchemaCompat::Full);
    }

    #[test]
    fn test_schema_breaking_change() {
        let mut sr = MsgSchemaRegistry::new();
        // v1: required=name,age
        sr.register("msg", vec![("name".into(), "string".into()), ("age".into(), "int".into())], vec!["name".into(), "age".into()]);
        // v2: removes "age" entirely → not backward compatible (old required field missing)
        sr.register("msg", vec![("name".into(), "string".into())], vec!["name".into()]);
        // backward: v2 must have all required from v1 → "age" missing → false
        // forward: v1 must have all required from v2 → "name" present → true
        assert_eq!(sr.check_compat("msg"), SchemaCompat::Forward);
    }

    #[test]
    fn test_schema_validate() {
        let mut sr = MsgSchemaRegistry::new();
        sr.register("event", vec![("id".into(), "string".into()), ("ts".into(), "int".into())], vec!["id".into()]);
        assert!(sr.validate("event", &["id", "ts"]));
        assert!(sr.validate("event", &["id"])); // has required
        assert!(!sr.validate("event", &["ts"])); // missing required "id"
    }

    #[test]
    fn test_schema_evolution_history() {
        let mut sr = MsgSchemaRegistry::new();
        sr.register("x", vec![("a".into(), "int".into())], vec!["a".into()]);
        sr.register("x", vec![("a".into(), "int".into()), ("b".into(), "str".into())], vec!["a".into()]);
        let hist = sr.evolution_history("x");
        assert_eq!(hist.len(), 2);
        assert_eq!(hist[0], (1, 1, 1));
        assert_eq!(hist[1], (2, 2, 1));
    }

