    #[test]
    fn test_migration_lifecycle() {
        let mut lm = LiveMigrator::new();
        let id = lm.plan("agent-1", "slot-a", "slot-b", vec!["state".into(), "config".into()]);
        assert_eq!(lm.get(&id).unwrap().phase, MigrationPhase::Planning);
        assert!(lm.start_precopy(&id));
        assert_eq!(lm.get(&id).unwrap().phase, MigrationPhase::PreCopy);
        assert!(lm.copy_key(&id, "state"));
        assert!((lm.progress(&id).unwrap() - 0.5).abs() < 0.01);
        assert!(lm.copy_key(&id, "config"));
        assert!((lm.progress(&id).unwrap() - 1.0).abs() < 0.01);
        assert!(lm.start_postcopy(&id));
        assert!(lm.complete(&id, 15));
        assert_eq!(lm.get(&id).unwrap().phase, MigrationPhase::Completed);
        assert_eq!(lm.get(&id).unwrap().downtime_ms, 15);
    }

