    #[test]
    fn test_ts_push_and_range() {
        let mut ts = TsStore::new(3600);
        ts.push("cpu", 50.0);
        ts.push("cpu", 60.0);
        ts.push("cpu", 70.0);
        let points = ts.range("cpu", 2);
        assert_eq!(points.len(), 2);
        assert!((points[0].value - 60.0).abs() < 0.01);
        assert!((points[1].value - 70.0).abs() < 0.01);
    }

    #[test]
    fn test_ts_aggregate() {
        let mut ts = TsStore::new(3600);
        ts.push("m", 10.0);
        ts.push("m", 20.0);
        ts.push("m", 30.0);
        let (min, max, avg, sum) = ts.aggregate("m", 100).unwrap();
        assert!((min - 10.0).abs() < 0.01);
        assert!((max - 30.0).abs() < 0.01);
        assert!((avg - 20.0).abs() < 0.01);
        assert!((sum - 60.0).abs() < 0.01);
    }

    #[test]
    fn test_ts_downsample() {
        let mut ts = TsStore::new(3600);
        for i in 0..10 { ts.push("x", i as f64); }
        let ds = ts.downsample("x", 5);
        assert_eq!(ds.len(), 2);
        assert!((ds[0] - 2.0).abs() < 0.01); // avg(0,1,2,3,4) = 2.0
        assert!((ds[1] - 7.0).abs() < 0.01); // avg(5,6,7,8,9) = 7.0
    }

    #[test]
    fn test_ts_anomaly_band() {
        let mut ts = TsStore::new(3600);
        for _ in 0..20 { ts.push("stable", 100.0); }
        let (lo, hi) = ts.anomaly_band("stable", 20).unwrap();
        // All same value → std_dev=0 → band = [100, 100]
        assert!((lo - 100.0).abs() < 0.01);
        assert!((hi - 100.0).abs() < 0.01);
    }

    #[test]
    fn test_ts_series_count() {
        let mut ts = TsStore::new(3600);
        ts.push("a", 1.0);
        ts.push("b", 2.0);
        assert_eq!(ts.series_count(), 2);
        assert_eq!(ts.point_count("a"), 1);
    }

