    // ── Backpressure Controller ──

    #[test]
    fn test_backpressure_state_transitions() {
        let mut reg = FlowCtrlRegistry::new();
        reg.register("q1", 80, 40); // high=80, low=40 (queue depth)
        // Initially Normal
        let ctrl = reg.get("q1").unwrap();
        assert_eq!(ctrl.state, BackpressureState::Normal);
        assert!(ctrl.should_accept());

        // Push above low but below high → Throttled
        reg.update("q1", 60);
        assert_eq!(reg.get("q1").unwrap().state, BackpressureState::Throttled);

        // Push to high watermark → Blocked
        reg.update("q1", 80);
        assert_eq!(reg.get("q1").unwrap().state, BackpressureState::Blocked);
        assert!(!reg.get("q1").unwrap().should_accept());

        // Drop below low watermark → Normal
        reg.update("q1", 30);
        assert_eq!(reg.get("q1").unwrap().state, BackpressureState::Normal);
    }

    #[test]
    fn test_backpressure_adaptive_rate() {
        let mut reg = FlowCtrlRegistry::new();
        reg.register("q1", 80, 40);
        let ctrl = reg.get("q1").unwrap();
        // Normal state → rate_limit = 1.0
        assert!((ctrl.rate_limit - 1.0).abs() < 0.01);

        reg.update("q1", 60); // between low(40) and high(80) → Throttled
        let ctrl = reg.get("q1").unwrap();
        // Throttled → rate_limit < 1.0
        assert!(ctrl.rate_limit < 1.0);
    }

    #[test]
    fn test_backpressure_signals_count() {
        let mut reg = FlowCtrlRegistry::new();
        reg.register("q1", 50, 20);
        reg.update("q1", 30); // above low(20), below high(50) → Throttled, signal
        reg.update("q1", 10); // back to normal
        reg.update("q1", 30); // Throttled again, signal
        assert!(reg.get("q1").unwrap().signals_sent >= 2);
    }

    #[test]
    fn test_backpressure_list_queues() {
        let mut reg = FlowCtrlRegistry::new();
        reg.register("a", 80, 40);
        reg.register("b", 90, 50);
        assert_eq!(reg.list().len(), 2);
    }

    #[test]
    fn test_backpressure_unknown_queue() {
        let reg = FlowCtrlRegistry::new();
        assert!(reg.get("nonexistent").is_none());
    }

    // ── Consistent Hash Ring ──

    #[test]
    fn test_hashring_add_and_lookup() {
        let mut ring = HashRing::new(3, 1); // 3 vnodes, replication=1
        ring.add_node("node-A");
        ring.add_node("node-B");
        // Any key should resolve to some node
        let node = ring.lookup("my-key");
        assert!(node.is_some());
        let n = node.unwrap();
        assert!(n == "node-A" || n == "node-B");
    }

    #[test]
    fn test_hashring_remove_node() {
        let mut ring = HashRing::new(3, 1);
        ring.add_node("node-A");
        ring.add_node("node-B");
        ring.remove_node("node-A");
        // All lookups should now go to node-B
        let node = ring.lookup("any-key").unwrap();
        assert_eq!(node, "node-B");
    }

    #[test]
    fn test_hashring_replicas() {
        let mut ring = HashRing::new(5, 3); // replication factor 3
        ring.add_node("n1");
        ring.add_node("n2");
        ring.add_node("n3");
        let replicas = ring.lookup_replicas("key1");
        assert_eq!(replicas.len(), 3);
        // All replicas should be distinct
        let mut deduped = replicas.clone();
        deduped.sort();
        deduped.dedup();
        assert_eq!(deduped.len(), 3);
    }

    #[test]
    fn test_hashring_empty() {
        let ring = HashRing::new(3, 1);
        assert!(ring.lookup("key").is_none());
        assert!(ring.lookup_replicas("key").is_empty());
    }

    #[test]
    fn test_hashring_single_node_replicas() {
        let mut ring = HashRing::new(5, 3);
        ring.add_node("only-node");
        // With 1 node, replicas returns just that node (can't have 3 distinct)
        let replicas = ring.lookup_replicas("key1");
        assert_eq!(replicas.len(), 1);
        assert_eq!(replicas[0], "only-node");
    }

