    #[test]
    fn test_policy_default_allow() {
        let mut pe = AgentPolicyEngine::new();
        let decision = pe.evaluate("any-agent", "any-action");
        assert_eq!(decision, PolicyDecision::Allow);
    }

    #[test]
    fn test_policy_deny_rule() {
        let mut pe = AgentPolicyEngine::new();
        pe.add_rule("block-delete", "*", "delete", PolicyDecision::Deny, 10, false);
        let decision = pe.evaluate("agent-1", "delete");
        assert_eq!(decision, PolicyDecision::Deny);
    }

    #[test]
    fn test_policy_priority_ordering() {
        let mut pe = AgentPolicyEngine::new();
        pe.add_rule("allow-all", "*", "*", PolicyDecision::Allow, 1, false);
        pe.add_rule("deny-delete", "*", "delete", PolicyDecision::Deny, 10, false);
        // Higher priority deny should win
        let decision = pe.evaluate("agent-1", "delete");
        assert_eq!(decision, PolicyDecision::Deny);
    }

    #[test]
    fn test_policy_dry_run() {
        let mut pe = AgentPolicyEngine::new();
        pe.add_rule("dry-deny", "*", "write", PolicyDecision::Deny, 10, true);
        // Dry-run logs but doesn't enforce → falls through to default Allow
        let decision = pe.evaluate("agent-1", "write");
        assert_eq!(decision, PolicyDecision::Allow);
        // But it should be in audit log
        assert_eq!(pe.audit_log().len(), 1);
    }

    #[test]
    fn test_policy_audit_and_clear() {
        let mut pe = AgentPolicyEngine::new();
        pe.add_rule("r1", "*", "*", PolicyDecision::Allow, 1, false);
        pe.evaluate("a1", "read");
        pe.evaluate("a2", "write");
        assert_eq!(pe.audit_log().len(), 2);
        pe.clear_audit();
        assert!(pe.audit_log().is_empty());
    }

