    #[test]
    fn test_eventsource_snapshot_and_replay() {
        let mut es = EventSourceStore::new();
        es.append("agg-1", "init", "start");
        es.append("agg-1", "update", "mid");
        es.create_snapshot("agg-1", "state-at-v2");
        es.append("agg-1", "finalize", "end");

        let (snap, events) = es.replay_from_snapshot("agg-1");
        assert!(snap.is_some());
        let (v, data) = snap.unwrap();
        assert_eq!(v, 2);
        assert_eq!(data, "state-at-v2");
        // Only events after snapshot
        assert_eq!(events.len(), 1);
        assert_eq!(events[0].event_type, "finalize");
    }

