    // ── Semaphore Pool ──

    #[test]
    fn test_semaphore_acquire_and_release() {
        let mut sp = SemaphorePool::new();
        sp.create("gpu", 2);
        let p1 = sp.acquire("gpu", "a1").unwrap();
        let p2 = sp.acquire("gpu", "a2").unwrap();
        // Third should fail (max=2)
        assert!(sp.acquire("gpu", "a3").is_none());
        assert_eq!(sp.available("gpu"), Some(0));
        // Release one — a3 auto-granted from wait queue
        sp.release("gpu", p1);
        assert_eq!(sp.available("gpu"), Some(0)); // still full (a2 + auto-granted a3)
        let holders = sp.holders("gpu");
        assert_eq!(holders.len(), 2); // a2 + a3 (auto-granted)
    }

    #[test]
    fn test_semaphore_fifo_wait_queue() {
        let mut sp = SemaphorePool::new();
        sp.create("lock", 1);
        sp.acquire("lock", "first");
        sp.acquire("lock", "second"); // goes to wait queue
        sp.acquire("lock", "third"); // goes to wait queue
        assert_eq!(sp.waiting("lock"), Some(2));
    }

    #[test]
    fn test_semaphore_available() {
        let mut sp = SemaphorePool::new();
        sp.create("res", 3);
        assert_eq!(sp.available("res"), Some(3));
        sp.acquire("res", "a1");
        assert_eq!(sp.available("res"), Some(2));
    }

    #[test]
    fn test_semaphore_list() {
        let mut sp = SemaphorePool::new();
        sp.create("a", 2);
        sp.create("b", 5);
        assert_eq!(sp.list().len(), 2);
    }

    #[test]
    fn test_semaphore_unknown() {
        let sp = SemaphorePool::new();
        assert!(sp.available("x").is_none());
    }

    // ── Saga Orchestrator ──

    #[test]
    fn test_saga_execute_all_steps() {
        let mut so = SagaOrchestrator::new();
        let id = so.create("order", vec![
            ("validate".into(), "check_stock".into(), "release_hold".into()),
            ("charge".into(), "debit_card".into(), "refund".into()),
        ]);
        let (name1, _) = so.execute_next(&id).unwrap();
        assert_eq!(name1, "validate");
        let (name2, _) = so.execute_next(&id).unwrap();
        assert_eq!(name2, "charge");
        assert_eq!(so.get_state(&id), Some(&SagaState::Completed));
    }

    #[test]
    fn test_saga_orch_fail_and_compensate() {
        let mut so = SagaOrchestrator::new();
        let id = so.create("tx", vec![
            ("s1".into(), "do1".into(), "undo1".into()),
            ("s2".into(), "do2".into(), "undo2".into()),
            ("s3".into(), "do3".into(), "undo3".into()),
        ]);
        so.execute_next(&id); // s1 completed
        so.execute_next(&id); // s2 completed
        // Fail at s2 — compensate s2 and s1
        let comps = so.fail_and_compensate(&id);
        assert_eq!(comps.len(), 2);
        assert_eq!(comps[0].0, "s2"); // reverse order
        assert_eq!(comps[1].0, "s1");
        assert_eq!(so.get_state(&id), Some(&SagaState::Failed));
    }

    #[test]
    fn test_saga_pending_state() {
        let mut so = SagaOrchestrator::new();
        let id = so.create("s", vec![("step".into(), "act".into(), "comp".into())]);
        assert_eq!(so.get_state(&id), Some(&SagaState::Pending));
    }

    #[test]
    fn test_saga_orch_list() {
        let mut so = SagaOrchestrator::new();
        so.create("a", vec![]);
        so.create("b", vec![]);
        assert_eq!(so.list().len(), 2);
    }

    #[test]
    fn test_saga_orch_no_steps() {
        let mut so = SagaOrchestrator::new();
        let id = so.create("empty", vec![]);
        // execute_next on pending with no steps → becomes Running then Completed
        assert!(so.execute_next(&id).is_none());
    }

