    // ── Voting Booth ──

    #[test]
    fn test_voting_majority_pass() {
        let mut vb = VotingBooth::new();
        let id = vb.create_proposal("upgrade", VoteStrategy::Majority, 2);
        vb.cast_vote(&id, "a1", VoteChoice::For);
        vb.cast_vote(&id, "a2", VoteChoice::For);
        vb.cast_vote(&id, "a3", VoteChoice::Against);
        assert_eq!(vb.tally(&id), VoteResult::Passed);
    }

    #[test]
    fn test_voting_majority_fail() {
        let mut vb = VotingBooth::new();
        let id = vb.create_proposal("cut", VoteStrategy::Majority, 2);
        vb.cast_vote(&id, "a1", VoteChoice::Against);
        vb.cast_vote(&id, "a2", VoteChoice::Against);
        vb.cast_vote(&id, "a3", VoteChoice::For);
        assert_eq!(vb.tally(&id), VoteResult::Failed);
    }

    #[test]
    fn test_voting_no_quorum() {
        let mut vb = VotingBooth::new();
        let id = vb.create_proposal("thing", VoteStrategy::Majority, 5);
        vb.cast_vote(&id, "a1", VoteChoice::For);
        assert_eq!(vb.tally(&id), VoteResult::NoQuorum);
    }

    #[test]
    fn test_voting_no_double_vote() {
        let mut vb = VotingBooth::new();
        let id = vb.create_proposal("p", VoteStrategy::Majority, 1);
        assert!(vb.cast_vote(&id, "a1", VoteChoice::For));
        assert!(!vb.cast_vote(&id, "a1", VoteChoice::Against)); // double vote rejected
    }

    #[test]
    fn test_voting_unanimous() {
        let mut vb = VotingBooth::new();
        let id = vb.create_proposal("consensus", VoteStrategy::Unanimous, 2);
        vb.cast_vote(&id, "a1", VoteChoice::For);
        vb.cast_vote(&id, "a2", VoteChoice::For);
        assert_eq!(vb.tally(&id), VoteResult::Passed);
        // Add one against
        let id2 = vb.create_proposal("consensus2", VoteStrategy::Unanimous, 2);
        vb.cast_vote(&id2, "a1", VoteChoice::For);
        vb.cast_vote(&id2, "a2", VoteChoice::Against);
        assert_eq!(vb.tally(&id2), VoteResult::Failed);
    }

