    // TaskDepGraph tests
    #[test]
    fn test_depgraph_topo_sort() {
        let mut g = TaskDepGraph::new();
        g.add_node("a", "task A");
        g.add_node("b", "task B");
        g.add_node("c", "task C");
        g.add_edge("a", "b");
        g.add_edge("b", "c");
        let order = g.topo_sort();
        let ai = order.iter().position(|x| x == "a").unwrap();
        let bi = order.iter().position(|x| x == "b").unwrap();
        let ci = order.iter().position(|x| x == "c").unwrap();
        assert!(ai < bi);
        assert!(bi < ci);
    }

    #[test]
    fn test_depgraph_cycle_reject() {
        let mut g = TaskDepGraph::new();
        g.add_node("a", "A");
        g.add_node("b", "B");
        assert!(g.add_edge("a", "b"));
        assert!(!g.add_edge("b", "a")); // cycle — rejected
    }

    #[test]
    fn test_depgraph_ready_set() {
        let mut g = TaskDepGraph::new();
        g.add_node("a", "A");
        g.add_node("b", "B");
        g.add_edge("a", "b");
        let ready = g.ready_set();
        assert!(ready.contains(&"a".to_string()));
        assert!(!ready.contains(&"b".to_string()));
    }

    #[test]
    fn test_depgraph_mark_done() {
        let mut g = TaskDepGraph::new();
        g.add_node("a", "A");
        g.add_node("b", "B");
        g.add_edge("a", "b");
        g.mark_done("a");
        let ready = g.ready_set();
        assert!(ready.contains(&"b".to_string()));
    }

    #[test]
    fn test_depgraph_list() {
        let mut g = TaskDepGraph::new();
        g.add_node("x", "X");
        g.add_node("y", "Y");
        assert_eq!(g.list().len(), 2);
    }

