    // RetryStrategyEngine tests
    #[test]
    fn test_retry_record_attempt() {
        let mut re = RetryStrategyEngine::new();
        re.register("fetch", RetryStrategyPolicy {
            max_attempts: 3, base_delay_ms: 100, backoff_multiplier: 2.0, jitter: false,
        });
        let delay = re.record_attempt("fetch", 0, "timeout").unwrap();
        assert_eq!(delay, 100); // 100 * 2^0
    }

    #[test]
    fn test_retry_backoff_increases() {
        let mut re = RetryStrategyEngine::new();
        re.register("fetch", RetryStrategyPolicy {
            max_attempts: 5, base_delay_ms: 100, backoff_multiplier: 2.0, jitter: false,
        });
        let d0 = re.record_attempt("fetch", 0, "e").unwrap();
        let d1 = re.record_attempt("fetch", 1, "e").unwrap();
        assert!(d1 > d0);
    }

    #[test]
    fn test_retry_exhausted() {
        let mut re = RetryStrategyEngine::new();
        re.register("op", RetryStrategyPolicy {
            max_attempts: 2, base_delay_ms: 50, backoff_multiplier: 1.5, jitter: false,
        });
        re.record_attempt("op", 0, "e");
        re.record_attempt("op", 1, "e");
        assert!(re.exhausted("op"));
    }

    #[test]
    fn test_retry_max_attempts_none() {
        let mut re = RetryStrategyEngine::new();
        re.register("op", RetryStrategyPolicy {
            max_attempts: 2, base_delay_ms: 50, backoff_multiplier: 1.0, jitter: false,
        });
        assert!(re.record_attempt("op", 2, "e").is_none()); // attempt >= max
    }

