    // ── Round 43: PrioQueueMgr ──────────────────────────────────────

    #[test]
    fn test_prioq_push_pop() {
        let mut pq = PrioQueueMgr::new();
        pq.push(5, "low");
        pq.push(10, "high");
        let item = pq.pop().unwrap();
        assert_eq!(item.payload, "high"); // higher priority first
    }

    #[test]
    fn test_prioq_aging() {
        let mut pq = PrioQueueMgr::new();
        pq.push(1, "old");
        pq.push(5, "new");
        for _ in 0..10 { pq.age_all(); }
        // "old" now has effective priority 1+10=11 > 5+10=15... wait both age
        // Actually both age equally. "old" = 1+10=11, "new" = 5+10=15, so "new" still wins
        let item = pq.pop().unwrap();
        assert_eq!(item.payload, "new");
    }

    #[test]
    fn test_prioq_reprioritize() {
        let mut pq = PrioQueueMgr::new();
        let id = pq.push(1, "low");
        pq.push(10, "high");
        pq.reprioritize(&id, 20);
        let item = pq.pop().unwrap();
        assert_eq!(item.payload, "low"); // now priority 20
    }

    #[test]
    fn test_prioq_empty_pop() {
        let mut pq = PrioQueueMgr::new();
        assert!(pq.pop().is_none());
    }

    #[test]
    fn test_prioq_len() {
        let mut pq = PrioQueueMgr::new();
        pq.push(1, "a");
        pq.push(2, "b");
        assert_eq!(pq.len(), 2);
        pq.pop();
        assert_eq!(pq.len(), 1);
    }

