    // ── Round 44: DependencyResolver ────────────────────────────────

    #[test]
    fn test_depresolve_linear() {
        let mut dr = DependencyResolver::new();
        dr.add("c", &["b"]);
        dr.add("b", &["a"]);
        dr.add("a", &[]);
        let order = dr.resolve().unwrap();
        let pa = order.iter().position(|x| x == "a").unwrap();
        let pb = order.iter().position(|x| x == "b").unwrap();
        let pc = order.iter().position(|x| x == "c").unwrap();
        assert!(pa < pb && pb < pc);
    }

    #[test]
    fn test_depresolve_cycle() {
        let mut dr = DependencyResolver::new();
        dr.add("a", &["b"]);
        dr.add("b", &["a"]);
        assert!(dr.resolve().is_err());
    }

