    fn test_depresolve_no_deps() {
        let mut dr = DependencyResolver::new();
        dr.add("standalone", &[]);
        let order = dr.resolve().unwrap();
        assert_eq!(order, vec!["standalone"]);
    }

    #[test]
    fn test_depresolve_diamond() {
        let mut dr = DependencyResolver::new();
        dr.add("d", &["b", "c"]);
        dr.add("b", &["a"]);
        dr.add("c", &["a"]);
        dr.add("a", &[]);
        let order = dr.resolve().unwrap();
        let pa = order.iter().position(|x| x == "a").unwrap();
        let pd = order.iter().position(|x| x == "d").unwrap();
        assert!(pa < pd);
    }

