    #[test]
    fn test_gossip_sync_spread() {
        let mut g = GossipSyncMgr::new();
        g.add_peer("p1");
        g.spread("r1", "hello", "origin");
        assert_eq!(g.list().len(), 1);
        assert_eq!(g.get("r1").unwrap().payload, "hello");
    }

    #[test]
    fn test_gossip_sync_tick_convergence() {
        let mut g = GossipSyncMgr::new();
        g.add_peer("p1");
        g.add_peer("p2");
        g.spread("r1", "data", "p1");
        assert!(!g.converged("r1"));
        g.tick();
        assert!(g.converged("r1"));
    }

    #[test]
    fn test_gossip_sync_remove_peer() {
        let mut g = GossipSyncMgr::new();
        g.add_peer("p1");
        g.add_peer("p2");
        g.remove_peer("p1");
        g.spread("r1", "x", "p2");
        g.tick();
        assert!(g.converged("r1"));
    }

    #[test]
    fn test_gossip_sync_no_duplicate_peer() {
        let mut g = GossipSyncMgr::new();
        g.add_peer("p1");
        g.add_peer("p1");
        assert_eq!(g.peers.len(), 1);
    }

