    #[test]
    fn test_tbucket_capacity_cap() {
        let mut tb = TBucketLimiter::new();
        tb.register("x", 5.0, 1000.0); // high refill
        tb.try_consume("x", 3.0);
        // After refill, should not exceed capacity
        std::thread::sleep(std::time::Duration::from_millis(10));
        assert!(tb.try_consume("x", 1.0));
        assert!(tb.tokens("x").unwrap() <= 5.0);
    }

