    #[test]
    fn test_consensus_quorum_majority() {
        let mut cq = ConsensusQuorum::new();
        cq.propose("p1", QuorumMode::Majority, 3);
        cq.vote("p1", "a", true);
        cq.vote("p1", "b", true);
        assert!(cq.result("p1").is_none()); // need 3 votes
        cq.vote("p1", "c", false);
        assert_eq!(cq.result("p1"), Some(true)); // 2/3 majority
    }

    #[test]
    fn test_consensus_quorum_unanimous() {
        let mut cq = ConsensusQuorum::new();
        cq.propose("p1", QuorumMode::Unanimous, 3);
        cq.vote("p1", "a", true);
        cq.vote("p1", "b", true);
        cq.vote("p1", "c", false);
        assert_eq!(cq.result("p1"), Some(false));
    }

