    // NotificationRouter tests
    #[test]
    fn test_notif_router_add_and_route() {
        let mut nr = NotificationRouter::new();
        nr.add_route("error", "*", "pager");
        let channels = nr.route("error occurred", "high");
        assert_eq!(channels, vec!["pager"]);
    }

    #[test]
    fn test_notif_router_priority_filter() {
        let mut nr = NotificationRouter::new();
        nr.add_route("alert", "critical", "pager");
        nr.add_route("alert", "*", "log");
        let c1 = nr.route("alert fired", "critical");
        assert_eq!(c1.len(), 2); // both match
        let c2 = nr.route("alert fired", "low");
        assert_eq!(c2, vec!["log"]); // only wildcard matches
    }

    #[test]
    fn test_notif_router_remove_route() {
        let mut nr = NotificationRouter::new();
        nr.add_route("err", "*", "slack");
        nr.add_route("warn", "*", "email");
        assert_eq!(nr.len(), 2);
        nr.remove_route("err");
        assert_eq!(nr.len(), 1);
        assert!(nr.route("err happened", "info").is_empty());
    }

