    // IdempotencyKeyStore tests
    #[test]
    fn test_idemp_key_check_set() {
        let mut ik = IdempotencyKeyStore::new();
        assert!(ik.check_and_set_at("req-1", 100, 60));
        assert!(!ik.check_and_set_at("req-1", 100, 60)); // duplicate
    }

    #[test]
    fn test_idemp_key_expiry() {
        let mut ik = IdempotencyKeyStore::new();
        ik.check_and_set_at("req-1", 100, 60);
        assert!(ik.contains("req-1"));
        ik.clear_expired_at(200); // past expiry (100+60=160)
        assert!(!ik.contains("req-1"));
    }

    #[test]
    fn test_idemp_key_len() {
        let mut ik = IdempotencyKeyStore::new();
        ik.check_and_set_at("a", 100, 300);
        ik.check_and_set_at("b", 100, 300);
        assert_eq!(ik.len(), 2);
    }

    #[test]
    fn test_idemp_key_reuse_after_expiry() {
        let mut ik = IdempotencyKeyStore::new();
        ik.check_and_set_at("req-1", 100, 10);
        assert!(!ik.check_and_set_at("req-1", 105, 10)); // still alive
        assert!(ik.check_and_set_at("req-1", 200, 10)); // expired, can reuse
    }

    #[test]
    fn test_idemp_key_different_keys() {
        let mut ik = IdempotencyKeyStore::new();
        assert!(ik.check_and_set_at("a", 100, 60));
        assert!(ik.check_and_set_at("b", 100, 60));
        assert!(!ik.check_and_set_at("a", 100, 60));
    }

