    // VersionVector tests
    #[test]
    fn test_vvec_increment() {
        let mut vv = VersionVector::new();
        vv.increment("node-a");
        vv.increment("node-a");
        assert_eq!(vv.get("node-a"), 2);
    }

    #[test]
    fn test_vvec_merge() {
        let mut v1 = VersionVector::new();
        v1.increment("a");
        v1.increment("a");
        let mut v2 = VersionVector::new();
        v2.increment("a");
        v2.increment("b");
        v1.merge(&v2);
        assert_eq!(v1.get("a"), 2); // max(2,1)
        assert_eq!(v1.get("b"), 1);
    }

    #[test]
    fn test_vvec_dominates() {
        let mut v1 = VersionVector::new();
        v1.increment("a");
        v1.increment("b");
        let mut v2 = VersionVector::new();
        v2.increment("a");
        assert!(v1.dominates(&v2));
        assert!(!v2.dominates(&v1));
    }

    #[test]
    fn test_vvec_concurrent() {
        let mut v1 = VersionVector::new();
        v1.increment("a");
        let mut v2 = VersionVector::new();
        v2.increment("b");
        assert!(v1.concurrent_with(&v2));
    }

