    // RetryPolicyRegistry tests
    #[test]
    fn test_retrypol_register_get() {
        let mut rp = RetryPolicyRegistry::new();
        rp.register("api_call", 5, 1000, 2.0);
        let (max, delay, mult) = rp.get_policy("api_call").unwrap();
        assert_eq!(max, 5);
        assert_eq!(delay, 1000);
        assert!((mult - 2.0).abs() < 0.001);
    }

    #[test]
    fn test_retrypol_delay() {
        let mut rp = RetryPolicyRegistry::new();
        rp.register("t", 3, 100, 2.0);
        assert_eq!(rp.delay_for_attempt("t", 0), Some(100)); // 100 * 2^0
        assert_eq!(rp.delay_for_attempt("t", 1), Some(200)); // 100 * 2^1
        assert_eq!(rp.delay_for_attempt("t", 2), Some(400)); // 100 * 2^2
    }

    #[test]
    fn test_retrypol_should_retry() {
        let mut rp = RetryPolicyRegistry::new();
        rp.register("t", 3, 100, 2.0);
        assert!(rp.should_retry("t", 0));
        assert!(rp.should_retry("t", 2));
        assert!(!rp.should_retry("t", 3)); // at max
    }

    #[test]
    fn test_retrypol_remove() {
        let mut rp = RetryPolicyRegistry::new();
        rp.register("t", 3, 100, 2.0);
        rp.remove("t");
        assert!(rp.get_policy("t").is_none());
    }

    #[test]
    fn test_retrypol_unknown() {
        let rp = RetryPolicyRegistry::new();
        assert!(rp.get_policy("none").is_none());
        assert!(!rp.should_retry("none", 0));
    }

